import { component$, Slot, useStyles$ } from "@qwik.dev/core";
import styles from "./instrument-motion.css?inline";

export type InstrumentMotionState = "rest" | "open" | "compare" | "arrive";
export type InstrumentMotionPartKind = "source" | "alternative" | "result";

export interface InstrumentMotionProps {
  /** Use rest for restored content. Change state only for an actual interaction. */
  state?: InstrumentMotionState;
  /** Pass true while writing, in Zen, or when the host is outside the viewport. */
  quiet?: boolean;
  class?: string;
}

/**
 * Finite feedback only: no timers, document listeners, or perpetual loader.
 * This wrapper never manages visibility or delays interaction with its children.
 */
export const InstrumentMotion = component$<InstrumentMotionProps>((props) => {
  useStyles$(styles);
  return (
    <div
      class={["instrument-motion", props.class]}
      data-instrument-motion={props.state ?? "rest"}
      data-instrument-quiet={props.quiet ? "true" : undefined}
    >
      <Slot />
    </div>
  );
});

/** Mark the real comparison/result content, not a decorative stand-in. */
export const InstrumentMotionPart = component$<{
  part: InstrumentMotionPartKind;
  class?: string;
}>((props) => (
  <div class={props.class} data-instrument-part={props.part}>
    <Slot />
  </div>
));
.instrument-motion {
  --instrument-ease: cubic-bezier(0.22, 1, 0.36, 1);
}

/* Content starts fully visible. Animation never gates a control or a result. */
@media (prefers-reduced-motion: no-preference) {
  .instrument-motion[data-instrument-motion="open"] .instrument-art__image {
    animation: instrument-open 220ms var(--instrument-ease);
  }

  .instrument-motion[data-instrument-motion="compare"]
    [data-instrument-part="alternative"] {
    animation: instrument-compare 200ms var(--instrument-ease);
  }

  .instrument-motion[data-instrument-motion="arrive"]
    [data-instrument-part="result"] {
    animation: instrument-result 240ms var(--instrument-ease);
  }

  .instrument-motion[data-instrument-motion="arrive"] .instrument-art__rule {
    animation: instrument-rule 260ms var(--instrument-ease);
  }
}

@keyframes instrument-open {
  from {
    opacity: 0.6;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes instrument-compare {
  from {
    opacity: 0.6;
    transform: translateX(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes instrument-result {
  from {
    opacity: 0.5;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes instrument-rule {
  from {
    opacity: 0.5;
    transform: scaleX(0.3);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* The host passes quiet for its exact typing/visibility state. Existing ambient
 * flow and Zen containers are supported as an additional, CSS-only safeguard. */
.instrument-motion[data-instrument-quiet="true"],
.instrument-motion[data-instrument-quiet="true"] *,
[data-flow="flow"] .instrument-motion,
[data-flow="flow"] .instrument-motion *,
[data-flow="settling"] .instrument-motion,
[data-flow="settling"] .instrument-motion *,
[data-zen="true"] .instrument-motion,
[data-zen="true"] .instrument-motion *,
.zen-mode .instrument-motion,
.zen-mode .instrument-motion * {
  animation: none !important;
  transition: none !important;
}

@media (prefers-reduced-motion: reduce) {
  .instrument-motion,
  .instrument-motion * {
    animation: none !important;
    transition: none !important;
  }
}

