  transform: translateY(1px);
  box-shadow: none;
}

.dossier-action-pending {
  position: relative;
  border-color: var(--color-vermilion);
}

@media (prefers-reduced-motion: no-preference) {
  .dossier-action-pending::after {
    content: "";
    position: absolute;
    inset: -3px;
    border: 1px solid var(--color-vermilion);
    border-radius: 4px;
    pointer-events: none;
    animation: dossier-action-pulse 2.8s ease-in-out infinite;
  }
}

@keyframes dossier-action-pulse {
  0%,
  100% {
    opacity: 0;
    transform: scale(1);
