/* Small icon-only control — consistent hit target + accessible focus */
.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.75rem;
  min-height: 1.75rem;
  border-radius: 2px;
  color: var(--color-ink-muted);
