.tool-btn {
  padding: 0.25rem 0.5rem;
  font-size: 0.875rem;
  color: var(--color-ink-light);
  border-radius: 2px;
  transition:
    color 0.15s ease,
    background 0.15s ease,
    transform 0.1s ease;
  cursor: pointer;
