// Damped spring step response sampled into a CSS linear() easing.
function spring({ zeta, omega, samples = 32, duration }) {
  const wd = omega * Math.sqrt(1 - zeta * zeta);
  const x = (t) =>
    1 - Math.exp(-zeta * omega * t) * (Math.cos(wd * t) + ((zeta * omega) / wd) * Math.sin(wd * t));
  const pts = [];
  for (let i = 0; i <= samples; i++) {
    const t = (i / samples) * duration;
    pts.push(i === samples ? 1 : +x(t).toFixed(4));
  }
  // Drop near-collinear points.
  const out = [];
  pts.forEach((v, i) => {
    const pct = ((i / samples) * 100).toFixed(1).replace(/\.0$/, "");
    out.push(i === 0 || i === samples ? `${v}` : `${v} ${pct}%`);
  });
  const peak = Math.max(...pts);
  return { css: `linear(${out.join(", ")})`, overshoot: ((peak - 1) * 100).toFixed(1) + "%" };
}
