import { component$ } from "@qwik.dev/core";
import { CONSEQUENCE_LABELS, type Consequence } from "../../utils/consequence";

interface DestinationTagProps {
  /** Where the action's words or data go. */
  to: Consequence;
  /** Replaces the short visible word, e.g. a provider's name. */
  label?: string;
  /** Replaces the long, spoken description. */
  description?: string;
  /** Softer, for a tag repeated down a list. */
  quiet?: boolean;
  class?: string;
}

/**
 * A typewritten docket saying where an action sends things. The mark's ink and
 * shape follow the destination (hollow for the device, struck for erasing), and
 * the word is always there, so colour is never the only cue. Screen readers get
 * the long form instead of the abbreviation.
 */
export const DestinationTag = component$<DestinationTagProps>((props) => {
  const labels = CONSEQUENCE_LABELS[props.to];
  const long = props.description ?? labels.long;
  return (
    <span
      class={[
        "destination-tag",
        { "destination-tag--quiet": props.quiet },
        props.class,
      ]}
      data-consequence={props.to}
      title={long}
    >
      <span class="destination-tag__mark" aria-hidden="true" />
      <span aria-hidden="true">{props.label ?? labels.short}</span>
      <span class="sr-only">{long}</span>
    </span>
  );
});

/**
 * The platen behind <HoldToConfirm>: tracks a press-and-hold on one element
 * and writes its progress to `--press-progress`, so the ink fill is driven by
 * a single custom property rather than a re-render per frame.
 */

interface ActiveHold {
  frame: number;
  started: number;
}

const holds = new WeakMap<HTMLElement, ActiveHold>();

export interface HoldOptions {
  /** How long the press must be held. */
  durationMs: number;
  /** Called once, when the platen reaches the bed. */
  onCommit: () => void;
}

/** Start a hold on `element`. A second call while one runs is ignored. */
export function beginHold(element: HTMLElement, options: HoldOptions): void {
  if (holds.has(element)) return;
  const hold: ActiveHold = { frame: 0, started: performance.now() };
  holds.set(element, hold);
  element.setAttribute("data-holding", "");
  element.removeAttribute("data-committed");

  const tick = (now: number) => {
    if (holds.get(element) !== hold) return;
    const progress = Math.min(1, (now - hold.started) / options.durationMs);
    // Ease-in: the platen is slow to start and quick to land, so an
    // accidental tap barely marks the paper.
    element.style.setProperty("--press-progress", String(progress ** 1.6));
    if (progress >= 1) {
      holds.delete(element);
      element.removeAttribute("data-holding");
      element.setAttribute("data-committed", "");
      options.onCommit();
      return;
    }
    hold.frame = requestAnimationFrame(tick);
  };
  hold.frame = requestAnimationFrame(tick);
}

/** Release early: nothing happens, and the ink drains back. */
export function cancelHold(element: HTMLElement): void {
  const hold = holds.get(element);
  if (!hold) return;
  cancelAnimationFrame(hold.frame);
  holds.delete(element);
  element.removeAttribute("data-holding");
  element.style.setProperty("--press-progress", "0");
}

export function isHolding(element: HTMLElement): boolean {
  return holds.has(element);
}

import {
  $,
  component$,
  Slot,
  useSignal,
  useVisibleTask$,
  type PropFunction,
} from "@qwik.dev/core";
import type { Consequence } from "../../utils/consequence";
import { beginHold, cancelHold } from "../../utils/hold-press";
import { motionLevel } from "../../utils/motion";

interface HoldToConfirmProps {
  /** Runs once the hold completes (or on a confirmed keyboard press). */
  onConfirm$: PropFunction<() => void | Promise<void>>;
  /** Where the action sends things; tints the ink. Defaults to `erase`. */
  consequence?: Consequence;
  /** How long a pointer must hold. */
  holdMs?: number;
  /** Spoken and shown as the tooltip: what happens on completion. */
  label: string;
  /** The short instruction under the label, e.g. "hold to erase". */
  hint?: string;
  disabled?: boolean;
  class?: string;
}

/**
 * For actions that cannot be taken back from here. A pointer must hold the
 * control while the platen comes down; releasing early cancels and the ink
 * drains away. Keyboard and assistive tech take a two-step path instead (the
 * first Enter arms, the second confirms within a few seconds), so the guard
 * never depends on being able to hold a button steady.
 *
 * Reserve it for permanent losses. Recoverable actions are better served by
 * an undo, which interrupts no one.
 */
export const HoldToConfirm = component$<HoldToConfirmProps>((props) => {
  const button = useSignal<HTMLButtonElement>();
  const armed = useSignal(false);
  const holdMs = props.holdMs ?? 900;

  // A keyboard arm that is not confirmed lapses, so a stray Enter later on
  // cannot complete an old intention.
  useVisibleTask$(({ track, cleanup }) => {
    if (!track(() => armed.value)) return;
    const timer = window.setTimeout(() => (armed.value = false), 4000);
    cleanup(() => window.clearTimeout(timer));
  });

  const start = $((event: PointerEvent) => {
    const element = button.value;
    if (!element || props.disabled || event.button !== 0) return;
    if (event.pointerType === "mouse" || event.pointerType === "pen") {
      element.setPointerCapture(event.pointerId);
    }
    // With motion stilled the ink cannot show progress, so the hold is
    // shortened rather than made invisible; it still guards a slip.
    const duration = motionLevel() === "still" ? 450 : holdMs;
    beginHold(element, {
      durationMs: duration,
      onCommit: () => void props.onConfirm$(),
    });
  });

  const stop = $(() => {
    const element = button.value;
    if (element) cancelHold(element);
  });

  return (
    <button
      ref={button}
      type="button"
      class={["hold-to-confirm", props.class]}
      data-consequence={props.consequence ?? "erase"}
      data-armed={armed.value ? "" : undefined}
      disabled={props.disabled}
      title={props.label}
      aria-label={
        armed.value ? `${props.label}. Press again to confirm.` : props.label
      }
      onPointerDown$={start}
      onPointerUp$={stop}
      onPointerCancel$={stop}
      onPointerLeave$={stop}
      onClick$={async (event) => {
        // Pointer presses commit through the hold; a click with no pointer
        // behind it came from the keyboard or assistive tech.
        if (event.detail !== 0 || props.disabled) return;
        if (!armed.value) {
          armed.value = true;
          return;
        }
        armed.value = false;
        await props.onConfirm$();
      }}
      onKeyDown$={(event) => {
        if (event.key === "Escape") armed.value = false;
      }}
    >
      <span class="hold-to-confirm__ink" aria-hidden="true" />
      <Slot />
      {(props.hint || armed.value) && (
        <span class="hold-to-confirm__hint" aria-hidden="true">
          {armed.value ? "press again to confirm" : props.hint}
        </span>
      )}
    </button>
  );
});

