// Prove lane A in a real browser: wet ink, caret, selection, popover tags,
// section slug + drop rule, drop docket, desk lamp.
// Usage: env -u LD_LIBRARY_PATH node /tmp/twyne-juice/lane-a.mjs <outDir> [baseUrl]
import { chromium } from "/home/diogenes/.t3/worktrees/twyne/feat-living-press/node_modules/playwright/index.mjs";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const outDir = process.argv[2];
const base = process.argv[3] ?? "http://127.0.0.1:5190";
mkdirSync(outDir, { recursive: true });

const MANUSCRIPT =
  `<h1>The Salt Roads</h1>` +
  `<p>The traders weighed their loads by the handful and argued about the weather, as if the weather had ever listened to a trader.</p>` +
  `<p>By the fourth day the road forgot the sea entirely and turned inland, past terraces of thyme and the white ribs of abandoned pans.</p>` +
  `<p>Morgan kept the ledger. Every sack had a line, every line a price, and every price a story about who had been cheated last season.</p>` +
  `<h2>The inland markets</h2>` +
  `<p>Salt bought silence in the hill towns. A handful pressed into a magistrate's palm could close a dispute that had run for three generations.</p>` +
  `<h2>The rains</h2>` +
  `<p>When the rains came early the pans flooded and the price doubled overnight.</p>`;

const browser = await chromium.launch();
const context = await browser.newContext({
  viewport: { width: 1440, height: 900 },
  deviceScaleFactor: 1,
});
const page = await context.newPage();
const errors = [];
page.on("pageerror", (e) => errors.push(e.message));
await page.route(/\/api\/auth\//, (r) =>
  r.fulfill({ contentType: "application/json", body: "null" }),
);
await page.route("**/__juice-seed", (r) =>
  r.fulfill({ contentType: "text/html", body: "<!doctype html><title>Seed</title>" }),
);
await page.goto(`${base}/__juice-seed`);
await page.evaluate(async (html) => {
  const idb = await import(/* @vite-ignore */ "/src/utils/idb.ts");
  const now = Date.now();
  await idb.saveFoliosToIdb([
    { id: "f-a", name: "The Salt Roads", type: "draft", createdAt: now, updatedAt: now },
  ]);
  await idb.saveActiveFolioIdToIdb("f-a");
  await idb.saveFolioContentToIdb("f-a", html);
  await idb.saveMetaToIdb("live-review-enabled", false);
  await idb.saveMetaToIdb("signin-toast-dismissed", true);
  localStorage.setItem("living-desk-open", "false");
  localStorage.setItem(
    "twyne:editor:view:v1",
    JSON.stringify({ zenMode: false, compositorOpen: false }),
  );
  localStorage.setItem("twyne.appearance.motion", "full");
}, MANUSCRIPT);

await page.goto(`${base}/editor/`);
const pm = page.locator("#twyne-editor-mount .ProseMirror");
await pm.waitFor({ timeout: 90000 });
await page.evaluate(() => document.fonts.ready);
await page.waitForTimeout(2500);

const report = {};
report.motion = await page.evaluate(() => document.documentElement.dataset.motion);
report.caret = await pm.evaluate((el) => getComputedStyle(el).caretColor);
report.lamp = await page.evaluate(() => {
  const s = document.querySelector(".manuscript-scroller");
  return s
    ? {
        on: s.classList.contains("desk-lamp"),
        x: s.style.getPropertyValue("--lamp-x"),
        y: s.style.getPropertyValue("--lamp-y"),
        warmth: s.style.getPropertyValue("--lamp-warmth"),
        bg: getComputedStyle(s).backgroundImage.slice(0, 80),
      }
    : null;
});
await page.screenshot({ path: join(outDir, "a-editor-lamp.png") });

// Lean the lamp toward the pointer.
await page.mouse.move(1300, 700, { steps: 8 });
await page.waitForTimeout(1600);
report.lampLeaned = await page.evaluate(() => {
  const s = document.querySelector(".manuscript-scroller");
  return [s?.style.getPropertyValue("--lamp-x"), s?.style.getPropertyValue("--lamp-y")];
});
await page.screenshot({ path: join(outDir, "a-editor-lamp-leaned.png") });

// Wet ink: type, read the highlight registry, then wait for the save.
await pm.locator("p").nth(2).click();
await page.keyboard.press("End");
const typedAt = Date.now();
await page.keyboard.type(" The ledger kept its own counsel.", { delay: 35 });
await page.waitForTimeout(60);
report.typingAttr = await page.evaluate(() => document.documentElement.hasAttribute("data-typing"));
report.wetWhileTyping = await page.evaluate(() => {
  const h = CSS.highlights?.get("twyne-ink-wet");
  return h ? [...h].map((r) => r.toString()) : null;
});
await pm.locator("p").nth(2).screenshot({ path: join(outDir, "a-wet-ink.png") });
await page.screenshot({ path: join(outDir, "a-editor-typing.png") });
// Poll until the ink dries (the save lands).
let driedAfter = null;
for (let i = 0; i < 60; i++) {
  const state = await page.evaluate(() => ({
    wet: CSS.highlights?.has("twyne-ink-wet"),
    drying: CSS.highlights?.has("twyne-ink-drying"),
  }));
  if (!state.wet) {
    driedAfter = Date.now() - typedAt;
    report.dryingTone = state.drying;
    break;
  }
  await page.waitForTimeout(100);
}
report.driedAfterMs = driedAfter;
await pm.locator("p").nth(2).screenshot({ path: join(outDir, "a-ink-drying.png") });
await page.waitForTimeout(1800);
report.afterDry = await page.evaluate(() => ({
  wet: CSS.highlights?.has("twyne-ink-wet"),
  drying: CSS.highlights?.has("twyne-ink-drying"),
}));
report.typingCleared = await page.evaluate(() => !document.documentElement.hasAttribute("data-typing"));

// Selection: non-photo blue + popover with destination marks.
await page.mouse.click(5, 300);
const para = pm.locator("p").nth(3);
const box = await para.boundingBox();
await page.mouse.move(box.x + 4, box.y + 8);
await page.mouse.down();
await page.mouse.move(box.x + box.width * 0.75, box.y + 10, { steps: 14 });
await page.mouse.up();
await page.waitForTimeout(140);
await page.screenshot({ path: join(outDir, "a-selection-arriving.png") });
await page.waitForTimeout(500);
report.popover = await page.evaluate(() => {
  const el = document.querySelector(".selection-actions");
  if (!el) return null;
  return [...el.querySelectorAll(".selection-actions__row > button")].map((b) => ({
    label: b.textContent?.replace(/\s+/g, " ").trim(),
    consequence: b.getAttribute("data-consequence"),
    title: b.getAttribute("title"),
  }));
});
report.selectionBg = await page.evaluate(() => {
  const el = document.querySelector("#twyne-editor-mount .ProseMirror p");
  return el ? getComputedStyle(el, "::selection").backgroundColor : null;
});
await page.screenshot({ path: join(outDir, "a-selection.png") });
const pop = page.locator(".selection-actions");
if (await pop.count()) await pop.screenshot({ path: join(outDir, "a-selection-popover.png") });
// Open "Ask an editor" menu
const ask = page.locator('.selection-actions [data-menu-trigger="persona"]');
if (await ask.count()) {
  await ask.click();
  await page.waitForTimeout(400);
  await page.screenshot({ path: join(outDir, "a-ask-an-editor.png") });
  await page.keyboard.press("Escape");
}

// Section slug: hover a heading, then drag the handle over another heading.
await page.mouse.click(5, 300);
const h2 = pm.locator("h2").first();
await h2.scrollIntoViewIfNeeded();
await h2.hover();
await page.waitForTimeout(300);
const handle = h2.locator(".twyne-section-drag-handle");
report.handle = await handle.evaluate((el) => {
  const cs = getComputedStyle(el);
  return { opacity: cs.opacity, bg: cs.backgroundImage.slice(0, 40), translate: cs.translate };
}).catch((e) => e.message);
await h2.screenshot({ path: join(outDir, "a-section-slug.png") }).catch(() => {});
// Simulate a drag with DataTransfer so the drop rule renders.
report.dropRule = await page.evaluate(() => {
  const handle = document.querySelector("h2 .twyne-section-drag-handle");
  const target = document.querySelectorAll("#twyne-editor-mount .ProseMirror h2")[1];
  if (!handle || !target) return "missing";
  const dt = new DataTransfer();
  handle.dispatchEvent(new DragEvent("dragstart", { bubbles: true, dataTransfer: dt }));
  const r = target.getBoundingClientRect();
  target.dispatchEvent(
    new DragEvent("dragover", {
      bubbles: true,
      cancelable: true,
      dataTransfer: dt,
      clientX: r.left + 20,
      clientY: r.bottom - 2,
    }),
  );
  const rule = document.querySelector(".twyne-section-drop-rule");
  return rule
    ? { label: rule.getAttribute("data-section-drop-label"), placement: rule.dataset.sectionDropIndicator }
    : "no rule";
});
await page.waitForTimeout(300);
await page.screenshot({ path: join(outDir, "a-section-drop-rule.png") });
await page.evaluate(() => {
  document.querySelector("h2 .twyne-section-drag-handle")?.dispatchEvent(
    new DragEvent("dragend", { bubbles: true }),
  );
});

// File drop docket (offline route shows "kept in the manuscript").
report.dropDocket = await page.evaluate(async () => {
  const scroller = document.querySelector(".manuscript-scroller");
  const dt = new DataTransfer();
  dt.items.add(new File(["x"], "plate.png", { type: "image/png" }));
  scroller.dispatchEvent(
    new DragEvent("dragover", { bubbles: true, cancelable: true, dataTransfer: dt, clientX: 700, clientY: 400 }),
  );
  await new Promise((r) => setTimeout(r, 600));
  const docket = document.querySelector(".drag-overlay__docket");
  return docket ? docket.textContent.replace(/\s+/g, " ").trim() : "no docket";
});
await page.screenshot({ path: join(outDir, "a-drop-docket.png") });

console.log(JSON.stringify(report, null, 2));
console.log("errors", JSON.stringify(errors.slice(0, 8)));
await browser.close();

