  * frequency sets the budget, consequence has one ink per destination,
  * ambient motion carries data-ambient, and data-motion="still" stops it all.
  * ───────────────────────────────────────────────────────────── */
+
+:root {
+  --scrim: color-mix(in srgb, var(--color-ink) 55%, transparent);
+}
+.press-popover {
+  animation: press-slip-in var(--dur-arrive) var(--ease-slip) both;
+}
+.press-scrim {
+  background: var(--scrim);
+  animation: press-fade-in var(--dur-arrive) var(--ease-set) both;
+}
+.press-drawer {
+  transition: width var(--dur-settle) var(--ease-set);
+}
+.press-drawer-content {
+  transition:
+    opacity var(--dur-settle) var(--ease-set),
+    transform var(--dur-settle) var(--ease-set);
+}
+.press-drawer[data-open="false"] .press-drawer-content {
