+  background: var(--ink-public);
+  animation: press-slip-in var(--dur-arrive) var(--ease-slip) both;
+}
+.press-drawer-toggle svg {
+  transition: transform var(--dur-release) var(--ease-set);
+}
+.press-drawer-toggle[aria-expanded="true"] {
+  color: var(--color-vermilion);
+}
+.press-drawer-toggle[aria-expanded="true"] svg {
+  transform: rotate(90deg);
+}
+.press-sync-status {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.4em;
+  color: var(--consequence-ink);
+}
+.press-sync-mark {
+  width: 0.55em;
+  height: 0.55em;
+  border: 1px solid var(--consequence-ink);
+  border-radius: 50%;
+}
+.press-sync-status[data-consequence="synced"] .press-sync-mark {
+  background: var(--consequence-ink);
+}
+.press-sync-filed {
+  --flash-ink: var(--ink-synced);
+  animation: press-ink-flash var(--dur-settle) var(--ease-set);
+}
+.press-published {
+  --press-progress: 1;
+  color: var(--ink-public);
+  position: relative;
+  background: linear-gradient(
+    to right,
+    color-mix(in srgb, var(--ink-public) 25%, transparent)
+      calc(var(--press-progress) * 100%),
+    transparent 0
+  );
+  animation: press-publish var(--dur-ceremony) var(--ease-platen) both;
+}
+@keyframes press-publish {
+  from {
