+  }
+  to {
+    --press-progress: 1;
+  }
+}
+.press-hydration {
+  opacity: 0;
+  animation: press-fade-in var(--dur-arrive) var(--ease-set) 150ms both;
+}
+.press-type-slugs {
+  display: flex;
+  justify-content: center;
+  gap: 3px;
+  margin-top: 0.75rem;
+  animation: press-type-breathe var(--dur-breath) var(--ease-set) infinite;
+}
+.press-type-slugs i {
+  width: 0.5rem;
+  height: 0.2rem;
+  background: var(--color-ink-muted);
+}
+@keyframes press-type-breathe {
+  50% {
+    opacity: 0.35;
+  }
+}
+.press-signin-toast {
+  border-radius: 2px;
+  box-shadow: 0 14px 36px color-mix(in srgb, var(--shade) 28%, transparent);
+  animation: press-toast-in var(--dur-arrive) var(--ease-slip) both;
+}
+@keyframes press-toast-in {
+  from {
+    opacity: 0;
+    transform: translate(-50%, var(--lift-2));
+  }
+  to {
+    opacity: 1;
+    transform: translate(-50%, 0);
+  }
+}
+.press-masthead,
+.editor-compositor {
+  transition:
+    opacity var(--dur-settle) var(--ease-set),
+    transform var(--dur-settle) var(--ease-set),
+    display var(--dur-settle) allow-discrete;
+}
+.press-masthead[hidden],
+.editor-compositor[hidden] {
+  opacity: 0;
+  transform: translateY(calc(-1 * var(--lift-2)));
+}
+@starting-style {
+  .press-masthead:not([hidden]),
