+}
+
+.press-shortcut {
+  animation: press-fade-in var(--dur-arrive) var(--ease-set) both;
+}
+.editor-desk-controls {
+  transition:
+    opacity var(--dur-settle) var(--ease-set),
+    transform var(--dur-settle) var(--ease-set);
+}
+[data-flow="settling"] .press-masthead,
+[data-flow="flow"] .press-masthead,
+[data-flow="settling"] .editor-desk-controls,
+[data-flow="flow"] .editor-desk-controls {
+  transition:
+    opacity var(--dur-settle) var(--ease-set),
+    transform var(--dur-settle) var(--ease-set),
+    visibility var(--dur-settle) allow-discrete;
+}
+[data-flow="settling"] .editor-desk-controls {
+  opacity: 0.4;
+}
+[data-flow="flow"] .press-masthead,
+[data-flow="flow"] .editor-desk-controls {
+  transform: translateY(calc(-1 * var(--lift-2)));
+}

8607:[data-flow="settling"] .twyne-toolbar,
8634:[data-flow="flow"] .editor-desk-controls,
8644:[data-flow="settling"] .twyne-toolbar:hover {
   itself never moves. */
[data-flow="settling"] .editor-workspace-main > header,
[data-flow="settling"] .twyne-toolbar,
[data-flow="settling"] .in-flow-rails,
[data-flow="settling"] .flow-surface > :not(.flow-desk) {
  opacity: 0.4;
  transition: opacity 1.2s ease;
}
/* In flow the text-heavy margin goes: cards, tools, conversations. It is
   dismissed, not dimmed, so nothing invisible keeps focus or the pointer.
   The desk (post and galley slip) stays: it is what flow leaves behind,
   and the post is the way back. Nothing is deleted; a pause, Escape or the
   post brings it all back as it was. */
[data-flow="flow"] .flow-surface > :not(.flow-desk),
[data-flow="flow"] .in-flow-rails,
[data-flow="flow"] .manuscript-comment-card.is-in-margin,
[data-flow="flow"] .ld-panel {
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  transition:
    opacity 0.8s ease,
    visibility 0s linear 0.8s;
}
/* The masthead, the review line and the docked panels leave too, but keep
   their size, so the page does not move. The masthead is the explicit way
   back: reaching for its strip (or Escape) ends focus. */
[data-flow="flow"] .editor-workspace-main > header,
[data-flow="flow"] .twyne-toolbar,
[data-flow="flow"] .editor-desk-controls,
[data-flow="flow"] .live-review-status,
[data-flow="flow"] .editor-workspace-shell > aside {
  visibility: hidden;
  opacity: 0;
  transition:
    opacity 1.2s ease,
    visibility 0s linear 1.2s;
}
[data-flow="settling"] .editor-workspace-main > header:hover,
[data-flow="settling"] .twyne-toolbar:hover {
  opacity: 1;
  transition-duration: 0.2s;
}
[data-flow="stuck"] .flow-card {
  animation: flow-slip-in 360ms ease-out;
}

/* ── The desk: what outlasts the cards ─────────────────────────────────
   Pneumatic post at the head of the room while the page is quiet; the
   galley slip at its foot when a run of focus ends. Both are sticky, so
   they stay in view however long the manuscript. */
.flow-desk {
  position: absolute;
  top: 0;
  bottom: 0;
  left: calc(100% + 28px);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  pointer-events: none;
}

