// A specimen sheet of the living press vocabulary, rendered with the app's
// own compiled CSS, plus a filmstrip of the rubric's ink-impression shader.
// Usage: env -u LD_LIBRARY_PATH node specimen.mjs <outPng> [baseUrl] [theme] [shaderFile]
import { readFileSync } from "node:fs";
const root = "/home/diogenes/.t3/worktrees/twyne/feat-living-press";
const { chromium } = await import(`${root}/node_modules/playwright/index.mjs`);
const out = process.argv[2];
const base = process.argv[3] ?? "http://127.0.0.1:5190";
const theme = process.argv[4] ?? "editorial";
const shaderFile = process.argv[5] ?? `${root}/src/components/rubric/stamp-shader.tsx`;

const tsx = readFileSync(shaderFile, "utf8");
const fragment = tsx.match(/FRAGMENT_SHADER,\s*`([\s\S]*?)`/)[1];
const vertex = tsx.match(/VERTEX_SHADER,\s*"([^"]+)"/)[1];
// The component's own sizing rule, so the filmstrip shows what ships.
const cellsRule = /uniform float cells/.test(fragment);

const html = `<!doctype html>
<html data-theme="${theme}" data-motion="full">
<head>
<meta charset="utf-8">
<link rel="preconnect" href="https://fonts.googleapis.com">
