        <span style="font-family:var(--font-display);font-size:28px">24</span>
        <span>days writing</span>
        <span style="font-family:var(--font-display);font-size:28px;color:var(--ink-credit)">$0.4210</span>
        <span class="destination-tag" data-consequence="credit"><span class="destination-tag__mark"></span><span>credit</span></span>
        <span>3 days <span class="desk-filed" style="animation:none">Filed</span></span>
      </div>
