    </section>

    <section class="cell" style="grid-column: 1 / -1">
      <h2>The verdict</h2><h3>The rubric's ink impression, frame by frame</h3>
      <div class="film" id="film"></div>
      <p class="note">A WebGL halftone that spreads under a new grade stamp, with the cobalt plate mis-registered against the vermilion. Plays once per new verdict for --dur-ceremony, then the context is surrendered. Never on restore, never at Still.</p>
    </section>

    <section class="cell" style="grid-column: 1 / -1">
      <h2>Tokens</h2><h3>Two springs and the house curve, sampled from the CSS</h3>
      <div class="row" id="curves"></div>
    </section>
  </div>
</div>
<script>
const FRAG = ${JSON.stringify(fragment)};
const VERT = ${JSON.stringify(vertex)};
const ink = (name) => {
  const probe = document.createElement("span");
  probe.style.color = "var(" + name + ")";
  document.body.appendChild(probe);
