  wrap.append(canvas, img, label);
  document.getElementById("film").append(wrap);
  // Same rule as the component: CSS size times DPR, no cap below.
  const size = ${cellsRule ? "Math.round(150 * (window.devicePixelRatio || 1))" : "Math.max(1, Math.round(150 * (window.devicePixelRatio || 1) / 2))"};
  canvas.width = size; canvas.height = size;
  const gl = canvas.getContext("webgl", { alpha: true, antialias: false, preserveDrawingBuffer: true });
  const compile = (type, src) => { const s = gl.createShader(type); gl.shaderSource(s, src); gl.compileShader(s); if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s)); return s; };
  const program = gl.createProgram();
