// Plot the easing curves by sampling a real CSS transition's timing.
function plot(name, varName) {
  const w = 220, h = 120, pad = 14;
  const timing = getComputedStyle(document.documentElement).getPropertyValue(varName).trim();
  const probe = document.createElement("div");
  document.body.appendChild(probe);
  const anim = probe.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 1000, easing: timing, fill: "both" });
  anim.pause();
  const pts = [];
  for (let i = 0; i <= 60; i++) { anim.currentTime = (i / 60) * 1000; pts.push(Number(getComputedStyle(probe).opacity)); }
  probe.remove();
  // opacity clamps to [0,1]; read overshoot from linear() stops directly.
  const stops = [...timing.matchAll(/(-?[\\d.]+)(?:\\s+[\\d.]+%)?/g)].map((m) => Number(m[1])).filter((v) => !Number.isNaN(v));
  const peak = timing.startsWith("linear(") ? Math.max(...stops) : 1;
  const y = (v) => h - pad - v * (h - 2 * pad) / 1.1;
  const path = timing.startsWith("linear(")
    ? [...timing.slice(7, -1).split(",")].map((s, i, all) => { const [v, pct] = s.trim().split(/\\s+/); const x = pct ? parseFloat(pct) / 100 : i / (all.length - 1); return [x, Number(v)]; })
    : pts.map((v, i) => [i / 60, v]);
  const d = path.map(([x, v], i) => (i ? "L" : "M") + (pad + x * (w - 2 * pad)).toFixed(1) + " " + y(v).toFixed(1)).join(" ");
  const fig = document.createElement("figure");
  fig.style.margin = "0";
  fig.innerHTML = '<svg class="curve" width="' + w + '" height="' + h + '"><line x1="' + pad + '" x2="' + (w - pad) + '" y1="' + y(1) + '" y2="' + y(1) + '" stroke="var(--color-paper-3)" stroke-dasharray="3 3"/><path d="' + d + '" fill="none" stroke="var(--color-vermilion)" stroke-width="2"/></svg><figcaption class="note" style="margin-top:4px">' + name + ' · peak ' + peak.toFixed(3) + '</figcaption>';
  document.getElementById("curves").append(fig);
}
plot("--ease-set (house curve)", "--ease-set");
plot("--ease-slip (paper in hand)", "--ease-slip");
