22	varying vec2 uv;
23	uniform float t;          // 0..1 through the ceremony
24	uniform vec3 stampInk;    // the grade's own ink
25	uniform vec3 registerInk; // the second plate
26	uniform float radius;     // the stamp's radius, in uv units
27	uniform float cells;      // halftone cells across the canvas
28	uniform float aa;         // one device pixel, in cell units
