30	float hash(vec2 p) {
31	  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
32	}
33	
34	// Coverage of one halftone screen at this density, screened at an angle.
35	float screen(vec2 p, float density, float angle) {
36	  float c = cos(angle), s = sin(angle);
37	  vec2 g = mat2(c, -s, s, c) * p * cells * 0.5;
38	  vec2 cell = fract(g) - 0.5;
