44	float squeeze(vec2 p, float spread, float dry) {
45	  float r = length(p);
46	  float a = atan(p.y, p.x);
47	  float tip = radius * 0.8;                 // the rays end here
48	  float reach = max(spread * radius * 0.62, 0.0001);
49	  float along = (r - tip) / reach;          // 0 at the tips, 1 at the front
50	  // Ink is pushed along the rays' channels: streaks that continue them.
51	  float rays = pow(abs(cos(a * 20.0)), 5.0);
