// A specimen sheet of the living press, rendered with the app's own compiled
// CSS from a running dev server, plus a filmstrip of the verdict shader read
// straight out of src/components/rubric/stamp-shader.tsx.
//
// Usage (from the worktree root):
//   env -u LD_LIBRARY_PATH node artifacts/qa-recordings/2026-11-05/juice/scripts/specimen.mjs \
//     <outPng> [baseUrl=http://127.0.0.1:5190] [theme=editorial]
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

const root = resolve(new URL("../../../../..", import.meta.url).pathname);
const { chromium } = await import(`${root}/node_modules/playwright/index.mjs`);
const out = process.argv[2];
const base = process.argv[3] ?? "http://127.0.0.1:5190";
const theme = process.argv[4] ?? "editorial";
if (!out) throw new Error("usage: specimen.mjs <outPng> [baseUrl] [theme]");

const tsx = readFileSync(`${root}/src/components/rubric/stamp-shader.tsx`, "utf8");
const fragment = tsx.match(/const FRAGMENT = `([\s\S]*?)`;/)[1];
const vertex = tsx.match(/const VERTEX =\s*"([^"]+)"/)[1];

const stampCell = (grade, tier, colour, asset, t) => `
  <div class="frame">
    <div class="rubric-grade-stamp rubric-grade-stamp--compact rubric-grade-stamp--${tier}"
         style="color:${colour};--rubric-stamp-image:url(/assets/rubric-stamps/${asset}.png)"
         data-t="${t}">
      <canvas class="room-stamp-shader"></canvas>
      <span class="ink-stamp"><span class="ink-stamp__imprint"><span class="rubric-grade-stamp__mark"></span></span></span>
    </div>
    <span class="t">${grade} · t=${t.toFixed(2)}</span>
  </div>`;

const film = [0.12, 0.22, 0.3, 0.4, 0.52, 0.66, 0.8, 0.94]
  .map((t) => stampCell("B+", "b", "var(--color-ink-light)", "sunburst-b-plus", t))
  .join("");
const tiers = [
  ["A", "a", "var(--color-accent-green)", "sunburst-a"],
  ["C+", "c", "var(--color-accent-amber)", "sunburst-c-plus"],
  ["D", "revise", "var(--color-accent-red)", "sunburst-d"],
]
  .map(([g, tier, c, a]) => stampCell(g, tier, c, a, 0.44))
  .join("");

const tag = (to, word) =>
  `<span class="destination-tag" data-consequence="${to}"><span class="destination-tag__mark"></span><span>${word}</span></span>`;

const html = `<!doctype html>
<html data-theme="${theme}" data-motion="full">
<head>
<meta charset="utf-8">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Libre+Baskerville:ital,wght@0,400;0,700;1,400&family=Lora:ital,wght@0,400;0,500;1,400&family=Special+Elite&display=swap">
<link rel="stylesheet" href="/src/global.css?direct">
<link rel="stylesheet" href="/src/styles/press.css?direct">
<style>
  body { margin: 0; background: var(--color-paper); color: var(--color-ink); font-family: var(--font-sans); }
  .sheet { width: 1180px; padding: 40px 48px 56px; box-sizing: border-box; }
  .sheet h1 { font-family: var(--font-display); font-size: 30px; margin: 0; }
  .lede { font-family: var(--font-serif); font-style: italic; color: var(--color-ink-light); margin: 6px 0 26px; }
  .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 26px 30px; }
  .cell { border-top: 2px solid var(--color-ink); padding-top: 12px; }
  .wide { grid-column: 1 / -1; }
  .cell h2 { font-family: var(--font-typewriter); font-weight: 400; font-size: 11px; letter-spacing: .22em; text-transform: uppercase; color: var(--color-ink-muted); margin: 0 0 4px; }
  .cell h3 { font-family: var(--font-display); font-size: 17px; margin: 0 0 12px; font-weight: 400; }
  .row { display: flex; flex-wrap: wrap; align-items: center; gap: 14px 18px; }
  .note { font-size: 11.5px; color: var(--color-ink-muted); margin: 10px 0 0; line-height: 1.5; max-width: 62ch; }
  .prose { font-family: var(--font-serif); font-size: 18px; line-height: 1.8; margin: 0; }
  .wet { color: var(--ink-wet); }
  .drying { color: color-mix(in srgb, var(--ink-wet) 40%, var(--color-ink)); }
  .sel { background: var(--ink-selection); }
  .caret { display: inline-block; width: 1.5px; height: 1.15em; background: var(--color-vermilion); vertical-align: -0.18em; margin: 0 1px; }
  .face { position: relative; width: 30px; height: 30px; display: inline-block; }
  .face img { width: 30px; height: 30px; border-radius: 50%; display: block; object-fit: cover; background: var(--color-paper-2); border: 1px solid var(--color-paper-3); }
  .facecap { display: grid; justify-items: center; gap: 6px; font-family: var(--font-typewriter); font-size: 10px; letter-spacing: .1em; color: var(--color-ink-muted); text-transform: uppercase; }
  .film { display: flex; flex-wrap: wrap; gap: 10px; }
  .frame { position: relative; width: 128px; height: 150px; display: grid; place-items: center; background: var(--color-paper-soft); border: 1px solid var(--color-paper-3); overflow: hidden; }
  .frame .t { position: absolute; bottom: 4px; left: 6px; font-family: var(--font-typewriter); font-size: 10px; color: var(--color-ink-muted); }
  .mock-bar { display: inline-flex; gap: 14px; font-size: 12px; color: var(--color-ink-light); align-items: center; padding: 6px 10px; border: 1px solid var(--color-paper-3); background: var(--color-paper-2); }
  .selection-actions.static { position: relative; transform: none; left: auto; top: auto; z-index: 1; }
  .rule-host { position: relative; padding: 14px 10px 28px; background: var(--color-editor-bg); border: 1px solid var(--color-paper-3); font-family: var(--font-serif); }
  .rule-host .twyne-section-drop-rule { animation: none; margin-top: 10px; }
  .slug-host { position: relative; height: 44px; }
  .slug-host .twyne-section-slug { position: absolute; top: 6px; left: 6px; }
  .curve { background: var(--color-paper-soft); border: 1px solid var(--color-paper-3); }
  .holdrow { padding-bottom: 24px; }
</style>
</head>
<body>
<div class="sheet">
  <h1>The living press, a specimen</h1>
  <p class="lede">Each piece is the shipping CSS from src/styles, set statically. Theme: ${theme}.</p>
  <div class="grid">

    <section class="cell">
      <h2>Consequence</h2><h3>One ink, one mark, one word per destination</h3>
      <div class="row">${tag("local", "device")}${tag("synced", "account")}${tag("provider", "model")}${tag("credit", "credit")}${tag("public", "public")}${tag("erase", "erases")}</div>
      <div class="row" style="margin-top:14px">
        <button class="btn-press" data-consequence="credit">Grade this draft ${tag("credit", "credit")}</button>
        <button class="btn-press" data-consequence="public">Publish now ${tag("public", "public")}</button>
        <button class="btn-paper" data-consequence="provider">Send to editor ${tag("provider", "model")}</button>
      </div>
      <p class="note">Hollow ring: nothing leaves. Filled: a copy goes somewhere. Ring with a dot: seen from outside. Struck square: gone. The word is always printed, so colour is never the only cue.</p>
    </section>

    <section class="cell">
      <h2>Permanent losses</h2><h3>Hold to confirm: the platen comes down</h3>
      <div class="row holdrow">
        <button class="hold-to-confirm btn-paper" data-consequence="erase"><span class="hold-to-confirm__ink"></span>Stop sharing</button>
        <button class="hold-to-confirm btn-paper" data-consequence="erase" data-holding style="--press-progress:.33"><span class="hold-to-confirm__ink"></span>Stop sharing<span class="hold-to-confirm__hint">hold to stop</span></button>
        <button class="hold-to-confirm btn-paper" data-consequence="erase" data-holding style="--press-progress:.85"><span class="hold-to-confirm__ink"></span>Stop sharing<span class="hold-to-confirm__hint">hold to stop</span></button>
        <button class="hold-to-confirm btn-paper" data-consequence="erase" data-armed><span class="hold-to-confirm__ink"></span>Erase<span class="hold-to-confirm__hint">press again to confirm</span></button>
      </div>
      <p class="note">At rest, held part-way, nearly committed, and the keyboard's armed state. The ink eases in (slow to start), releasing early drains it, and a too-quick click nudges the slip into view instead of erasing.</p>
    </section>

    <section class="cell">
      <h2>The manuscript</h2><h3>Wet ink, the pencil caret, proof-blue selection</h3>
      <p class="prose">Morgan kept the ledger. <span class="drying">Every sack had a line,</span> <span class="wet">every line a price</span><span class="caret"></span></p>
      <p class="prose" style="margin-top:6px">Salt bought <span class="sel">silence in the hill towns.</span> A handful pressed…</p>
      <p class="note">New words sit in a wetter cobalt-black until IndexedDB has them, pass through a drying tone, then are just ink. Painted with the CSS Custom Highlight API: colour only, no DOM nodes, no layout.</p>
    </section>

    <section class="cell">
      <h2>Where the words are</h2><h3>The status bar, in its consequence ink</h3>
      <div class="row">
        <span class="mock-bar"><span class="press-sync-status"><span>Saved 4s ago</span><span class="press-sync-route" data-consequence="local"><span class="press-sync-mark"></span>held here</span></span></span>
        <span class="mock-bar"><span class="press-sync-status"><span>Saved just now</span><span class="press-sync-route" data-consequence="synced"><span class="press-sync-mark"></span>on the wire</span></span></span>
        <span class="mock-bar"><span class="press-sync-status"><span>Saved 12s ago</span><span class="press-sync-route" data-consequence="synced"><span class="press-sync-mark"></span>filed</span></span></span>
      </div>
      <p class="note">One line instead of a coloured dot beside a timestamp. "Filed" flashes once in the account's green when it lands; nothing pulses while the wire is busy.</p>
    </section>

    <section class="cell">
      <h2>An editor reading</h2><h3>A pencil ring that follows the real stream</h3>
      <div class="row" style="gap:26px">
        <span class="facecap"><span class="face"><svg class="room-reading-ring" viewBox="0 0 40 40" style="--reading-progress:.16"><circle cx="20" cy="20" r="18" pathLength="1"/></svg><img src="/assets/avatars/engraved-2026-09/owl.webp"></span>reasoning</span>
        <span class="facecap"><span class="face"><svg class="room-reading-ring" viewBox="0 0 40 40" style="--reading-progress:.58"><circle cx="20" cy="20" r="18" pathLength="1"/></svg><img src="/assets/avatars/engraved-2026-09/fox.webp"></span>writing</span>
        <span class="facecap"><span class="face"><svg class="room-reading-ring" viewBox="0 0 40 40" style="--reading-progress:.92"><circle cx="20" cy="20" r="18" pathLength="1"/></svg><img src="/assets/avatars/engraved-2026-09/hare.webp"></span>nearly filed</span>
