// Verify the verdict shader inside the real GradeStamp: it starts with the
// die press, draws ink, surrenders its context, ignores unrelated renders,
// and creates nothing at the still level.
import { resolve } from "node:path";
const root = resolve(new URL("../../../../..", import.meta.url).pathname);
const { chromium } = await import(`${root}/node_modules/playwright/index.mjs`);
const outDir = process.argv[2];
const base = process.argv[3] ?? "http://127.0.0.1:5190";

const browser = await chromium.launch({
  args: ["--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader"],
});

async function run(motion) {
  const context = await browser.newContext({ viewport: { width: 900, height: 600 }, deviceScaleFactor: 1 });
  await context.addInitScript((level) => localStorage.setItem("twyne.appearance.motion", level), motion);
  const page = await context.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));
  await page.route(/\/api\/auth\//, (r) => r.fulfill({ contentType: "application/json", body: "null" }));
  await page.goto(`${base}/__press-lab/`, { waitUntil: "networkidle" });
  await page.waitForTimeout(1500);
  // Warm the die image so the press starts at once, as on a returning visit.
  await page.evaluate(() => new Promise((r) => { const i = new Image(); i.onload = i.onerror = r; i.src = "/assets/stamp-press/walnut-stamp.avif"; }));
  console.log(`[${motion}] level`, await page.evaluate(() => document.documentElement.dataset.motion));

  await page.click("#stamp");
  const t0 = Date.now();
  const host = page.locator("#host");
  const samples = [];
  const box = await host.boundingBox();
  const clip = { x: Math.max(0, box.x - 20), y: Math.max(0, box.y - 60), width: 300, height: 290 };
  for (const at of [60, 180, 300, 450, 650, 1000, 1400]) {
    const wait = at - (Date.now() - t0);
    if (wait > 0) await page.waitForTimeout(wait);
    const state = await page.evaluate(() => {
      const canvas = document.querySelector(".room-stamp-shader");
      const tool = document.querySelector(".ink-stamp__tool");
      const press = tool?.getAnimations().find((a) => a.animationName === "stamp-die-press");
      return {
        canvas: !!canvas,
        width: canvas?.width ?? null,
        pressMs: press ? Math.round(press.currentTime) : null,
      };
    });
    const file = motion === "full" ? `${outDir}/verdict-${String(at).padStart(4, "0")}ms.png` : null;
    if (file) await page.screenshot({ path: file, clip });
    samples.push({ at, actual: Date.now() - t0, ...state });
  }
  // Has the context been surrendered once the ceremony is over?
  const lost = await page.evaluate(() => {
    const canvas = document.querySelector(".room-stamp-shader");
    if (!canvas || canvas.width === 300) return "never created";
    const gl = canvas.getContext("webgl");
    return gl ? (gl.isContextLost() ? "lost (surrendered)" : "still alive") : "no context";
  });
  // An unrelated re-render must not replay the impression.
  const widthBefore = await page.evaluate(() => document.querySelector(".room-stamp-shader")?.width ?? null);
  await page.click("#unrelated");
  await page.waitForTimeout(400);
  const replayed = await page.evaluate((w) => {
    const c = document.querySelector(".room-stamp-shader");
    return { width: c?.width ?? null, sameCanvas: c?.width === w };
  }, widthBefore);
  console.log(`[${motion}] samples`, JSON.stringify(samples));
  console.log(`[${motion}] context after ceremony:`, lost, "| unrelated render:", JSON.stringify(replayed));
  console.log(`[${motion}] errors`, JSON.stringify(errors.slice(0, 5)));
  await context.close();
}

await run("full");
await run("still");
await browser.close();
EOF
