// Capture the editor and My Desk in the states the comparison uses, against
// any running Twyne dev server: the base commit for "before", this branch
// for "after". The same seed and the same moments, so pairs line up.
//
// Usage (from a worktree root):
//   env -u LD_LIBRARY_PATH node artifacts/qa-recordings/2026-11-05/juice/scripts/capture.mjs \
//     <outDir> <baseUrl>
import { mkdirSync } from "node:fs";
import { join, resolve } from "node:path";

const root = resolve(new URL("../../../../..", import.meta.url).pathname);
const { chromium } = await import(`${root}/node_modules/playwright/index.mjs`);
const outDir = process.argv[2];
const base = process.argv[3];
if (!outDir || !base) throw new Error("usage: capture.mjs <outDir> <baseUrl>");
mkdirSync(outDir, { recursive: true });

const MANUSCRIPT =
  `<h1>The Salt Roads</h1>` +
  `<p>The traders <span data-persona-note-id="n1" data-persona-note-author="Marguerite" data-persona-note-color="#b0413e" data-persona-note-label="Pacing" data-persona-note-note="This sentence carries three ideas; let the second breathe." data-persona-note-quote="weighed their loads by the handful">weighed their loads by the handful</span> and argued about the weather, as if the weather had ever listened to a trader.</p>` +
  `<p>By the fourth day <span class="twyne-comment-mark" data-comment-id="c1" data-comment-author="You">the road forgot the sea entirely</span> and turned inland, past terraces of thyme and the white ribs of abandoned pans.</p>` +
  `<p>Morgan kept the ledger. Every sack had a line, every line a price, and every price a story about who had been cheated last season. The ledger was the only honest thing on the caravan, and even it lied by omission.</p>` +
  `<h2>The inland markets</h2>` +
  `<p>Salt bought silence in the hill towns. A handful pressed into a magistrate's palm could close a dispute that had run for three generations, and nobody thought to ask whose salt it had been.</p>` +
  `<p>When the rains came early the pans flooded and the price doubled overnight. The traders who had argued about the weather were suddenly the only ones who had planned for it.</p>` +
  `<p>There is a kind of wealth that only exists in transit. Stop moving and it dissolves, the way a crust of salt dissolves on the tongue.</p>`;

const browser = await chromium.launch();
const context = await browser.newContext({
  viewport: { width: 1440, height: 900 },
  deviceScaleFactor: 1,
});
const page = await context.newPage();
const errors = [];
page.on("pageerror", (e) => errors.push(e.message));
await page.route(/\/api\/auth\//, (route) =>
  route.fulfill({ contentType: "application/json", body: "null" }),
);
await page.route("**/__juice-seed", (route) =>
  route.fulfill({ contentType: "text/html", body: "<!doctype html><title>Seed</title>" }),
);

await page.goto(`${base}/__juice-seed`);
await page.evaluate(async (html) => {
  const idb = await import(/* @vite-ignore */ "/src/utils/idb.ts");
  const uc = await import(/* @vite-ignore */ "/src/utils/user-comments.ts");
  const sync = await import(/* @vite-ignore */ "/src/utils/convex-sync.ts");
  const ledgerMod = await import(/* @vite-ignore */ "/src/utils/usage-ledger.ts");
  const now = Date.now();
  const day = 86400000;
  const id = "f-juice";
  await idb.saveFoliosToIdb([
    { id, name: "The Salt Roads", type: "draft", createdAt: now - day * 40, updatedAt: now },
    { id: "f-juice-2", name: "Letters from the pans", type: "draft", createdAt: now - day * 30, updatedAt: now - day * 3 },
  ]);
  await idb.saveActiveFolioIdToIdb(id);
  await idb.saveFolioContentToIdb(id, html);
  await idb.saveFolioContentToIdb("f-juice-2", "<p>Dear R., the pans are quiet this year.</p>");
  await sync.savePersonaNoteLocally(
    {
      folioId: id, noteId: "n1", personaId: "marguerite", personaName: "Marguerite",
      personaColor: "#b0413e", feedback: "This sentence carries three ideas; let the second breathe.",
      anchor: "weighed their loads by the handful", timestamp: now, type: "critique",
    },
    null,
    id,
  );
  await uc.saveUserComments([
    {
      id: "c1", folioId: id, text: "Is this literally true? Check the map.", author: "You",
      anchor: "the road forgot the sea entirely", resolved: false, createdAt: now, updatedAt: now, replies: [],
    },
  ]);
  // A month of writing and some editorial runs, so the Desk has a ledger.
  const ledger = ledgerMod.usageLedger;
  for (let d = 0; d < 34; d++) {
    if (d % 5 === 3) continue;
    const marks = 1 + ((d * 7) % 5);
    for (let m = 0; m < marks; m++) {
      await ledger.recordWritingActivity({
        folioId: d % 4 === 0 ? "f-juice-2" : id,
        occurredAt: now - d * day - m * 3_600_000,
        throttleMs: 0,
      });
    }
  }
  for (let d = 0; d < 20; d += 2) {
    await ledgerMod.recordClientUsageAttempt({
      requestSent: true, traceId: `t-${d}`, attempt: 1, occurredAt: now - d * day,
      source: "byok", feature: "persona-feedback", provider: "anthropic", model: "claude-sonnet-5-5",
      outcome: "completed", usage: { inputTokens: 2400 + d * 90, outputTokens: 600 + d * 20 },
      folioId: id,
    });
  }
  await idb.saveMetaToIdb("live-review-enabled", false);
  await idb.saveMetaToIdb("signin-toast-dismissed", true);
  localStorage.setItem("living-desk-open", "false");
  localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
  localStorage.setItem("twyne.appearance.motion", "full");
  localStorage.removeItem("twyne.desk.patterns-seen");
}, MANUSCRIPT);

const shot = async (name, fn, opts = {}) => {
  try {
    if (fn) await fn();
    await page.screenshot({ path: join(outDir, `${name}.png`), ...opts });
    console.log("ok", name);
  } catch (e) {
    console.log("FAIL", name, e.message.split("\n")[0]);
  }
};
const settle = (ms = 900) => page.waitForTimeout(ms);
const manuscript = () => page.locator("#twyne-editor-mount .ProseMirror");
const detail = async (locator, name) => {
  try {
    await locator.screenshot({ path: join(outDir, `${name}.png`), timeout: 4000 });
    console.log("ok", name);
  } catch (e) {
    console.log("skip", name, e.message.split("\n")[0]);
  }
};

// Opening the editor: sample what is on screen while the route loads.
const t0 = Date.now();
await page.goto(`${base}/editor/`, { waitUntil: "commit" });
const timeline = [];
let gateShot = false;
for (let i = 0; i < 100; i++) {
  const state = await page
    .evaluate(() => {
      const gate = [...document.querySelectorAll(".folio")].find((el) =>
        el.textContent?.includes("Setting the type"),
      );
      return {
        shell: !!document.querySelector(".editor-workspace-shell"),
        gate: gate ? Number(getComputedStyle(gate.closest(".press-hydration") ?? gate).opacity) : -1,
        text: !!document.querySelector("#twyne-editor-mount .ProseMirror"),
      };
    })
    .catch(() => ({ shell: false, gate: -1, text: false }));
  timeline.push({ t: Date.now() - t0, ...state });
  if (state.gate > 0.5 && !gateShot) {
    await page.screenshot({ path: join(outDir, "editor-loading.png") }).catch(() => {});
    gateShot = true;
  }
  if (state.text) break;
  await page.waitForTimeout(100);
}
console.log(
  "load",
  JSON.stringify(
    timeline.map(({ t, shell, gate, text }) =>
      `${t}:${text ? "text" : shell ? "shell" : gate >= 0 ? `gate${gate.toFixed(1)}` : "blank"}`,
    ),
  ),
);
await manuscript().waitFor({ timeout: 90000 });
await page.evaluate(() => document.fonts.ready);
await settle(1800);
await shot("editor-default");

await shot("editor-hover-note", async () => {
  await page.locator('[data-persona-note-id="n1"]').first().hover();
  await settle(600);
});

// Typing, then the same paragraph once the save has landed.
await shot("editor-typing", async () => {
  await page.mouse.move(1300, 600);
  await manuscript().locator("p").nth(3).click();
  await page.keyboard.press("End");
  await page.keyboard.type(" The ledger kept its own counsel.", { delay: 30 });
  await page.waitForTimeout(80);
});
await detail(manuscript().locator("p").nth(3), "detail-typing");
await page.waitForTimeout(4200);
await detail(manuscript().locator("p").nth(3), "detail-typing-saved");
await detail(page.locator(".editor-bottom-bar, .typst-statusbar").first(), "detail-status-bar");

// A selection and its toolbar.
await page.mouse.click(5, 300);
const para = manuscript().locator("p").nth(5);
const box = await para.boundingBox();
await page.mouse.move(box.x + 4, box.y + 6);
await page.mouse.down();
await page.mouse.move(box.x + box.width * 0.7, box.y + 8, { steps: 12 });
await page.mouse.up();
await page.waitForTimeout(90);
await page.screenshot({ path: join(outDir, "editor-selection-arriving.png") });
await shot("editor-selection", async () => settle(600));
await detail(page.locator(".selection-actions"), "detail-selection-toolbar");
await shot("editor-ask-an-editor", async () => {
  await page.locator('.selection-actions [data-menu-trigger="persona"]').click();
  await settle(500);
});
await detail(page.locator(".selection-actions"), "detail-ask-an-editor");
await page.keyboard.press("Escape");
await page.mouse.click(5, 5);

// A heading's drag handle hovered, then a section dragged over a heading.
await shot("editor-section-drop", async () => {
  await manuscript().locator("h2").first().hover();
  await settle(300);
  await page.evaluate(() => {
    const handle = document.querySelector("#twyne-editor-mount .ProseMirror [data-section-drag-handle]");
    const target = document.querySelector("#twyne-editor-mount .ProseMirror h2");
    if (!handle || !target) return;
    const dt = new DataTransfer();
    handle.dispatchEvent(new DragEvent("dragstart", { bubbles: true, dataTransfer: dt }));
    const r = target.getBoundingClientRect();
    target.dispatchEvent(new DragEvent("dragover", { bubbles: true, cancelable: true, dataTransfer: dt, clientX: r.left + 20, clientY: r.bottom - 2 }));
  });
  await settle(400);
});
await page.evaluate(() => {
  document.querySelector("#twyne-editor-mount .ProseMirror [data-section-drag-handle]")
    ?.dispatchEvent(new DragEvent("dragend", { bubbles: true }));
});

// A file dragged over the manuscript.
await shot("editor-file-drag", async () => {
  await page.evaluate(() => {
    const scroller = document.querySelector(".manuscript-scroller");
    const dt = new DataTransfer();
    dt.items.add(new File(["x"], "plate.png", { type: "image/png" }));
    scroller.dispatchEvent(new DragEvent("dragover", { bubbles: true, cancelable: true, dataTransfer: dt, clientX: 700, clientY: 400 }));
  });
  await settle(600);
});
await page.evaluate(() => {
  document.querySelector(".manuscript-scroller")?.dispatchEvent(new DragEvent("dragleave", { bubbles: true }));
  document.querySelector(".manuscript-scroller")?.dispatchEvent(new DragEvent("drop", { bubbles: true, cancelable: true }));
});
await settle(400);

await shot("editor-scrolled", async () => {
  await page.locator(".manuscript-scroller").evaluate((el) => el.scrollTo({ top: 400 }));
  await settle(600);
});
await page.locator(".manuscript-scroller").evaluate((el) => el.scrollTo({ top: 0 })).catch(() => {});

await shot("editor-drawer", async () => {
  await page.getByRole("button", { name: "Toggle the drawer sidebar" }).click();
  await settle(700);
});
await page.getByRole("button", { name: "Toggle the drawer sidebar" }).click().catch(() => {});
await settle(500);

await shot("editor-board", async () => {
  await page.getByRole("button", { name: /Editorial Board|editorial board|Open the room|The Room/i }).first().click({ timeout: 5000 });
  await settle(1000);
});
await detail(page.locator(".editorial-overlay"), "detail-board");
await page.keyboard.press("Escape").catch(() => {});
await settle(300);

await shot("editor-file-menu", async () => {
  await page.getByRole("button", { name: /^File/ }).click();
  await settle(500);
});
await detail(page.locator("[data-folio-menu] [role=menu]"), "detail-file-menu");
await page.keyboard.press("Escape").catch(() => {});

// My Desk: arriving, settled, a day selected, and keyboard on the tabs.
await page.goto(`${base}/desk/`);
