// Record short clips of the moments stills cannot show, against a running
// dev server, then (with ffmpeg) turn each into a looping GIF next to it.
//
// Usage (from a worktree root, after capture.mjs has seeded nothing; this
// seeds its own state):
//   env -u LD_LIBRARY_PATH node artifacts/qa-recordings/2026-11-05/juice/scripts/motion-clips.mjs \
//     <outDir> <baseUrl> <label>
import { mkdirSync, readdirSync, renameSync, rmSync } from "node:fs";
import { join, resolve } from "node:path";

const root = resolve(new URL("../../../../..", import.meta.url).pathname);
const { chromium } = await import(`${root}/node_modules/playwright/index.mjs`);
const outDir = process.argv[2];
const base = process.argv[3];
const label = process.argv[4] ?? "clip";
mkdirSync(outDir, { recursive: true });

const MANUSCRIPT =
  `<h1>The Salt Roads</h1>` +
  `<p>The traders weighed their loads by the handful and argued about the weather, as if the weather had ever listened to a trader.</p>` +
  `<p>Morgan kept the ledger. Every sack had a line, every line a price, and every price a story about who had been cheated last season.</p>` +
  `<h2>The inland markets</h2>` +
  `<p>Salt bought silence in the hill towns. A handful pressed into a magistrate's palm could close a dispute that had run for three generations.</p>` +
  `<p>When the rains came early the pans flooded and the price doubled overnight.</p>`;

const browser = await chromium.launch();

async function clip(name, size, run) {
  const tmp = join(outDir, `.${name}`);
  rmSync(tmp, { recursive: true, force: true });
  const context = await browser.newContext({
    viewport: size,
    deviceScaleFactor: 1,
    recordVideo: { dir: tmp, size },
  });
  const page = await context.newPage();
  await page.route(/\/api\/auth\//, (r) => r.fulfill({ contentType: "application/json", body: "null" }));
  await page.route("**/__clip-seed", (r) => r.fulfill({ contentType: "text/html", body: "<!doctype html><title>Seed</title>" }));
  await page.goto(`${base}/__clip-seed`);
  await page.evaluate(async (html) => {
    const idb = await import(/* @vite-ignore */ "/src/utils/idb.ts");
    const uc = await import(/* @vite-ignore */ "/src/utils/user-comments.ts");
    const ledgerMod = await import(/* @vite-ignore */ "/src/utils/usage-ledger.ts");
    const now = Date.now();
    await idb.saveFoliosToIdb([{ id: "f-c", name: "The Salt Roads", type: "draft", createdAt: now - 864e5 * 40, updatedAt: now }]);
    await idb.saveActiveFolioIdToIdb("f-c");
    await idb.saveFolioContentToIdb("f-c", html);
    const at = { folioId: "f-c", author: "You", resolved: false, createdAt: now, updatedAt: now, replies: [] };
    await uc.saveUserComments([
      { ...at, id: "c1", text: "Is this literally true?", anchor: "weighed their loads" },
      { ...at, id: "c2", text: "Name the magistrate.", anchor: "magistrate" },
    ]);
    for (let d = 0; d < 30; d++) {
      if (d % 5 === 3) continue;
      for (let m = 0; m < 1 + ((d * 7) % 5); m++) {
        await ledgerMod.usageLedger.recordWritingActivity({ folioId: "f-c", occurredAt: now - d * 864e5 - m * 36e5, throttleMs: 0 });
      }
    }
    await idb.saveMetaToIdb("live-review-enabled", false);
    await idb.saveMetaToIdb("signin-toast-dismissed", true);
    localStorage.setItem("living-desk-open", "false");
    localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
    localStorage.setItem("twyne.appearance.motion", "full");
    localStorage.removeItem("twyne.desk.patterns-seen");
  }, MANUSCRIPT);
  try {
    await run(page);
  } catch (e) {
    console.log("FAIL", name, e.message.split("\n")[0]);
  }
  const video = page.video();
  await context.close();
  const source = await video.path();
  const target = join(outDir, `${label}-${name}.webm`);
  renameSync(source, target);
  rmSync(tmp, { recursive: true, force: true });
  console.log("ok", target);
}

const openEditor = async (page) => {
  await page.goto(`${base}/editor/`);
  await page.locator("#twyne-editor-mount .ProseMirror").waitFor({ timeout: 90000 });
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(1500);
};

// 1. Typing a sentence and the save landing: the ink should be wet, then dry.
await clip("typing", { width: 900, height: 420 }, async (page) => {
  await openEditor(page);
  const para = page.locator("#twyne-editor-mount .ProseMirror p").nth(1);
  await para.scrollIntoViewIfNeeded();
  const box = await para.boundingBox();
  await page.mouse.click(box.x + box.width - 4, box.y + box.height - 8);
  await page.keyboard.press("End");
  await page.keyboard.type(" The ledger was the only honest thing on the caravan.", { delay: 55 });
  await page.waitForTimeout(4200);
});

// 2. Selecting a passage, the toolbar arriving, opening "Ask an editor".
await clip("selection", { width: 900, height: 420 }, async (page) => {
  await openEditor(page);
  const para = page.locator("#twyne-editor-mount .ProseMirror p").nth(2);
  await para.scrollIntoViewIfNeeded();
  const box = await para.boundingBox();
  await page.mouse.move(box.x + 4, box.y + 8);
  await page.mouse.down();
  await page.mouse.move(box.x + box.width * 0.7, box.y + 10, { steps: 18 });
  await page.mouse.up();
  await page.waitForTimeout(900);
  await page.locator('.selection-actions [data-menu-trigger="persona"]').hover();
  await page.waitForTimeout(400);
  await page.locator('.selection-actions [data-menu-trigger="persona"]').click();
  await page.waitForTimeout(1400);
});

// 3. The lamp: the pointer wanders the desk, then the writer types.
await clip("lamp", { width: 1280, height: 640 }, async (page) => {
  await openEditor(page);
  for (const [x, y] of [[1150, 500], [200, 520], [1150, 160], [640, 600], [120, 140]]) {
    await page.mouse.move(x, y, { steps: 25 });
    await page.waitForTimeout(1200);
  }
});

// 4. Holding to erase a comment, with a too-quick click first.
await clip("hold", { width: 1280, height: 640 }, async (page) => {
  await openEditor(page);
  await page.getByRole("button", { name: /Editorial Board|editorial board|Open the room|The Room/i }).first().click();
  await page.waitForTimeout(600);
  await page.locator(".editorial-board-context").filter({ hasText: "Marginalia" }).click();
  await page.waitForTimeout(1200);
  const key = page.locator('.hold-to-confirm[data-consequence="erase"]').first();
  await key.scrollIntoViewIfNeeded();
  const box = await key.boundingBox();
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2, { steps: 12 });
  await page.waitForTimeout(500);
  await page.mouse.down();
  await page.waitForTimeout(90);
  await page.mouse.up();
  await page.waitForTimeout(1300);
  await page.mouse.down();
  await page.waitForTimeout(1100);
  await page.mouse.up();
  await page.waitForTimeout(1200);
});

// 5. Opening My Desk: figures and bars setting, then a day selected.
await clip("desk", { width: 1280, height: 720 }, async (page) => {
  await page.goto(`${base}/desk/`);
  await page.waitForTimeout(2600);
  await page.mouse.wheel(0, 420);
  await page.waitForTimeout(700);
  const cells = page.locator(".desk-heat-cell:not([disabled]), [aria-label*='UTC'][aria-pressed]");
  if (await cells.count()) {
    await cells.nth(-6).click();
    await page.waitForTimeout(900);
    await cells.nth(-12).click();
  }
  await page.waitForTimeout(1200);
});

await browser.close();
console.log(readdirSync(outDir).filter((f) => f.startsWith(label)).join("\n"));

