// Scroll behaviour: the running foot follows the section being read, pressing
// it returns to the heading, and the lamp stays put while the paper slides.
// Checked in the default (zen) view and with the full chrome.
import { mkdirSync } from "node:fs";
import { resolve } from "node:path";
const root = resolve(new URL("../../../../..", import.meta.url).pathname);
const { chromium } = await import(`${root}/node_modules/playwright/index.mjs`);
const outDir = process.argv[2];
const base = process.argv[3] ?? "http://127.0.0.1:5190";
mkdirSync(outDir, { recursive: true });

const para = (n) =>
  Array.from({ length: n }, (_, i) => `<p>Paragraph ${i + 1}. The traders weighed their loads by the handful and argued about the weather, as if the weather had ever listened to a trader, and the road turned inland past terraces of thyme.</p>`).join("");
const MANUSCRIPT =
  `<h1>The Salt Roads</h1>${para(3)}<h2>The coast</h2>${para(6)}` +
  `<h2>The inland markets</h2>${para(6)}<h3>The magistrate</h3>${para(5)}<h2>The rains</h2>${para(7)}`;

const browser = await chromium.launch();
async function run(zen) {
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));
  await page.route(/\/api\/auth\//, (r) => r.fulfill({ contentType: "application/json", body: "null" }));
  await page.route("**/__scroll-seed", (r) => r.fulfill({ contentType: "text/html", body: "<!doctype html><title>Seed</title>" }));
  await page.goto(`${base}/__scroll-seed`);
  await page.evaluate(async ({ html, zen }) => {
    const idb = await import(/* @vite-ignore */ "/src/utils/idb.ts");
    const now = Date.now();
    await idb.saveFoliosToIdb([{ id: "f-s", name: "The Salt Roads", type: "draft", createdAt: now, updatedAt: now }]);
    await idb.saveActiveFolioIdToIdb("f-s");
    await idb.saveFolioContentToIdb("f-s", html);
    await idb.saveMetaToIdb("live-review-enabled", false);
    await idb.saveMetaToIdb("signin-toast-dismissed", true);
    localStorage.setItem("living-desk-open", "false");
    localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: zen, compositorOpen: false }));
    localStorage.setItem("twyne.appearance.motion", "full");
  }, { html: MANUSCRIPT, zen });
  await page.goto(`${base}/editor/`);
  await page.locator("#twyne-editor-mount .ProseMirror").waitFor({ timeout: 90000 });
  await page.waitForTimeout(2500);
  const label = zen ? "zen" : "chrome";
  const foot = () =>
    page.evaluate(() => document.querySelector(".press-running-foot__text")?.textContent ?? null);
  const lamp = () =>
    page.evaluate(() => {
      const s = document.querySelector(".manuscript-scroller");
      const cs = getComputedStyle(s);
      return { attachment: cs.backgroundAttachment, x: s.style.getPropertyValue("--lamp-x") };
    });
  const scroller = page.locator(".manuscript-scroller");
  const report = { zen, masthead: await page.evaluate(() => !!document.querySelector("header:not([hidden]) .masthead-wordmark")) };
  report.atTop = await foot();
  report.lamp = await lamp();
  await page.screenshot({ path: `${outDir}/${label}-top.png` });
  const positions = [];
  for (const heading of ["The coast", "The inland markets", "The magistrate", "The rains"]) {
    await page.evaluate((text) => {
      const h = [...document.querySelectorAll("#twyne-editor-mount .ProseMirror :is(h2,h3)")].find((el) => el.textContent.includes(text));
      const s = document.querySelector(".manuscript-scroller");
      s.scrollTo({ top: h.getBoundingClientRect().top - s.getBoundingClientRect().top + s.scrollTop - 60 });
    }, heading);
    await page.waitForTimeout(450);
    positions.push([heading, await foot()]);
  }
  report.positions = positions;
  await page.screenshot({ path: `${outDir}/${label}-scrolled.png` });
  await page.locator(".editor-bottom-bar").screenshot({ path: `${outDir}/${label}-status-bar.png` }).catch(() => {});
  // Scroll on into the middle of the last section, then press the foot.
  await scroller.evaluate((el) => el.scrollBy({ top: 500 }));
  await page.waitForTimeout(400);
  report.beforeJump = await foot();
  await page.locator(".press-running-foot__slip").click();
  await page.waitForTimeout(900);
  report.afterJump = await page.evaluate(() => {
    const s = document.querySelector(".manuscript-scroller");
    const h = [...document.querySelectorAll("#twyne-editor-mount .ProseMirror :is(h2,h3)")].find((el) => el.textContent.includes("The rains"));
    return Math.round(h.getBoundingClientRect().top - s.getBoundingClientRect().top);
  });
  report.errors = errors.slice(0, 5);
  console.log(JSON.stringify(report));
  await context.close();
}
await run(true);
await run(false);
await browser.close();

// Record the moments stills cannot show, against a running dev server, and
// write each as <label>-<name>.webm plus a trims.json entry saying where the
// action starts (so the loading of the page can be cut away).
//
// A drawn pointer is overlaid, because headless recordings have none, and the
// lamp and the hold only make sense with a hand on the desk.
//
// Usage (from a worktree root):
//   env -u LD_LIBRARY_PATH node artifacts/qa-recordings/2026-11-05/juice/scripts/motion-clips.mjs \
//     <outDir> <baseUrl> <label> [only,names]
import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

const root = resolve(new URL("../../../../..", import.meta.url).pathname);
const { chromium } = await import(`${root}/node_modules/playwright/index.mjs`);
const outDir = process.argv[2];
const base = process.argv[3];
const label = process.argv[4] ?? "clip";
const only = process.argv[5] ? new Set(process.argv[5].split(",")) : null;
mkdirSync(outDir, { recursive: true });
const trimsFile = join(outDir, "trims.json");
const trims = existsSync(trimsFile) ? JSON.parse(readFileSync(trimsFile, "utf8")) : {};

const para = (n, seed) =>
  Array.from({ length: n }, (_, i) => `<p>${seed} ${i + 1}. The traders weighed their loads by the handful and argued about the weather, as if the weather had ever listened to a trader.</p>`).join("");
const MANUSCRIPT =
  `<h1>The Salt Roads</h1>` +
  `<p>The traders weighed their loads by the handful and argued about the weather, as if the weather had ever listened to a trader.</p>` +
  `<p>Morgan kept the ledger. Every sack had a line, every line a price, and every price a story about who had been cheated last season.</p>` +
  `<h2>The inland markets</h2>` +
  `<p>Salt bought silence in the hill towns. A handful pressed into a magistrate's palm could close a dispute that had run for three generations.</p>` +
  `<p>When the rains came early the pans flooded and the price doubled overnight.</p>`;
const LONG =
  `<h1>The Salt Roads</h1>${para(3, "Ledger")}<h2>The coast</h2>${para(5, "Coast")}` +
  `<h2>The inland markets</h2>${para(5, "Market")}<h2>The rains</h2>${para(6, "Rain")}`;

// A pointer drawn into the page, following real pointer events.
const POINTER = `
(() => {
  const draw = () => {
    if (document.getElementById("__clip-pointer")) return;
    const dot = document.createElement("div");
    dot.id = "__clip-pointer";
    dot.innerHTML = '<svg width="22" height="22" viewBox="0 0 22 22"><path d="M3 2 L3 17 L7 13 L10 20 L13 19 L10 12 L16 12 Z" fill="#1f1b16" stroke="#fff" stroke-width="1.3" stroke-linejoin="round"/></svg>';
    dot.style.cssText = "position:fixed;left:0;top:0;z-index:2147483647;pointer-events:none;transform:translate(-200px,-200px);transition:scale 90ms ease;";
    document.documentElement.appendChild(dot);
    addEventListener("pointermove", (e) => { dot.style.transform = "translate(" + (e.clientX - 3) + "px," + (e.clientY - 2) + "px)"; }, true);
    addEventListener("pointerdown", () => { dot.style.scale = "0.82"; }, true);
    addEventListener("pointerup", () => { dot.style.scale = "1"; }, true);
  };
  if (document.readyState === "loading") addEventListener("DOMContentLoaded", draw); else draw();
})();`;

const browser = await chromium.launch({
  args: ["--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader"],
});

async function clip(name, size, html, run) {
  if (only && !only.has(name)) return;
  const tmp = join(outDir, `.${label}-${name}`);
  rmSync(tmp, { recursive: true, force: true });
  const context = await browser.newContext({ viewport: size, deviceScaleFactor: 1, recordVideo: { dir: tmp, size } });
  await context.addInitScript(POINTER);
  const page = await context.newPage();
  const t0 = Date.now();
  let start = 0;
  const mark = () => (start = (Date.now() - t0) / 1000);
  await page.route(/\/api\/auth\//, (r) => r.fulfill({ contentType: "application/json", body: "null" }));
  await page.route("**/__clip-seed", (r) => r.fulfill({ contentType: "text/html", body: "<!doctype html><title>Seed</title>" }));
  await page.goto(`${base}/__clip-seed`);
  await page.evaluate(async (html) => {
    const idb = await import(/* @vite-ignore */ "/src/utils/idb.ts");
    const uc = await import(/* @vite-ignore */ "/src/utils/user-comments.ts");
    const ledgerMod = await import(/* @vite-ignore */ "/src/utils/usage-ledger.ts");
    const now = Date.now();
    await idb.saveFoliosToIdb([{ id: "f-c", name: "The Salt Roads", type: "draft", createdAt: now - 864e5 * 40, updatedAt: now }]);
    await idb.saveActiveFolioIdToIdb("f-c");
    await idb.saveFolioContentToIdb("f-c", html);
    const at = { folioId: "f-c", author: "You", resolved: false, createdAt: now, updatedAt: now, replies: [] };
    await uc.saveUserComments([
      { ...at, id: "c1", text: "Is this literally true?", anchor: "weighed their loads" },
      { ...at, id: "c2", text: "Name the magistrate.", anchor: "magistrate" },
    ]);
    for (let d = 0; d < 30; d++) {
      if (d % 5 === 3) continue;
      for (let m = 0; m < 1 + ((d * 7) % 5); m++) {
        await ledgerMod.usageLedger.recordWritingActivity({ folioId: "f-c", occurredAt: now - d * 864e5 - m * 36e5, throttleMs: 0 });
      }
    }
    await idb.saveMetaToIdb("live-review-enabled", false);
    await idb.saveMetaToIdb("signin-toast-dismissed", true);
    localStorage.setItem("living-desk-open", "false");
    localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
    localStorage.setItem("twyne.appearance.motion", "full");
    localStorage.removeItem("twyne.desk.patterns-seen");
  }, html);
  try {
    await run(page, mark);
  } catch (e) {
    console.log("FAIL", name, e.message.split("\n")[0]);
  }
  const video = page.video();
  const end = (Date.now() - t0) / 1000;
  await context.close();
  const target = join(outDir, `${label}-${name}.webm`);
  renameSync(await video.path(), target);
  rmSync(tmp, { recursive: true, force: true });
  trims[`${label}-${name}`] = { start: Math.max(0, start - 0.25), end };
  writeFileSync(trimsFile, JSON.stringify(trims, null, 2));
  console.log("ok", target, trims[`${label}-${name}`]);
}

const openEditor = async (page) => {
  await page.goto(`${base}/editor/`);
  await page.locator("#twyne-editor-mount .ProseMirror").waitFor({ timeout: 90000 });
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(1500);
};

// Typing a sentence and the save landing: wet ink, then dry.
