// Load the live site the way a writer does and time it: a fresh visit to the
// landing page, then the editor with a real manuscript in IndexedDB, then
// typing, pointer movement and My Desk. Records page errors, console errors,
// failed and still-pending requests, long tasks and frame gaps.
//
// Usage: env -u LD_LIBRARY_PATH node prod-load-check.mjs <outDir> [baseUrl] [paragraphs]
import { mkdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
const root = resolve(new URL("../../../../..", import.meta.url).pathname);
const { chromium } = await import(`${root}/node_modules/playwright/index.mjs`);
const outDir = process.argv[2];
const base = process.argv[3] ?? "https://twyne.love";
const paragraphs = Number(process.argv[4] ?? 60);
mkdirSync(outDir, { recursive: true });

const para = (i) =>
  `<p>Paragraph ${i + 1}. The traders weighed their loads by the handful and argued about the weather, as if the weather had ever listened to a trader, and the road turned inland past terraces of thyme and the white ribs of abandoned pans.</p>`;
let html = "<h1>The Salt Roads</h1>";
for (let i = 0; i < paragraphs; i++) {
  if (i % 12 === 0) html += `<h2>Section ${i / 12 + 1}</h2>`;
  html += para(i);
}

const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await context.newPage();
const log = { pageErrors: [], consoleErrors: [], failed: [], pending: new Map(), timeline: [] };
const t0 = Date.now();
const note = (event, extra = {}) => {
  log.timeline.push({ t: Date.now() - t0, event, ...extra });
  console.log(`${String(Date.now() - t0).padStart(6)}ms  ${event}`, Object.keys(extra).length ? JSON.stringify(extra) : "");
};
page.on("pageerror", (e) => log.pageErrors.push(e.message.slice(0, 300)));
page.on("console", (m) => { if (m.type() === "error") log.consoleErrors.push(m.text().slice(0, 300)); });
page.on("request", (r) => log.pending.set(r, { url: r.url(), at: Date.now() - t0 }));
page.on("requestfinished", (r) => log.pending.delete(r));
page.on("requestfailed", (r) => { log.pending.delete(r); log.failed.push(`${r.failure()?.errorText} ${r.url().slice(0, 160)}`); });
// Keep test traffic out of production analytics.
await page.route(/posthog|i\.posthog\.com/, (r) => r.abort());

await page.addInitScript(() => {
  window.__longTasks = [];
  try {
    new PerformanceObserver((list) => {
      for (const e of list.getEntries()) window.__longTasks.push({ start: Math.round(e.startTime), dur: Math.round(e.duration) });
    }).observe({ type: "longtask", buffered: true });
  } catch {}
});

const pendingNow = () =>
  [...log.pending.values()].filter((p) => !/convex\.cloud|wss?:/.test(p.url)).map((p) => `${p.at}ms ${p.url.slice(0, 140)}`);

// 1. Landing page, fresh profile.
note("goto /");
await page.goto(`${base}/`, { waitUntil: "load", timeout: 90000 });
note("landing load");
await page.waitForTimeout(2000);
note("landing settled", { longTasks: await page.evaluate(() => window.__longTasks.length) });

// 2. Seed a manuscript through the app's own database (let the app create it).
await page.goto(`${base}/editor/`, { waitUntil: "load", timeout: 90000 });
await page.waitForTimeout(2500);
note("empty editor visited", { url: page.url() });
const seeded = await page.evaluate(async (html) => {
  const db = await new Promise((res, rej) => { const r = indexedDB.open("twyne"); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
  const stores = [...db.objectStoreNames];
  const now = Date.now();
  const put = (store, value) => new Promise((res, rej) => { const t = db.transaction(store, "readwrite"); t.objectStore(store).put(value); t.oncomplete = res; t.onerror = () => rej(t.error); });
  await put("folios", { id: "f-check", name: "The Salt Roads", type: "draft", createdAt: now - 864e5, updatedAt: now });
  await put("folio-content", { folioId: "f-check", html, updatedAt: now });
  await put("meta", { key: "active-folio-id", value: "f-check", updatedAt: now });
  await put("meta", { key: "signin-toast-dismissed", value: true, updatedAt: now });
  await put("meta", { key: "live-review-enabled", value: false, updatedAt: now });
  localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
  db.close();
  return { version: db.version, stores };
}, html);
note("seeded", seeded);

// 3. Open the editor with the manuscript.
const t1 = Date.now();
await page.goto(`${base}/editor/`, { waitUntil: "commit", timeout: 90000 });
let shellAt = null, textAt = null, gateSeen = false;
for (let i = 0; i < 300; i++) {
  const s = await page.evaluate(() => ({
    gate: !!document.querySelector(".press-hydration") || [...document.querySelectorAll(".folio")].some((e) => e.textContent?.includes("Setting the type")),
    shell: !!document.querySelector(".editor-workspace-shell"),
    text: !!document.querySelector("#twyne-editor-mount .ProseMirror"),
  })).catch(() => ({}));
  if (s.gate) gateSeen = true;
  if (s.shell && shellAt === null) shellAt = Date.now() - t1;
  if (s.text) { textAt = Date.now() - t1; break; }
  await page.waitForTimeout(100);
}
note("editor opened", { gateSeen, shellAt, textAt, url: page.url() });
await page.screenshot({ path: `${outDir}/editor.png` });
if (textAt === null) {
  note("EDITOR NEVER SHOWED TEXT", { pending: pendingNow().slice(0, 15) });
} else {
  await page.waitForTimeout(1500);
  const lt = await page.evaluate(() => window.__longTasks.slice(-30));
  note("long tasks after open", { count: lt.length, worst: lt.sort((a, b) => b.dur - a.dur).slice(0, 5) });

  // 4. Frame gaps while the pointer wanders (the desk lamp).
  const frames = await page.evaluate(() => new Promise((res) => {
    const gaps = []; let last = performance.now(); let n = 0;
    const tick = (now) => { gaps.push(now - last); last = now; if (++n < 150) requestAnimationFrame(tick); else res(gaps); };
    requestAnimationFrame(tick);
  }).then((g) => g) );
  void frames;
  const moveProbe = page.evaluate(() => new Promise((res) => {
    const gaps = []; let last = performance.now(); let n = 0;
    const tick = (now) => { gaps.push(now - last); last = now; if (++n < 180) requestAnimationFrame(tick); else res(gaps); };
    requestAnimationFrame(tick);
  }));
  for (let i = 0; i < 40; i++) await page.mouse.move(100 + (i * 31) % 1200, 150 + (i * 47) % 600, { steps: 3 });
  const gaps = await moveProbe;
  const sorted = [...gaps].sort((a, b) => a - b);
  note("frames while moving pointer", { p50: +sorted[Math.floor(sorted.length * 0.5)].toFixed(1), p95: +sorted[Math.floor(sorted.length * 0.95)].toFixed(1), max: +sorted[sorted.length - 1].toFixed(1) });

  // 5. Typing latency (key to next frame), a short burst.
  await page.locator("#twyne-editor-mount .ProseMirror p").nth(2).click();
  await page.keyboard.press("End");
  const lat = [];
  for (const ch of " The ledger kept its own counsel.") {
    const start = await page.evaluate(() => performance.now());
    await page.keyboard.type(ch);
    const end = await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => r(performance.now()))));
    lat.push(end - start);
  }
  const ls = [...lat].sort((a, b) => a - b);
  note("typing key-to-frame (incl. CDP overhead)", { p50: +ls[Math.floor(ls.length / 2)].toFixed(1), p95: +ls[Math.floor(ls.length * 0.95)].toFixed(1), max: +ls[ls.length - 1].toFixed(1) });
  await page.waitForTimeout(3000);
  note("after typing", { wet: await page.evaluate(() => !!CSS.highlights?.has("twyne-ink-wet")), saved: await page.evaluate(() => document.querySelector(".editor-last-saved")?.textContent?.trim()) });
}

// 6. My Desk.
const t2 = Date.now();
await page.goto(`${base}/desk/`, { waitUntil: "commit", timeout: 90000 });
let deskAt = null;
for (let i = 0; i < 300; i++) {
  const ok = await page.evaluate(() => !!document.querySelector("#patterns-heading, [aria-labelledby=patterns-heading]")).catch(() => false);
  if (ok) { deskAt = Date.now() - t2; break; }
  await page.waitForTimeout(100);
}
note("desk opened", { deskAt, loaderStill: await page.evaluate(() => document.body.innerText.includes("Reading the ledger")).catch(() => null) });
await page.screenshot({ path: `${outDir}/desk.png` });
await page.waitForTimeout(3000);
note("desk +3s", { longTasks: await page.evaluate(() => window.__longTasks.length) });

note("done", { pageErrors: log.pageErrors.slice(0, 8), consoleErrors: log.consoleErrors.slice(0, 8), failed: log.failed.slice(0, 10), pending: pendingNow().slice(0, 10) });
writeFileSync(`${outDir}/report.json`, JSON.stringify({ ...log, pending: pendingNow() }, null, 2));
await browser.close();

