// Is the desk lamp expensive? Frame gaps while the pointer moves over the
// editor, with the lamp on (motion=full) and off (motion=calm), after a
// warm-up pass so first-interaction code loading is excluded. Also times
// opening the editor at each level.
// Usage: env -u LD_LIBRARY_PATH node lamp-cost.mjs <baseUrl> <paragraphs> <engine>
import { resolve } from "node:path";
const root = resolve(new URL("../../../../..", import.meta.url).pathname);
const { chromium, firefox } = await import(`${root}/node_modules/playwright/index.mjs`);
const base = process.argv[2] ?? "https://twyne.love";
const paragraphs = Number(process.argv[3] ?? 400);
const engine = process.argv[4] ?? "firefox";

let html = "<h1>The Salt Roads</h1>";
for (let i = 0; i < paragraphs; i++) {
  if (i % 12 === 0) html += `<h2>Section ${i / 12 + 1}</h2>`;
  html += `<p>Paragraph ${i + 1}. The traders weighed their loads by the handful and argued about the weather, as if the weather had ever listened to a trader, and the road turned inland past terraces of thyme.</p>`;
}

const browser = await (engine === "firefox" ? firefox : chromium).launch();
const stats = (gaps) => {
  const s = [...gaps].sort((a, b) => a - b);
  const q = (p) => +s[Math.min(s.length - 1, Math.floor(s.length * p))].toFixed(1);
  return { n: s.length, p50: q(0.5), p95: q(0.95), max: q(1), over50: s.filter((g) => g > 50).length };
};

async function run(level) {
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();
  await page.route(/posthog/, (r) => r.abort());
  await page.goto(`${base}/editor/`, { waitUntil: "load" });
  await page.waitForTimeout(2000);
  await page.evaluate(async ({ html, level }) => {
    const db = await new Promise((res, rej) => { const r = indexedDB.open("twyne"); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
    const now = Date.now();
    const put = (store, value) => new Promise((res, rej) => { const t = db.transaction(store, "readwrite"); t.objectStore(store).put(value); t.oncomplete = res; t.onerror = () => rej(t.error); });
    await put("folios", { id: "f-lamp", name: "The Salt Roads", type: "draft", createdAt: now, updatedAt: now });
    await put("folio-content", { folioId: "f-lamp", html, updatedAt: now });
    await put("meta", { key: "active-folio-id", value: "f-lamp", updatedAt: now });
    await put("meta", { key: "signin-toast-dismissed", value: true, updatedAt: now });
    await put("meta", { key: "live-review-enabled", value: false, updatedAt: now });
    localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
    localStorage.setItem("twyne.appearance.motion", level);
    db.close();
  }, { html, level });
  const t = Date.now();
  await page.goto(`${base}/editor/`, { waitUntil: "commit" });
  await page.locator("#twyne-editor-mount .ProseMirror").waitFor({ timeout: 120000 });
  const openMs = Date.now() - t;
  await page.waitForTimeout(2500);
  const lampOn = await page.evaluate(() => ({ motion: document.documentElement.dataset.motion, lamp: document.querySelector(".manuscript-scroller")?.classList.contains("desk-lamp") }));
  const pass = async () => {
    const probe = page.evaluate(() => new Promise((res) => {
      const gaps = []; let last = performance.now(); let n = 0;
      const tick = (now) => { gaps.push(now - last); last = now; if (++n < 240) requestAnimationFrame(tick); else res(gaps); };
      requestAnimationFrame(tick);
    }));
    for (let i = 0; i < 60; i++) await page.mouse.move(80 + ((i * 97) % 1280), 160 + ((i * 53) % 640), { steps: 4 });
    return probe;
  };
  await pass(); // warm-up: loads hover handlers etc.
  const gaps = await pass();
  await context.close();
  return { level, openMs, ...lampOn, frames: stats(gaps) };
}

