// Twyne load + responsiveness metric, for hill climbing.
//
// Measures a production build (served by `node server.js`) the way a writer
// meets it, in Firefox by default (the reporter's browser), with a large
// manuscript seeded into IndexedDB through the app's own database.
//
// Per repetition (a fresh browser context each time):
//   landingMs  fresh visit to /: navigation start -> load event
//   openMs     /editor/ with the manuscript: navigation start -> editor text shown
//   editableMs navigation start -> editor accepts input (contenteditable=true)
//   frameP95   frame gap p95 (ms) while the pointer wanders over the editor,
//              measured on a second pass (the first pass loads hover code)
//   frameMax   worst frame in that pass
//   typeP95    key -> next frame latency p95 (ms) over a 30-character burst
//   deskMs     /desk/: navigation start -> the ledger's sections shown
//   errors     page errors + console errors (analytics requests excluded)
//
// score (lower is better) = openMs/1000 + deskMs/1000 + landingMs/1000
//                         + frameP95/16.7 + typeP95/16.7
// i.e. one second of waiting weighs the same as one dropped 60 Hz frame at p95.
//
// Usage (run from a Twyne checkout, so its node_modules/playwright is used):
//   PLAYWRIGHT_SKIP_VALIDATE_HOST_REQUIREMENTS=1 env -u LD_LIBRARY_PATH \
//     node /home/diogenes/.t3/worktrees/twyne/perf-harness/perf-metric.mjs \
//       --url http://127.0.0.1:5196 [--engine firefox|chromium] [--reps 3] \
//       [--paragraphs 600] [--out result.json] [--label "baseline"]
import { writeFileSync } from "node:fs";
import { resolve } from "node:path";

const arg = (name, fallback) => {
  const i = process.argv.indexOf(`--${name}`);
  return i > -1 ? process.argv[i + 1] : fallback;
};
const url = arg("url", "http://127.0.0.1:5196");
const engine = arg("engine", "firefox");
const reps = Number(arg("reps", 3));
const paragraphs = Number(arg("paragraphs", 600));
const out = arg("out", null);
const label = arg("label", "");

const { chromium, firefox } = await import(
  resolve(process.cwd(), "node_modules/playwright/index.mjs")
);

// A long manuscript with sections, persona notes and the writer's comments.
function manuscript(count) {
  let html = "<h1>The Salt Roads</h1>";
  for (let i = 0; i < count; i++) {
    if (i % 12 === 0) html += `<h2>Section ${i / 12 + 1}: the inland road</h2>`;
    const note =
      i % 9 === 4
        ? `<span data-persona-note-id="n${i}" data-persona-note-author="Marguerite" data-persona-note-color="#b0413e" data-persona-note-label="Pacing" data-persona-note-note="This sentence carries three ideas; let the second breathe." data-persona-note-quote="weighed their loads">weighed their loads</span>`
        : "weighed their loads";
    const comment =
      i % 13 === 6
        ? `<span class="twyne-comment-mark" data-comment-id="c${i}" data-comment-author="You">the road forgot the sea</span>`
        : "the road forgot the sea";
    html += `<p>Paragraph ${i + 1}. The traders ${note} by the handful and argued about the weather, as if the weather had ever listened to a trader; by the fourth day ${comment} entirely and turned inland, past terraces of thyme and the white ribs of abandoned pans.</p>`;
  }
  return html;
}

const INIT = () => {
  // Record, against the navigation's own clock, when the editor and the desk
  // first appear and when the editor becomes editable.
  window.__marks = {};
  const check = () => {
    const pm = document.querySelector("#twyne-editor-mount .ProseMirror");
    if (pm && window.__marks.open === undefined) window.__marks.open = performance.now();
    if (pm?.getAttribute("contenteditable") === "true" && window.__marks.editable === undefined)
      window.__marks.editable = performance.now();
    if (document.querySelector("#patterns-heading") && window.__marks.desk === undefined)
      window.__marks.desk = performance.now();
  };
  new MutationObserver(check).observe(document, { subtree: true, childList: true, attributes: true, attributeFilter: ["contenteditable"] });
};

const stats = (values) => {
  const s = [...values].sort((a, b) => a - b);
  const q = (p) => s[Math.min(s.length - 1, Math.floor(s.length * p))];
  return { p50: q(0.5), p95: q(0.95), max: s[s.length - 1] };
};
const median = (xs) => {
  const s = [...xs].filter((x) => Number.isFinite(x)).sort((a, b) => a - b);
  return s.length ? s[Math.floor(s.length / 2)] : NaN;
};
const round = (x) => (Number.isFinite(x) ? Math.round(x * 10) / 10 : x);

const browser = await (engine === "chromium" ? chromium : firefox).launch();
const html = manuscript(paragraphs);
const runs = [];

for (let rep = 0; rep < reps; rep++) {
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  await context.addInitScript(INIT);
  const page = await context.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(`pageerror: ${e.message.slice(0, 200)}`));
  page.on("console", (m) => {
    if (m.type() === "error" && !/posthog/i.test(m.text())) errors.push(`console: ${m.text().slice(0, 200)}`);
  });
  await page.route(/posthog/, (r) => r.abort());

  // 1. Landing, fresh profile.
  await page.goto(`${url}/`, { waitUntil: "load", timeout: 120000 });
  const landingMs = await page.evaluate(() => performance.getEntriesByType("navigation")[0]?.loadEventEnd ?? NaN);

  // 2. Let the app create its database, then seed a manuscript into it.
  await page.goto(`${url}/editor/`, { waitUntil: "load", timeout: 120000 });
  await page.waitForTimeout(1500);
  await page.evaluate(async (html) => {
    const db = await new Promise((res, rej) => { const r = indexedDB.open("twyne"); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
    const now = Date.now();
    const put = (store, value) => new Promise((res, rej) => { const t = db.transaction(store, "readwrite"); t.objectStore(store).put(value); t.oncomplete = res; t.onerror = () => rej(t.error); });
    await put("folios", { id: "f-metric", name: "The Salt Roads", type: "draft", createdAt: now - 864e5 * 30, updatedAt: now });
    await put("folios", { id: "f-metric-2", name: "Letters from the pans", type: "draft", createdAt: now - 864e5 * 9, updatedAt: now - 864e5 });
    await put("folio-content", { folioId: "f-metric", html, updatedAt: now });
    await put("folio-content", { folioId: "f-metric-2", html: "<p>Dear R., the pans are quiet this year.</p>", updatedAt: now });
    await put("meta", { key: "active-folio-id", value: "f-metric", updatedAt: now });
    await put("meta", { key: "signin-toast-dismissed", value: true, updatedAt: now });
    await put("meta", { key: "live-review-enabled", value: false, updatedAt: now });
    localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
    db.close();
  }, html);

  // 3. Open the editor with the manuscript.
  await page.goto(`${url}/editor/`, { waitUntil: "commit", timeout: 120000 });
  await page.waitForFunction(() => window.__marks?.open !== undefined, null, { timeout: 120000, polling: 100 });
  await page.waitForFunction(() => window.__marks?.editable !== undefined, null, { timeout: 120000, polling: 100 }).catch(() => {});
  const { open: openMs, editable: editableMs } = await page.evaluate(() => window.__marks);
  await page.waitForTimeout(2500);

  // 4. Frames while the pointer wanders (second pass is measured).
  const pass = async () => {
    const probe = page.evaluate(() => new Promise((res) => {
      const gaps = []; let last = performance.now(); let n = 0;
      const tick = (now) => { gaps.push(now - last); last = now; if (++n < 240) requestAnimationFrame(tick); else res(gaps); };
      requestAnimationFrame(tick);
    }));
    for (let i = 0; i < 60; i++) await page.mouse.move(80 + ((i * 97) % 1280), 160 + ((i * 53) % 640), { steps: 4 });
    return probe;
  };
  await pass();
  const frames = stats(await pass());

  // 5. Typing: key -> next frame.
  await page.locator("#twyne-editor-mount .ProseMirror p").nth(3).click();
  await page.keyboard.press("End");
  const lat = [];
  for (const ch of " The ledger kept its own counsel") {
    const start = await page.evaluate(() => performance.now());
    await page.keyboard.type(ch);
    const end = await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => r(performance.now()))));
    lat.push(end - start);
  }
  const typing = stats(lat);
  await page.waitForTimeout(1500);

  // 6. My Desk.
  await page.goto(`${url}/desk/`, { waitUntil: "commit", timeout: 120000 });
  await page.waitForFunction(() => window.__marks?.desk !== undefined, null, { timeout: 120000, polling: 100 }).catch(() => {});
  const deskMs = await page.evaluate(() => window.__marks?.desk ?? NaN);

  const run = {
    landingMs: round(landingMs),
    openMs: round(openMs),
    editableMs: round(editableMs),
    frameP95: round(frames.p95),
    frameMax: round(frames.max),
    typeP95: round(typing.p95),
    typeP50: round(typing.p50),
    deskMs: round(deskMs),
    errors: [...new Set(errors)].slice(0, 6),
  };
  runs.push(run);
  console.error(`rep ${rep + 1}/${reps}`, JSON.stringify(run));
  await context.close();
}
await browser.close();

const keys = ["landingMs", "openMs", "editableMs", "frameP95", "frameMax", "typeP95", "typeP50", "deskMs"];
const medians = Object.fromEntries(keys.map((k) => [k, round(median(runs.map((r) => r[k])))]));
const score = round(
  medians.openMs / 1000 + medians.deskMs / 1000 + medians.landingMs / 1000 + medians.frameP95 / 16.7 + medians.typeP95 / 16.7,
);
const result = { label, url, engine, paragraphs, reps, score, medians, errors: [...new Set(runs.flatMap((r) => r.errors))], runs, at: new Date().toISOString() };
console.log(JSON.stringify({ label, engine, score, medians, errors: result.errors }));
if (out) writeFileSync(out, JSON.stringify(result, null, 2));

