// Several Twyne tabs in one Firefox profile, against a production build.
//
// For N = 1..maxTabs editor tabs (all on the same 600-paragraph manuscript,
// opened one after another), measures:
//   openMs[k]    time for tab k's editor to show its text while k-1 tabs are open
//   idleCpu      CPU (% of one core, all Firefox processes) over 20s with every
//                tab idle (the last one in front)
//   rssMB        total RSS of all Firefox processes
//   typeP95      key -> painted frame p95 in the front tab with the others open
//   frameP95     frame gap p95 while the pointer wanders in the front tab
// Then checks whether two tabs on the same piece overwrite each other's words.
//
// Usage (from a Twyne checkout):
//   PLAYWRIGHT_SKIP_VALIDATE_HOST_REQUIREMENTS=1 env -u LD_LIBRARY_PATH \
//     node multi-tab.mjs --url http://127.0.0.1:5197 [--tabs 5] [--shared] [--out file]
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const arg = (name, fallback) => {
  const i = process.argv.indexOf(`--${name}`);
  return i > -1 ? process.argv[i + 1] : fallback;
};
const url = arg("url", "http://127.0.0.1:5197");
const maxTabs = Number(arg("tabs", 5));
const shared = process.argv.includes("--shared");
const out = arg("out", null);
const { firefox } = await import(resolve(process.cwd(), "node_modules/playwright/index.mjs"));

let html = "<h1>The Salt Roads</h1>";
for (let i = 0; i < 600; i++) {
  if (i % 12 === 0) html += `<h2>Section ${i / 12 + 1}</h2>`;
  html += `<p>Paragraph ${i + 1}. The traders weighed their loads by the handful and argued about the weather, as if the weather had ever listened to a trader, and the road turned inland past terraces of thyme and the white ribs of abandoned pans.</p>`;
}

// ── Process accounting for Playwright's Firefox only ─────────────────────
const TICK = 100; // clock ticks per second on Linux
function playwrightFirefoxPids() {
  const pids = [];
  for (const entry of readdirSync("/proc")) {
    if (!/^\d+$/.test(entry)) continue;
    try {
      const cmd = readFileSync(`/proc/${entry}/cmdline`, "utf8");
      if (cmd.includes("ms-playwright/firefox-")) pids.push(Number(entry));
    } catch {}
  }
  return pids;
}
function cpuTicks(pids) {
  let total = 0;
  for (const pid of pids) {
    try {
      const stat = readFileSync(`/proc/${pid}/stat`, "utf8");
      const fields = stat.slice(stat.lastIndexOf(")") + 2).split(" ");
      total += Number(fields[11]) + Number(fields[12]); // utime + stime
    } catch {}
  }
  return total;
}
function rssMB(pids) {
  let kb = 0;
  for (const pid of pids) {
    try {
      const m = readFileSync(`/proc/${pid}/status`, "utf8").match(/VmRSS:\s+(\d+)/);
      if (m) kb += Number(m[1]);
    } catch {}
  }
  return Math.round(kb / 1024);
}
async function idleCpu(seconds) {
  const pids = playwrightFirefoxPids();
  const a = cpuTicks(pids);
  const t = Date.now();
  await new Promise((r) => setTimeout(r, seconds * 1000));
  const used = (cpuTicks(playwrightFirefoxPids()) - a) / TICK;
  return Math.round((used / ((Date.now() - t) / 1000)) * 1000) / 10; // % of a core
}

const browser = await firefox.launch({
  firefoxUserPrefs: shared ? { "dom.ipc.processCount.webIsolated": 1 } : {},
});
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
await context.addInitScript(() => {
  window.__marks = {};
  new MutationObserver(() => {
    if (window.__marks.open === undefined && document.querySelector("#twyne-editor-mount .ProseMirror"))
      window.__marks.open = performance.now();
  }).observe(document, { subtree: true, childList: true });
  window.__keyLat = [];
  addEventListener("keydown", (e) => {
    const t0 = e.timeStamp;
    requestAnimationFrame(() => setTimeout(() => window.__keyLat.push(performance.now() - t0), 0));
  }, true);
});
await context.route(/posthog/, (r) => r.abort());

// Seed through the app's own database.
const seedPage = await context.newPage();
await seedPage.goto(`${url}/editor/`, { waitUntil: "load" });
