async function measureFront(page) {
  await page.bringToFront();
  await page.waitForTimeout(800);
  // Frames while the pointer wanders (second pass measured).
  const pass = async () => {
    const probe = page.evaluate(() => new Promise((res) => {
      const gaps = []; let last = performance.now(); let n = 0;
      const tick = (now) => { gaps.push(now - last); last = now; if (++n < 180) requestAnimationFrame(tick); else res(gaps); };
      requestAnimationFrame(tick);
    }));
    for (let i = 0; i < 45; i++) await page.mouse.move(80 + ((i * 97) % 1280), 160 + ((i * 53) % 640), { steps: 4 });
    return probe;
  };
  await pass();
  const frames = stats(await pass());
  await page.locator("#twyne-editor-mount .ProseMirror p").nth(4).click();
