// What does one idle editor tab do? Opens the editor with a 600-paragraph
// manuscript, waits for it to settle, then for 40s records: workers created,
// network requests by URL, console errors, and CPU of Playwright's Firefox.
// Usage: PLAYWRIGHT_SKIP_VALIDATE_HOST_REQUIREMENTS=1 env -u LD_LIBRARY_PATH \
//   node idle-tab.mjs --url http://127.0.0.1:5197 [--engine firefox|chromium] [--hidden]
import { readFileSync, readdirSync } from "node:fs";
import { resolve } from "node:path";
const arg = (name, fallback) => {
  const i = process.argv.indexOf(`--${name}`);
  return i > -1 ? process.argv[i + 1] : fallback;
};
const url = arg("url", "http://127.0.0.1:5197");
const engine = arg("engine", "firefox");
const hidden = process.argv.includes("--hidden");
const seconds = Number(arg("seconds", 40));
const pw = await import(resolve(process.cwd(), "node_modules/playwright/index.mjs"));

function pids() {
  const marker = engine === "firefox" ? "ms-playwright/firefox-" : "ms-playwright/chromium";
  return readdirSync("/proc").filter((p) => /^\d+$/.test(p)).filter((p) => {
    try { return readFileSync(`/proc/${p}/cmdline`, "utf8").includes(marker); } catch { return false; }
  });
}
function ticks() {
  let t = 0;
  for (const p of pids()) {
    try {
      const s = readFileSync(`/proc/${p}/stat`, "utf8");
      const f = s.slice(s.lastIndexOf(")") + 2).split(" ");
      t += Number(f[11]) + Number(f[12]);
    } catch {}
  }
  return t;
}

let html = "<h1>The Salt Roads</h1>";
for (let i = 0; i < 600; i++) {
  if (i % 12 === 0) html += `<h2>Section ${i / 12 + 1}</h2>`;
  html += `<p>Paragraph ${i + 1}. The traders weighed their loads by the handful and argued about the weather, as if the weather had ever listened to a trader.</p>`;
}

const browser = await pw[engine].launch();
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
await context.route(/posthog/, (r) => r.abort());
const page = await context.newPage();
await page.goto(`${url}/editor/`, { waitUntil: "load" });
await page.waitForTimeout(1500);
await page.evaluate(async (html) => {
  const db = await new Promise((res, rej) => { const r = indexedDB.open("twyne"); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
  const now = Date.now();
  const put = (store, value) => new Promise((res, rej) => { const t = db.transaction(store, "readwrite"); t.objectStore(store).put(value); t.oncomplete = res; t.onerror = () => rej(t.error); });
  await put("folios", { id: "f-idle", name: "The Salt Roads", type: "draft", createdAt: now, updatedAt: now });
  await put("folio-content", { folioId: "f-idle", html, updatedAt: now });
  await put("meta", { key: "active-folio-id", value: "f-idle", updatedAt: now });
  await put("meta", { key: "signin-toast-dismissed", value: true, updatedAt: now });
  await put("meta", { key: "live-review-enabled", value: false, updatedAt: now });
  localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
  db.close();
}, html);

const workers = [];
const requests = new Map();
const consoleErrors = new Map();
let recording = false;
page.on("worker", (w) => { if (recording) workers.push(w.url().slice(0, 140)); });
context.on("request", (r) => {
  if (!recording) return;
  const key = `${r.method()} ${r.url().replace(/\?.*$/, "").slice(0, 120)}${r.serviceWorker() ? " [sw]" : ""}`;
  requests.set(key, (requests.get(key) ?? 0) + 1);
});
page.on("console", (m) => {
  if (!recording || (m.type() !== "error" && m.type() !== "warning")) return;
  const key = `${m.type()}: ${m.text().slice(0, 160)}`;
  consoleErrors.set(key, (consoleErrors.get(key) ?? 0) + 1);
});

await page.goto(`${url}/editor/`, { waitUntil: "load" });
await page.locator("#twyne-editor-mount .ProseMirror").waitFor({ timeout: 120000 });
await page.waitForTimeout(8000); // settle
if (hidden) {
  const other = await context.newPage();
  await other.goto("about:blank");
  await other.bringToFront();
}
const visibility = await page.evaluate(() => document.visibilityState);
recording = true;
const t0 = ticks();
const start = Date.now();
await page.waitForTimeout(seconds * 1000);
const cpu = ((ticks() - t0) / 100 / ((Date.now() - start) / 1000)) * 100;
recording = false;

console.log(JSON.stringify({ engine, visibility, seconds, cpuPctOfCore: Math.round(cpu) }));
console.log("workers created while idle:", workers.length, JSON.stringify([...new Set(workers)].slice(0, 6)));
console.log("requests while idle:");
for (const [k, n] of [...requests].sort((a, b) => b[1] - a[1]).slice(0, 20)) console.log(`  ${String(n).padStart(4)}  ${k}`);
console.log("console errors/warnings while idle:");
for (const [k, n] of [...consoleErrors].sort((a, b) => b[1] - a[1]).slice(0, 12)) console.log(`  ${String(n).padStart(4)}  ${k}`);
await browser.close();

