/**
 * Keep SQLite/Lix and its JSON plugin out of the editor's static module graph.
 * All SDK operations were already asynchronous; only loading their code moves
 * behind that boundary. Native module imports share the in-flight load.
 */
type Sdk = typeof import("@lix-js/sdk");

export const closeLix: Sdk["closeLix"] = async (...args) =>
  (await import("@lix-js/sdk")).closeLix(...args);
export async function openLixInMemory(
  ...args: Parameters<Sdk["openLixInMemory"]>
) {
  return (await import("@lix-js/sdk")).openLixInMemory(...args);
}
export const createVersion: Sdk["createVersion"] = async (...args) =>
  (await import("@lix-js/sdk")).createVersion(...args);
export const switchVersion: Sdk["switchVersion"] = async (...args) =>
  (await import("@lix-js/sdk")).switchVersion(...args);
export const mergeVersion: Sdk["mergeVersion"] = async (...args) =>
  (await import("@lix-js/sdk")).mergeVersion(...args);
export const toBlob: Sdk["toBlob"] = async (...args) =>
  (await import("@lix-js/sdk")).toBlob(...args);

export async function openJsonLix(
  options: Omit<Parameters<Sdk["openLixInMemory"]>[0], "providePlugins">,
) {
  const [sdk, { plugin }] = await Promise.all([
    import("@lix-js/sdk"),
    import("@lix-js/plugin-json"),
  ]);
  return sdk.openLixInMemory({
    ...options,
    providePlugins: [plugin as unknown as any],
  });
}

