const RECOVERY_KEY = "twyne:chunk-recovery:v1";

/** Kept self-contained so it can run before any Qwik module is fetched. */
export function installChunkRecovery(host: Window): void {
  let checking = false;
  const recover = async (reason: unknown) => {
    if (checking || host.navigator.onLine === false) return;
    const message =
      typeof reason === "string"
        ? reason
        : ((reason as { message?: string } | null)?.message ?? "");
    if (
      !/dynamically imported module|importing a module script failed/i.test(
        message,
      )
    )
      return;
    const raw = message.match(/https?:\/\/[^\s'"<>]+/)?.[0];
    if (!raw) return;
    let url: URL;
    try {
      url = new URL(raw);
      if (
        url.origin !== host.location.origin ||
        !/^\/build\/[^/]+\.js$/.test(url.pathname)
      )
        return;
      if (host.sessionStorage.getItem("twyne:chunk-recovery:v1")) return;
    } catch {
      // Without session storage there is no durable reload-loop guard.
      return;
    }
    checking = true;
    try {
      // Aborts, a lost connection, and application exceptions aren't evidence
      // of deploy skew. Confirm that this exact module is gone before reloading.
      const response = await host.fetch(url.href, {
        method: "HEAD",
        cache: "no-store",
        credentials: "omit",
      });
      if (
        (response.status === 404 || response.status === 410) &&
        host.document.visibilityState !== "hidden"
      ) {
        host.sessionStorage.setItem("twyne:chunk-recovery:v1", "1");
        // The editor's existing pagehide path flushes to its crash mirror
        // synchronously, so an in-flight debounce survives this navigation.
        host.location.reload();
      }
    } catch {
      // Offline and cache failures must not start a reload loop.
    } finally {
      checking = false;
    }
  };
  host.document.addEventListener("qerror", (event) => {
    const detail = (event as CustomEvent<{ error?: unknown }>).detail;
    void recover(detail?.error);
  });
  host.addEventListener("unhandledrejection", (event) => {
    void recover(event.reason);
  });
}

export const CHUNK_RECOVERY_SCRIPT = `(${installChunkRecovery.toString()})(window);`;
export { RECOVERY_KEY };
