const settle = () => new Promise((resolve) => setTimeout(resolve, 0));

describe("stale chunk recovery", () => {
  test("confirms a missing same-origin module and reloads once across a session", async () => {
    const h = harness();
    h.reject(failure);
    h.reject(failure);
    await settle();
    expect(h.reloads()).toBe(1);
    expect(h.storage.get(RECOVERY_KEY)).toBe("1");
    const nextPage = harness(404, h.storage);
    nextPage.reject(failure);
    await settle();
    expect(nextPage.reloads()).toBe(0);
    expect(nextPage.probes).toHaveLength(0);
  });

  test("also handles Qwik's import error event", async () => {
    const h = harness();
    h.events.get("qerror")!({ detail: { error: new TypeError(failure) } });
    await settle();
    expect(h.reloads()).toBe(1);
  });

  test("does not reload for successful probes, transient failures, external modules, or app exceptions", async () => {
    for (const status of [200, 500, 503]) {
      const h = harness(status);
      h.reject(failure);
      await settle();
      expect(h.reloads()).toBe(0);
    }
    const h = harness();
    h.reject("fetch failed");
    h.reject("Application failed in https://twyne.example/build/q-app.js");
    h.reject(failure.replace("twyne.example", "external.example"));
    await settle();
    expect(h.probes).toHaveLength(0);
    expect(h.reloads()).toBe(0);
  });

  test("offline, hidden, or storage-blocked pages cannot enter a reload loop", async () => {
    const offline = harness();
    offline.host.navigator.onLine = false;
    offline.reject(failure);
    const hidden = harness();
    hidden.host.document.visibilityState = "hidden";
    hidden.reject(failure);
    const blocked = harness();
    blocked.host.sessionStorage.getItem = () => {
      throw new Error("blocked");
    };
    blocked.reject(failure);
    await settle();
    expect(offline.reloads() + hidden.reloads() + blocked.reloads()).toBe(0);
  });
});

