// A tab left open across a deploy. Opens the editor (build A), signals
// "ready", waits for the outside to swap the server to build B and signal
// "go", then presses File: the menu's code is now a chunk build B no longer
// has. Reports page loads, chunk errors, and whether File works afterwards.
// Usage: PLAYWRIGHT_SKIP_VALIDATE_HOST_REQUIREMENTS=1 env -u LD_LIBRARY_PATH \
//   node skew-tab.mjs <url> <dir-for-markers> [firefox|chromium]
import { existsSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
const [url, dir, engine = "firefox"] = process.argv.slice(2);
const pw = await import(resolve(process.cwd(), "node_modules/playwright/index.mjs"));
const browser = await pw[engine].launch();
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
await context.route(/posthog/, (r) => r.abort());
const page = await context.newPage();
const log = { loads: 0, chunkErrors: [], consoleErrors: [], steps: [] };
const note = (step, extra = {}) => {
  log.steps.push({ at: Date.now(), step, ...extra });
  console.log(step, JSON.stringify(extra));
};
page.on("load", () => log.loads++);
page.on("console", (m) => {
  if (m.type() !== "error") return;
  const t = m.text();
  if (/build\/q-|dynamically imported|qrl/i.test(t)) log.chunkErrors.push(t.slice(0, 200));
  else log.consoleErrors.push(t.slice(0, 160));
});
await page.goto(`${url}/editor/`, { waitUntil: "load" });
await page.waitForTimeout(1500);
await page.evaluate(async () => {
  const db = await new Promise((res, rej) => { const r = indexedDB.open("twyne"); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
  const now = Date.now();
  const put = (store, value) => new Promise((res, rej) => { const t = db.transaction(store, "readwrite"); t.objectStore(store).put(value); t.oncomplete = res; t.onerror = () => rej(t.error); });
  await put("folios", { id: "f-skew", name: "The Salt Roads", type: "draft", createdAt: now, updatedAt: now });
  await put("folio-content", { folioId: "f-skew", html: "<h1>The Salt Roads</h1><p>Salt bought silence in the hill towns.</p>", updatedAt: now });
  await put("meta", { key: "active-folio-id", value: "f-skew", updatedAt: now });
  await put("meta", { key: "signin-toast-dismissed", value: true, updatedAt: now });
  localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
  db.close();
});
await page.goto(`${url}/editor/`, { waitUntil: "load" });
await page.locator("#twyne-editor-mount .ProseMirror").waitFor({ timeout: 60000 });
await page.waitForTimeout(3000);
const loadsBefore = log.loads;
note("ready on build A", { loads: log.loads });
writeFileSync(`${dir}/ready`, "1");
while (!existsSync(`${dir}/go`)) await new Promise((r) => setTimeout(r, 300));
note("server now on build B");

const file = page.getByRole("button", { name: /^File/ });
const menu = page.locator("[data-folio-menu] [role=menu]");
const opened = async () => menu.isVisible().catch(() => false);
await file.click();
const deadline = Date.now() + 12000;
let state = "no menu";
while (Date.now() < deadline) {
  if (await opened()) { state = "menu opened"; break; }
  await page.waitForTimeout(250);
}
note("after first press of File", { state, reloadsSinceDeploy: log.loads - loadsBefore });
if (state !== "menu opened") {
  // After a recovery reload the page is on build B: File should work now.
  await page.locator("#twyne-editor-mount .ProseMirror").waitFor({ timeout: 60000 }).catch(() => {});
  await page.waitForTimeout(1500);
  await file.click().catch(() => {});
  await page.waitForTimeout(1500);
  note("after second press of File", { state: (await opened()) ? "menu opened" : "no menu", reloadsSinceDeploy: log.loads - loadsBefore });
}
await page.waitForTimeout(3000);
note("final", { reloadsSinceDeploy: log.loads - loadsBefore, recoveryFlag: await page.evaluate(() => sessionStorage.getItem("twyne:chunk-recovery:v1")) });
writeFileSync(`${dir}/result.json`, JSON.stringify(log, null, 2));
console.log("chunk errors:", JSON.stringify(log.chunkErrors.slice(0, 4)));
await browser.close();

