// A tab left open across a deploy, instrumented: every request the page makes
// after the swap (with status), every console message of any level, page
// errors, Qwik's qerror events, unhandled rejections, and whether the File
// menu opens. Usage: node skew-diagnose.mjs <url> <dir> [firefox|chromium]
import { existsSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
const [url, dir, engine = "firefox"] = process.argv.slice(2);
const pw = await import(resolve(process.cwd(), "node_modules/playwright/index.mjs"));
const browser = await pw[engine].launch();
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
await context.route(/posthog/, (r) => r.abort());
const page = await context.newPage();
let recording = false;
const events = [];
const t0 = { v: 0 };
const rec = (kind, text) => recording && events.push(`${Date.now() - t0.v}ms ${kind}: ${String(text).slice(0, 220)}`);
page.on("console", (m) => rec(`console.${m.type()}`, m.text()));
page.on("pageerror", (e) => rec("pageerror", e.message));
page.on("requestfinished", async (r) => {
  const res = await r.response().catch(() => null);
  rec("request", `${res?.status() ?? "?"} ${r.url().replace(url, "")}`);
});
page.on("requestfailed", (r) => rec("request FAILED", `${r.failure()?.errorText} ${r.url().replace(url, "")}`));
page.on("framenavigated", (f) => f === page.mainFrame() && rec("navigated", f.url()));
await page.addInitScript(() => {
  document.addEventListener("qerror", (e) => console.warn("[diag] qerror", e.detail?.importError, String(e.detail?.error?.message ?? e.detail?.error).slice(0, 160)));
  addEventListener("unhandledrejection", (e) => console.warn("[diag] unhandledrejection", String(e.reason?.message ?? e.reason).slice(0, 160)));
});

await page.goto(`${url}/editor/`, { waitUntil: "load" });
await page.waitForTimeout(1500);
await page.evaluate(async () => {
  const db = await new Promise((res, rej) => { const r = indexedDB.open("twyne"); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
  const now = Date.now();
  const put = (store, value) => new Promise((res, rej) => { const t = db.transaction(store, "readwrite"); t.objectStore(store).put(value); t.oncomplete = res; t.onerror = () => rej(t.error); });
  await put("folios", { id: "f-skew", name: "The Salt Roads", type: "draft", createdAt: now, updatedAt: now });
  await put("folio-content", { folioId: "f-skew", html: "<h1>The Salt Roads</h1><p>Salt.</p>", updatedAt: now });
  await put("meta", { key: "active-folio-id", value: "f-skew", updatedAt: now });
  await put("meta", { key: "signin-toast-dismissed", value: true, updatedAt: now });
  localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
  db.close();
});
await page.goto(`${url}/editor/`, { waitUntil: "load" });
await page.locator("#twyne-editor-mount .ProseMirror").waitFor({ timeout: 60000 });
await page.waitForTimeout(3000);
console.log("before deploy:", JSON.stringify(await page.evaluate(() => ({
  build: document.documentElement.getAttribute("q:manifest-hash"),
  recoveryScript: !!document.querySelector("script[data-chunk-recovery]"),
}))));
writeFileSync(`${dir}/ready`, "1");
while (!existsSync(`${dir}/go`)) await new Promise((r) => setTimeout(r, 300));

t0.v = Date.now();
recording = true;
await page.getByRole("button", { name: /^File/ }).click({ timeout: 10000 });
await page.waitForTimeout(8000);
recording = false;
const menuOpen = await page.locator("[data-folio-menu] [role=menu]").isVisible().catch(() => false);
console.log("after pressing File:", JSON.stringify(await page.evaluate(() => ({
  build: document.documentElement.getAttribute("q:manifest-hash"),
  flag: sessionStorage.getItem("twyne:chunk-recovery:v1"),
}))), "menu open:", menuOpen);
console.log("events after the deploy:\n  " + events.join("\n  "));
await browser.close();

