/**
 * Paragraph-level three-way merge for a manuscript open in two tabs.
 *
 * `base` is what this tab last loaded or saved, `mine` is this tab's editor
 * now, `theirs` is what the other tab saved. Each is a list of top-level
 * blocks (paragraphs, headings, lists…) serialized the same way, so equal
 * blocks compare equal as strings.
 *
 * Regions changed on only one side merge cleanly. A region both sides
 * changed differently is a conflict, resolved by the writer's choice; the
 * default keeps both, so bringing changes in can never lose words.
 */

export type ConflictChoice = "mine" | "theirs" | "both";

export type MergeRegion =
  | { kind: "same"; blocks: string[] }
  /** Only the other tab changed this stretch: `base` → `theirs`. */
  | { kind: "theirs"; base: string[]; theirs: string[] }
  /** Only this tab changed this stretch: `base` → `mine`. */
  | { kind: "mine"; base: string[]; mine: string[] }
  /** Both tabs made the same change. */
  | { kind: "both-same"; blocks: string[] }
  /** Both tabs changed this stretch, differently. */
  | { kind: "conflict"; id: number; base: string[]; mine: string[]; theirs: string[] };

export interface BlockMerge {
  regions: MergeRegion[];
  /** Blocks the other tab added, changed or removed. */
  theirChanges: number;
  /** Blocks this tab added, changed or removed. */
  myChanges: number;
  conflicts: number;
}

/** Above this many unmatched blocks per side the middle is not aligned. */
const MAX_ALIGN = 1500;

/**
 * Pairs of equal blocks (indices into `a` and `b`) along a longest common
 * subsequence. The common prefix and suffix are matched directly, so the
 * quadratic part only covers the stretch that actually changed.
 */
export function matchBlocks(a: string[], b: string[]): Array<[number, number]> {
  const pairs: Array<[number, number]> = [];
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) {
    pairs.push([start, start]);
    start++;
  }
  let endA = a.length;
  let endB = b.length;
  const tail: Array<[number, number]> = [];
  while (endA > start && endB > start && a[endA - 1] === b[endB - 1]) {
    endA--;
    endB--;
    tail.push([endA, endB]);
  }
  const n = endA - start;
  const m = endB - start;
  if (n > 0 && m > 0 && n <= MAX_ALIGN && m <= MAX_ALIGN) {
    // Classic LCS table over the changed middle.
    const width = m + 1;
    const table = new Uint32Array((n + 1) * width);
    for (let i = n - 1; i >= 0; i--) {
      for (let j = m - 1; j >= 0; j--) {
        table[i * width + j] =
          a[start + i] === b[start + j]
            ? table[(i + 1) * width + j + 1] + 1
            : Math.max(table[(i + 1) * width + j], table[i * width + j + 1]);
      }
    }
    let i = 0;
    let j = 0;
    while (i < n && j < m) {
      if (a[start + i] === b[start + j]) {
        pairs.push([start + i, start + j]);
        i++;
        j++;
      } else if (table[(i + 1) * width + j] >= table[i * width + j + 1]) {
        i++;
      } else {
        j++;
      }
    }
  }
  return pairs.concat(tail.reverse());
}

const sameList = (a: string[], b: string[]) =>
  a.length === b.length && a.every((block, i) => block === b[i]);

export function mergeBlocks(
  base: string[],
  mine: string[],
  theirs: string[],
): BlockMerge {
  const toMine = new Map(matchBlocks(base, mine));
  const toTheirs = new Map(matchBlocks(base, theirs));
  // Base blocks both sides kept, in order: the anchors between regions.
  const anchors: Array<[number, number, number]> = [];
  for (let i = 0; i < base.length; i++) {
    const m = toMine.get(i);
    const t = toTheirs.get(i);
    if (m !== undefined && t !== undefined) anchors.push([i, m, t]);
  }
  anchors.push([base.length, mine.length, theirs.length]);

  const regions: MergeRegion[] = [];
  let theirChanges = 0;
  let myChanges = 0;
  let conflicts = 0;
  let b0 = 0;
  let m0 = 0;
  let t0 = 0;
  for (const [b1, m1, t1] of anchors) {
    const baseRun = base.slice(b0, b1);
    const mineRun = mine.slice(m0, m1);
    const theirsRun = theirs.slice(t0, t1);
    const mineChanged = !sameList(baseRun, mineRun);
    const theirsChanged = !sameList(baseRun, theirsRun);
    if (!mineChanged && theirsChanged) {
      regions.push({ kind: "theirs", base: baseRun, theirs: theirsRun });
      theirChanges += Math.max(baseRun.length, theirsRun.length);
    } else if (mineChanged && !theirsChanged) {
      regions.push({ kind: "mine", base: baseRun, mine: mineRun });
      myChanges += Math.max(baseRun.length, mineRun.length);
    } else if (mineChanged && theirsChanged) {
      if (sameList(mineRun, theirsRun)) {
        regions.push({ kind: "both-same", blocks: mineRun });
      } else {
        regions.push({
          kind: "conflict",
          id: conflicts++,
          base: baseRun,
          mine: mineRun,
          theirs: theirsRun,
        });
        theirChanges += Math.max(baseRun.length, theirsRun.length);
        myChanges += Math.max(baseRun.length, mineRun.length);
      }
    }
    if (b1 < base.length) {
      const last = regions[regions.length - 1];
      if (last?.kind === "same") last.blocks.push(base[b1]);
      else regions.push({ kind: "same", blocks: [base[b1]] });
    }
    b0 = b1 + 1;
    m0 = m1 + 1;
    t0 = t1 + 1;
  }
  return { regions, theirChanges, myChanges, conflicts };
}

/** The merged manuscript, with each conflict resolved as chosen. */
export function resolveMerge(
  merge: BlockMerge,
  choices: Record<number, ConflictChoice> = {},
): string[] {
  const out: string[] = [];
  for (const region of merge.regions) {
    switch (region.kind) {
      case "same":
      case "both-same":
        out.push(...region.blocks);
        break;
      case "theirs":
        out.push(...region.theirs);
        break;
      case "mine":
        out.push(...region.mine);
        break;
      case "conflict": {
        const choice = choices[region.id] ?? "both";
        if (choice === "mine") out.push(...region.mine);
        else if (choice === "theirs") out.push(...region.theirs);
        else out.push(...region.mine, ...region.theirs);
        break;
      }
    }
  }
  return out;
}

export type WordPart = { kind: "same" | "added" | "removed"; text: string };

/** Word-level difference between two passages, for showing a change. */
export function diffWords(before: string, after: string): WordPart[] {
  const a = before.split(/(\s+)/).filter(Boolean);
  const b = after.split(/(\s+)/).filter(Boolean);
  const pairs = matchBlocks(a, b);
  const parts: WordPart[] = [];
  const push = (kind: WordPart["kind"], text: string) => {
    const last = parts[parts.length - 1];
    if (last?.kind === kind) last.text += text;
    else parts.push({ kind, text });
  };
  let i = 0;
  let j = 0;
  for (const [pi, pj] of [...pairs, [a.length, b.length] as [number, number]]) {
    while (i < pi) push("removed", a[i++]);
    while (j < pj) push("added", b[j++]);
    if (pi < a.length) push("same", a[pi]);
    i = pi + 1;
    j = pj + 1;
  }
  return parts;
}

import { describe, expect, test } from "bun:test";
import {
  diffWords,
  matchBlocks,
  mergeBlocks,
  resolveMerge,
} from "./block-merge";

const base = ["<h1>T</h1>", "<p>One.</p>", "<p>Two.</p>", "<p>Three.</p>"];

describe("mergeBlocks", () => {
  test("edits to different paragraphs both survive", () => {
    const mine = ["<h1>T</h1>", "<p>One, mine.</p>", "<p>Two.</p>", "<p>Three.</p>"];
    const theirs = ["<h1>T</h1>", "<p>One.</p>", "<p>Two.</p>", "<p>Three, theirs.</p>"];
    const merge = mergeBlocks(base, mine, theirs);
    expect(merge.conflicts).toBe(0);
    expect(merge.myChanges).toBe(1);
    expect(merge.theirChanges).toBe(1);
    expect(resolveMerge(merge)).toEqual([
      "<h1>T</h1>",
      "<p>One, mine.</p>",
      "<p>Two.</p>",
      "<p>Three, theirs.</p>",
    ]);
  });

  test("paragraphs added and removed on each side merge cleanly", () => {
    const mine = [...base, "<p>Four, mine.</p>"];
    const theirs = ["<h1>T</h1>", "<p>Two.</p>", "<p>Three.</p>"];
    expect(resolveMerge(mergeBlocks(base, mine, theirs))).toEqual([
      "<h1>T</h1>",
      "<p>Two.</p>",
      "<p>Three.</p>",
      "<p>Four, mine.</p>",
    ]);
  });

  test("the same paragraph changed differently is a conflict that keeps both by default", () => {
    const mine = ["<h1>T</h1>", "<p>One, mine.</p>", "<p>Two.</p>", "<p>Three.</p>"];
    const theirs = ["<h1>T</h1>", "<p>One, theirs.</p>", "<p>Two.</p>", "<p>Three.</p>"];
    const merge = mergeBlocks(base, mine, theirs);
    expect(merge.conflicts).toBe(1);
    expect(resolveMerge(merge)).toEqual([
      "<h1>T</h1>",
      "<p>One, mine.</p>",
      "<p>One, theirs.</p>",
      "<p>Two.</p>",
      "<p>Three.</p>",
    ]);
    expect(resolveMerge(merge, { 0: "theirs" })[1]).toBe("<p>One, theirs.</p>");
    expect(resolveMerge(merge, { 0: "mine" })).toHaveLength(4);
  });

  test("the same change on both sides is not a conflict", () => {
    const both = ["<h1>T</h1>", "<p>One, again.</p>", "<p>Two.</p>", "<p>Three.</p>"];
    const merge = mergeBlocks(base, both, both);
    expect(merge.conflicts).toBe(0);
    expect(resolveMerge(merge)).toEqual(both);
  });

  test("with no edits here, the result is exactly the other tab's", () => {
    const theirs = ["<h1>T</h1>", "<p>New.</p>", "<p>Three.</p>"];
    const merge = mergeBlocks(base, base, theirs);
    expect(merge.myChanges).toBe(0);
    expect(resolveMerge(merge)).toEqual(theirs);
  });

  test("a long manuscript with a change in the middle aligns quickly", () => {
    const long = Array.from({ length: 3000 }, (_, i) => `<p>Paragraph ${i}.</p>`);
    const mine = [...long];
    mine[10] = "<p>Mine.</p>";
    const theirs = [...long];
    theirs[2900] = "<p>Theirs.</p>";
    const started = performance.now();
    const merged = resolveMerge(mergeBlocks(long, mine, theirs));
    expect(performance.now() - started).toBeLessThan(500);
    expect(merged[10]).toBe("<p>Mine.</p>");
    expect(merged[2900]).toBe("<p>Theirs.</p>");
    expect(merged).toHaveLength(3000);
  });
});

describe("matchBlocks", () => {
  test("pairs are a common subsequence in order", () => {
    const pairs = matchBlocks(["a", "b", "c", "d"], ["a", "x", "c", "d", "e"]);
    expect(pairs).toEqual([
      [0, 0],
      [2, 2],
      [3, 3],
    ]);
  });
});

describe("diffWords", () => {
  test("marks added and removed words", () => {
    const parts = diffWords("The road forgot the sea.", "The road forgot the coast entirely.");
    expect(parts.filter((p) => p.kind === "removed").map((p) => p.text.trim())).toEqual(["sea."]);
    expect(parts.filter((p) => p.kind === "added").map((p) => p.text).join("")).toContain("coast");
    expect(parts.map((p) => (p.kind === "removed" ? "" : p.text)).join("")).toBe(
      "The road forgot the coast entirely.",
    );
  });
});

