export async function saveFolioContentToIdb(
  folioId: string,
  html: string,
  options: {
    /**
     * The manuscript the caller believes is stored. When something else is
     * there (another tab saved in between), the save still lands and the
     * version it replaced comes back as `displaced`, so it can be kept.
     */
    expectHtml?: string;
  } = {},
): Promise<{ displaced?: string }> {
  // Stamp when the snapshot is queued, not when an asynchronous read finishes.
  // An older in-flight save must not look newer than a departure mirror.
  const updatedAt = Date.now();
  let displaced: string | undefined;
  await updateFolioContent(folioId, (previous) => {
    if (
      options.expectHtml !== undefined &&
      previous?.html &&
      previous.html !== options.expectHtml &&
      previous.html !== html
    ) {
      displaced = previous.html;
    }
    return {
      folioId,
      html,
      format: "typst",
      ...(previous?.kit ? { kit: previous.kit } : {}),
      typstSource:
        previous?.typstSource !== undefined
          ? previous.html === html
            ? previous.typstSource
            : reconcileTypstSource(previous.typstSource, html)
          : htmlToTypst(html),
      updatedAt: previous?.html === html ? previous.updatedAt : updatedAt,
    };
  });
  return displaced === undefined ? {} : { displaced };
}

