const CHANNEL = "twyne:folio-tabs";
/** Coalesce a burst of saves from a tab being typed in. */
const SETTLE_MS = 300;
const VERSION_LIMIT = 12;
/** A save racing an older build's tab is kept at most this often. */
const DISPLACED_KEEP_MS = 60_000;
const KEPT_LABEL = "Kept from another tab";

/** Saves seen per tab. One vector covers another when it has seen them all. */
type Clock = Record<string, number>;

type Message =
  | { t: "hello"; tab: string; folioId: string | null }
  | { t: "showing"; tab: string; folioId: string | null }
  | { t: "bye"; tab: string }
  | {
      t: "saved";
      tab: string;
      folioId: string;
      html: string;
      clock: Clock;
      /** The version this one was written over. */
      from: string;
    }
  | {
      t: "here";
      tab: string;
      to: string;
      folioId: string | null;
      state?: { html: string; clock: Clock; from: string };
    };

interface Version {
  html: string;
  clock: Clock;
  from: string;
}

interface Shown {
  folioId: string;
  generation: string;
  /** The stored manuscript this tab's editor last matched. */
  html: string;
  id: string;
  clock: Clock;
  /** The editor's own serialization of `html`, once known. */
  as: string | null;
  edited: boolean;
  versions: Map<string, { html: string; clock: Clock }>;
  /** A version from another tab this tab has not brought in yet. */
  incoming: (Version & { id: string; at: number; summary: Summary | null }) | null;
  /** Arrived while hidden; considered on return. */
  waiting: Version | null;
  /** What the last automatic bring-in changed, for "See what changed". */
  applied: { before: string; after: string; at: number; paragraphs: number } | null;
  /** The editor's echo of an applied version, which is already stored. */
  echo: string | null;
  /** Clocks of versions brought in, folded into the next save. */
  integrated: Clock | null;
}

interface Summary {
  theirs: number;
  mine: number;
  conflicts: number;
}

export interface FolioTabsView {
  /** Other tabs showing this piece. */
  elsewhere: number;
  presenceDismissed: boolean;
  incoming: ({ at: number } & Partial<Summary>) | null;
  applied: { at: number; paragraphs: number } | null;
}

export interface FolioTabsChange {
  kind: "theirs" | "conflict";
  id: number;
  /** The end of the unchanged paragraph before this change. */
  after?: string;
  parts: WordPart[];
  mine?: string;
  theirs?: string;
}

export interface FolioTabsPreview {
  mode: "incoming" | "applied";
  changes: FolioTabsChange[];
  /** Paragraphs changed only in this tab, which stay as they are. */
  mine: number;
}

let tabId = "";
let channel: BroadcastChannel | null = null;
let editor: Editor | null = null;
let shown: Shown | null = null;
let saver: ((folioId: string, html: string) => void) | null = null;
let presenceDismissed = false;
let settleTimer: number | null = null;
let settling: Version & { folioId: string } = null as never;
const others = new Map<string, { folioId: string | null; seen: number }>();
/** The stored manuscript per piece, as far as this tab knows. */
const known = new Map<string, string>();
/** This tab's recent saves per piece, including ones still in flight. */
const ownRecent = new Map<string, string[]>();
const kept = new Set<string>();
const displacedKeptAt = new Map<string, number>();

/** A short fingerprint of a manuscript. */
export function versionOf(html: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < html.length; i++) {
    hash ^= html.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return `${html.length.toString(36)}.${(hash >>> 0).toString(36)}`;
}

/** Whether `a` has seen every save `b` has. */
export function covers(a: Clock, b: Clock): boolean {
  return Object.entries(b).every(([tab, n]) => (a[tab] ?? 0) >= n);
}

export function joinClocks(a: Clock, b: Clock): Clock {
  const out = { ...a };
  for (const [tab, n] of Object.entries(b)) out[tab] = Math.max(out[tab] ?? 0, n);
  return out;
}

const lockName = (tab: string) => `twyne:tab:${tab}`;
const post = (message: Message) => channel?.postMessage(message);
const hidden = () => document.visibilityState === "hidden";

function liveEditor(): Editor | null {
  return editor && !editor.isDestroyed ? editor : null;
}

function remember(s: Shown, html: string, clock: Clock) {
  const id = versionOf(html);
  s.versions.delete(id);
  s.versions.set(id, { html, clock });
  while (s.versions.size > VERSION_LIMIT) {
    s.versions.delete(s.versions.keys().next().value!);
  }
}

function view(): FolioTabsView {
  const s = shown;
  let elsewhere = 0;
  if (s) for (const other of others.values()) if (other.folioId === s.folioId) elsewhere++;
  return {
    elsewhere,
    presenceDismissed,
    incoming: s?.incoming ? { at: s.incoming.at, ...(s.incoming.summary ?? {}) } : null,
    applied: s?.applied ? { at: s.applied.at, paragraphs: s.applied.paragraphs } : null,
  };
}

export function folioTabsView(): FolioTabsView {
  return view();
}

function emit() {
  window.dispatchEvent(new CustomEvent<FolioTabsView>(FOLIO_TABS_EVENT, { detail: view() }));
}

function stateFor(folioId: string) {
  const s = shown;
  return s && s.folioId === folioId && s.as !== null && !s.edited
    ? { html: s.html, clock: s.clock, from: s.id }
    : s && s.folioId === folioId
      ? { html: s.html, clock: s.clock, from: s.id }
      : undefined;
}

function receive(message: Message) {
  if (!message || message.tab === tabId) return;
  const now = Date.now();
  switch (message.t) {
    case "hello":
    case "showing": {
      others.set(message.tab, { folioId: message.folioId, seen: now });
      post({
        t: "here",
        tab: tabId,
        to: message.tab,
        folioId: shown?.folioId ?? null,
        state:
          message.folioId && message.folioId === shown?.folioId
            ? stateFor(message.folioId)
            : undefined,
      });
      if (message.folioId === shown?.folioId && message.t === "hello") presenceDismissed = false;
      emit();
      return;
    }
    case "here":
      if (message.to !== tabId) return;
      others.set(message.tab, { folioId: message.folioId, seen: now });
      if (message.state && message.folioId) {
        arrive({ folioId: message.folioId, ...message.state });
      }
      emit();
      return;
    case "bye":
      others.delete(message.tab);
      emit();
      return;
    case "saved":
      others.set(message.tab, {
        folioId: others.get(message.tab)?.folioId ?? message.folioId,
        seen: now,
      });
      known.set(message.folioId, message.html);
      arrive(message);
      return;
  }
}

/** A version of some piece exists in another tab. */
function arrive(version: Version & { folioId: string }) {
  const s = shown;
  if (!s || version.folioId !== s.folioId) return;
  const id = versionOf(version.html);
  if (id === s.id) {
    s.clock = joinClocks(s.clock, version.clock);
    return;
  }
  // Already part of what this tab shows.
  if (covers(s.clock, version.clock) && Object.keys(version.clock).length > 0) return;
  if (s.incoming?.id === id) {
    s.incoming.clock = joinClocks(s.incoming.clock, version.clock);
    if (!s.incoming.from) s.incoming.from = version.from;
    return;
  }
  if (hidden()) {
    s.waiting = version;
    return;
  }
  settling = version;
  if (settleTimer !== null) return;
  settleTimer = window.setTimeout(() => {
    settleTimer = null;
    void consider(settling);
  }, SETTLE_MS);
}

async function consider(version: Version & { folioId: string }) {
  const s = shown;
  if (!s || version.folioId !== s.folioId) return;
  s.waiting = null;
  const ed = liveEditor();
  if (!ed || hidden()) {
    s.waiting = version;
    return;
  }
  const id = versionOf(version.html);
  const current = ed.getHTML();
  if (s.as === null && !s.edited) s.as = current;
  if (current === version.html) {
    s.html = version.html;
    s.id = id;
    s.as = current;
    s.edited = false;
    s.clock = joinClocks(s.clock, version.clock);
    remember(s, version.html, s.clock);
    settleIncoming(s);
    emit();
    return;
  }
  const clean = s.as !== null && current === s.as;
  const descends = version.from === s.id || covers(version.clock, s.clock);
  if (clean && descends) {
    const done = await replaceDocument(ed, version.html, current);
    if (shown !== s) return;
    if (!done) {
      // The writer started typing here meanwhile; look again.
      return void consider(version);
    }
    s.html = version.html;
    s.id = id;
    s.as = ed.getHTML();
    s.echo = s.as;
    s.edited = false;
    s.clock = joinClocks(s.clock, version.clock);
    remember(s, version.html, s.clock);
    settleIncoming(s);
    const before = s.applied?.before ?? current;
    s.applied = {
      before,
      after: version.html,
      at: Date.now(),
      paragraphs: (await mergeOf(ed, before, before, version.html)).merge.theirChanges,
    };
    emit();
    return;
  }
  const incoming = { ...version, id, at: Date.now(), summary: null };
  s.incoming = incoming;
  emit();
  const { merge } = await mergeFor(s, ed, incoming, current);
  if (s.incoming !== incoming) return;
  incoming.summary = {
    theirs: merge.theirChanges,
    mine: merge.myChanges,
    conflicts: merge.conflicts,
  };
  emit();
}

function settleIncoming(s: Shown) {
  if (s.incoming && covers(s.clock, s.incoming.clock) && Object.keys(s.incoming.clock).length) {
    s.incoming = null;
  }
  if (s.incoming && versionOf(s.html) === s.incoming.id) s.incoming = null;
}

/* ── Editor ─────────────────────────────────────────────────────────── */

let tiptapModules: Promise<{
  createDocument: typeof import("@tiptap/core").createDocument;
  DOMSerializer: typeof import("@tiptap/pm/model").DOMSerializer;
}> | null = null;

function tiptap() {
  tiptapModules ??= Promise.all([import("@tiptap/core"), import("@tiptap/pm/model")]).then(
    ([core, model]) => ({ createDocument: core.createDocument, DOMSerializer: model.DOMSerializer }),
  );
  return tiptapModules;
}

/**
 * Change the editor to `html` with one undoable step covering only the
 * stretch that differs, so the caret and scroll stay where they were.
 * Returns false when the editor no longer shows `expect`.
 */
async function replaceDocument(ed: Editor, html: string, expect: string): Promise<boolean> {
  const { createDocument } = await tiptap();
  if (ed.isDestroyed || ed.getHTML() !== expect) return false;
  const next = createDocument(html, ed.schema, ed.options.parseOptions);
  const { doc } = ed.state;
  const start = doc.content.findDiffStart(next.content);
  if (start === null) return true;
  const end = doc.content.findDiffEnd(next.content);
  let endA = end?.a ?? doc.content.size;
  let endB = end?.b ?? next.content.size;
  const overlap = start - Math.min(endA, endB);
  if (overlap > 0) {
    endA += overlap;
    endB += overlap;
  }
  ed.view.dispatch(
    ed.state.tr.replace(start, endA, next.slice(start, endB)).setMeta("twyne:other-tab", true),
  );
  return true;
}

interface Blocks {
  html: string[];
  text: Map<string, string>;
}

async function blocksOf(ed: Editor, html: string, text: Map<string, string>): Promise<string[]> {
  const { createDocument, DOMSerializer } = await tiptap();
  const doc = createDocument(html, ed.schema, ed.options.parseOptions);
  const serializer = DOMSerializer.fromSchema(ed.schema);
  const holder = document.createElement("div");
  const out: string[] = [];
  doc.forEach((node) => {
    holder.replaceChildren(serializer.serializeNode(node));
    const block = holder.innerHTML;
    out.push(block);
    text.set(block, node.textContent || `[${node.type.name.replace(/([A-Z])/g, " $1").toLowerCase()}]`);
  });
  return out;
}

async function mergeOf(
  ed: Editor,
  base: string | null,
  mine: string,
  theirs: string,
): Promise<{ merge: BlockMerge } & Pick<Blocks, "text">> {
  const text = new Map<string, string>();
  const [mineBlocks, theirBlocks] = await Promise.all([
    blocksOf(ed, mine, text),
    blocksOf(ed, theirs, text),
  ]);
  // Without a version both came from, treat what they share as the original:
  // nothing either side wrote can be lost, at the cost of more "both" choices.
  const baseBlocks =
    base === null
      ? matchBlocks(mineBlocks, theirBlocks).map(([i]) => mineBlocks[i])
      : await blocksOf(ed, base, text);
  return { merge: mergeBlocks(baseBlocks, mineBlocks, theirBlocks), text };
}

/** The newest version this tab passed through that `version` also contains. */
function ancestorOf(s: Shown, version: Version): string | null {
  const versions = [...s.versions.entries()].reverse();
  for (const [id, v] of versions) {
    if (id === version.from) return v.html;
    if (Object.keys(v.clock).length > 0 && covers(version.clock, v.clock)) return v.html;
  }
  return null;
}

function mergeFor(s: Shown, ed: Editor, version: Version, mine: string) {
  return mergeOf(ed, ancestorOf(s, version), mine, version.html);
}

/* ── Versions ───────────────────────────────────────────────────────── */

function keep(folioId: string, html: string) {
  const id = `${folioId}:${versionOf(html)}`;
  if (kept.has(id) || !html) return;
  kept.add(id);
  void createRevisionSnapshot({
    folioId,
    html,
    label: KEPT_LABEL,
    source: "automatic",
    force: true,
  }).catch(() => kept.delete(id));
}

/* ── The route's save path ──────────────────────────────────────────── */

/**
 * Before this tab stores `html`: returns a test for whether a stored version
 * is one this tab knows about. Keeps an unanswered version from another tab,
 * which this save is about to replace.
 */
export function beforeSave(folioId: string, html: string): (stored: string) => boolean {
  const recent = [...(ownRecent.get(folioId) ?? []), html].slice(-4);
  ownRecent.set(folioId, recent);
  const s = shown;
  if (s?.folioId === folioId && s.incoming) keep(folioId, s.incoming.html);
  const knownHtml = known.get(folioId);
  return (stored) =>
    stored === knownHtml || recent.includes(stored) || stored === known.get(folioId);
}

/** After this tab stored `html`; `displaced` is a version it replaced unseen. */
export function afterSave(folioId: string, html: string, displaced?: string) {
  known.set(folioId, html);
  const s = shown;
  if (!s || s.folioId !== folioId) {
    post({ t: "saved", tab: tabId, folioId, html, clock: {}, from: "" });
    return;
  }
  const from = s.id;
  if (versionOf(html) !== s.id || s.integrated) {
    const clock = joinClocks(s.clock, s.integrated ?? {});
    s.clock = { ...clock, [tabId]: (clock[tabId] ?? 0) + 1 };
    s.integrated = null;
  }
  s.html = html;
  s.id = versionOf(html);
  s.as = html;
  s.edited = false;
  remember(s, html, s.clock);
  settleIncoming(s);
  post({ t: "saved", tab: tabId, folioId, html, clock: s.clock, from });
  if (displaced !== undefined) {
    const last = displacedKeptAt.get(folioId) ?? 0;
    if (Date.now() - last > DISPLACED_KEEP_MS) {
      displacedKeptAt.set(folioId, Date.now());
      keep(folioId, displaced);
    }
    const id = versionOf(displaced);
    if (!s.incoming && !s.versions.has(id)) {
      s.incoming = { html: displaced, clock: {}, from: "", id, at: Date.now(), summary: null };
      emit();
      const ed = liveEditor();
      const incoming = s.incoming;
      if (ed) {
        void mergeFor(s, ed, incoming, ed.getHTML()).then(({ merge }) => {
          if (s.incoming !== incoming) return;
          incoming.summary = {
            theirs: merge.theirChanges,
            mine: merge.myChanges,
            conflicts: merge.conflicts,
          };
          emit();
        });
      }
    }
  }
}

/** True for the editor's echo of a version brought in, which is already stored. */
export function consumeEcho(folioId: string, html: string): boolean {
  const s = shown;
  if (!s || s.folioId !== folioId || s.echo !== html) return false;
  s.echo = null;
  return true;
}

/** How this tab can save on demand, so other tabs learn its choice. */
export function setSaver(save: ((folioId: string, html: string) => void) | null) {
  saver = save;
}

/** Another writer in this tab (a restore, an import, sync) stored a version. */
function localWrite(detail: FolioContentSavedDetail) {
  const { folioId, html } = detail;
  if (ownRecent.get(folioId)?.includes(html)) return;
  known.set(folioId, html);
  const s = shown;
  if (!s || s.folioId !== folioId) {
    post({ t: "saved", tab: tabId, folioId, html, clock: {}, from: "" });
    return;
  }
  if (versionOf(html) === s.id) return;
  const from = s.id;
  s.clock = { ...s.clock, [tabId]: (s.clock[tabId] ?? 0) + 1 };
  s.html = html;
  s.id = versionOf(html);
  s.as = null;
  s.edited = false;
  remember(s, html, s.clock);
  post({ t: "saved", tab: tabId, folioId, html, clock: s.clock, from });
}

/* ── What the tab shows ─────────────────────────────────────────────── */

/**
 * The editor now shows `folioId`, seeded with `html`. `generation` changes
 * whenever the editor is re-seeded; repeated calls for one are ignored.
 */
export function showingFolio(folioId: string | null, html: string, generation: string) {
  if (shown?.generation === generation || (!shown && !folioId && !generation)) return;
  if (folioId && shown?.folioId === folioId) {
    shown.generation = generation;
    loadedHere(folioId, html);
    return;
  }
  shown = folioId
    ? {
        folioId,
        generation,
        html,
        id: versionOf(html),
        clock: {},
        as: null,
        edited: false,
        versions: new Map([[versionOf(html), { html, clock: {} }]]),
        incoming: null,
        waiting: null,
        applied: null,
        echo: null,
        integrated: null,
      }
    : null;
  if (folioId && !known.has(folioId)) known.set(folioId, html);
  if (settleTimer !== null) window.clearTimeout(settleTimer);
  settleTimer = null;
  post({ t: "showing", tab: tabId, folioId });
  emit();
}

/** The editor was re-seeded with `html` for the piece it already shows. */
export function loadedHere(folioId: string, html: string) {
  const s = shown;
  if (!s || s.folioId !== folioId || versionOf(html) === s.id) return;
  s.html = html;
  s.id = versionOf(html);
  s.as = null;
  s.edited = false;
  s.echo = null;
  remember(s, html, s.clock);
  settleIncoming(s);
  emit();
}

export function attachEditor(next: Editor | null) {
  if (editor === next) return;
  editor = next;
  const s = shown;
  const ed = liveEditor();
  if (s && ed && s.as === null && !s.edited) s.as = ed.getHTML();
  if (s?.waiting && ed && !hidden()) void consider({ folioId: s.folioId, ...s.waiting });
}

function onContent(html: string) {
  const s = shown;
  if (!s) return;
  if (html === (s.as ?? s.html)) {
    s.edited = false;
    return;
  }
  if (html === s.echo) return;
  s.edited = true;
  if (s.applied) {
    s.applied = null;
    emit();
  }
}

/* ── Writer's choices ───────────────────────────────────────────────── */

export async function previewOtherTab(): Promise<FolioTabsPreview | null> {
  const s = shown;
  const ed = liveEditor();
  if (!s || !ed) return null;
  if (s.incoming) {
    const { merge, text } = await mergeFor(s, ed, s.incoming, ed.getHTML());
    return { mode: "incoming", changes: changesOf(merge, text), mine: merge.myChanges };
  }
  if (s.applied) {
    const { before, after } = s.applied;
    const { merge, text } = await mergeOf(ed, before, before, after);
    return { mode: "applied", changes: changesOf(merge, text), mine: 0 };
  }
  return null;
}

function changesOf(merge: BlockMerge, text: Map<string, string>): FolioTabsChange[] {
  const read = (blocks: string[]) => blocks.map((block) => text.get(block) ?? "").join("\n\n");
  const tail = (block: string | undefined) => {
    const words = block === undefined ? "" : (text.get(block) ?? "").trim();
    return words.length > 90 ? `…${words.slice(-88).trimStart()}` : words || undefined;
  };
  const changes: FolioTabsChange[] = [];
  let previous: string | undefined;
  merge.regions.forEach((region, index) => {
    switch (region.kind) {
      case "same":
      case "both-same":
        previous = region.blocks.at(-1) ?? previous;
        return;
      case "mine":
        previous = region.mine.at(-1) ?? previous;
        return;
      case "theirs":
        changes.push({
          kind: "theirs",
          id: index,
          after: tail(previous),
          parts: diffWords(read(region.base), read(region.theirs)),
        });
        previous = region.theirs.at(-1) ?? previous;
        return;
      case "conflict":
        changes.push({
          kind: "conflict",
          id: region.id,
          after: tail(previous),
          parts: diffWords(read(region.mine), read(region.theirs)),
          mine: read(region.mine),
          theirs: read(region.theirs),
        });
        previous = region.theirs.at(-1) ?? previous;
        return;
    }
  });
  return changes;
}

/**
 * Bring the other tab's changes into this one. Paragraphs only one tab
 * changed take that tab's wording; for ones both changed, `choices` picks,
 * and both are kept by default. One undoable step.
 */
export async function bringInOtherTab(
  choices: Record<number, ConflictChoice> = {},
): Promise<boolean> {
  const s = shown;
  const ed = liveEditor();
  const incoming = s?.incoming;
  if (!s || !ed || !incoming) return false;
  keep(s.folioId, incoming.html);
  for (let attempt = 0; attempt < 3; attempt++) {
    const current = ed.getHTML();
    const { merge } = await mergeFor(s, ed, incoming, current);
    const html = resolveMerge(merge, choices).join("");
    if (!(await replaceDocument(ed, html, current))) continue;
    if (shown !== s) return false;
    s.integrated = joinClocks(s.integrated ?? {}, incoming.clock);
    remember(s, incoming.html, incoming.clock);
    s.incoming = null;
    // Nothing changed here: save anyway so the other tab learns this one
    // already has its changes.
    if (ed.getHTML() === current) saver?.(s.folioId, current);
    emit();
    return true;
  }
  return false;
}

/** Keep this tab's version; the other tab's is kept in Versions. */
export function keepThisTab() {
  const s = shown;
  const ed = liveEditor();
  if (!s?.incoming || !ed) return;
  keep(s.folioId, s.incoming.html);
  s.integrated = joinClocks(s.integrated ?? {}, s.incoming.clock);
  s.incoming = null;
  saver?.(s.folioId, ed.getHTML());
  emit();
}

export function dismissOtherTab(what: "presence" | "applied") {
  if (what === "presence") presenceDismissed = true;
  else if (shown) shown.applied = null;
  emit();
}

/* ── Lifetime ───────────────────────────────────────────────────────── */

async function prune() {
  if (!navigator.locks?.query) return;
  const { held = [] } = await navigator.locks.query();
  const alive = new Set(held.map((lock) => lock.name));
  const now = Date.now();
  let changed = false;
  for (const [tab, other] of others) {
    // A tab that has just arrived may not hold its lock yet.
    if (now - other.seen > 5_000 && !alive.has(lockName(tab))) {
      others.delete(tab);
      changed = true;
    }
  }
  if (changed) emit();
}

export function startFolioTabs(): () => void {
  if (channel || typeof BroadcastChannel === "undefined") return () => undefined;
  tabId = crypto.randomUUID();
  channel = new BroadcastChannel(CHANNEL);
  channel.onmessage = (event: MessageEvent<Message>) => receive(event.data);
  let release = () => undefined as void;
  void navigator.locks
    ?.request(lockName(tabId), () => new Promise<void>((resolve) => (release = resolve)))
    .catch(() => undefined);
  const onSaved = (event: Event) =>
    localWrite((event as CustomEvent<FolioContentSavedDetail>).detail);
  const onDraft = (event: Event) =>
    onContent((event as CustomEvent<{ html: string }>).detail.html);
  const onReturn = () => {
    if (hidden()) return;
    void prune();
    const s = shown;
    if (s?.waiting) void consider({ folioId: s.folioId, ...s.waiting });
  };
  const onLeave = () => post({ t: "bye", tab: tabId });
  const onBack = (event: PageTransitionEvent) => {
    if (!event.persisted) return;
    others.clear();
    post({ t: "hello", tab: tabId, folioId: shown?.folioId ?? null });
  };
  window.addEventListener(FOLIO_CONTENT_SAVED, onSaved);
  window.addEventListener("twyne:content", onDraft);
  window.addEventListener("focus", onReturn);
  window.addEventListener("pagehide", onLeave);
  window.addEventListener("pageshow", onBack);
  document.addEventListener("visibilitychange", onReturn);
  post({ t: "hello", tab: tabId, folioId: shown?.folioId ?? null });
  return () => {
    window.removeEventListener(FOLIO_CONTENT_SAVED, onSaved);
    window.removeEventListener("twyne:content", onDraft);
    window.removeEventListener("focus", onReturn);
    window.removeEventListener("pagehide", onLeave);
    window.removeEventListener("pageshow", onBack);
    document.removeEventListener("visibilitychange", onReturn);
    if (settleTimer !== null) window.clearTimeout(settleTimer);
    settleTimer = null;
    post({ t: "bye", tab: tabId });
    channel?.close();
    channel = null;
    release();
    others.clear();
    shown = null;
    editor = null;
  };
}

