/**
 * The same piece open in more than one tab.
 *
 * Every editor tab joins one BroadcastChannel. A tab that saves a manuscript
 * announces the new version and the versions it was made from. A tab showing
 * that piece then
 *
 * - brings the change in by itself when it has no edits of its own and the
 *   new version grew out of what it shows (the usual case: writing in one
 *   tab, coming back to the other), or
 * - says so when both tabs changed the piece: the writer can see what
 *   changed, bring it in paragraph by paragraph, or keep this tab's version.
 *
 * Nothing is replaced silently. A version from another tab that this tab is
 * about to save over is kept in Versions first, and so is any stored version
 * a save finds in its way that this tab never saw (a tab from an older
 * build, or an announcement still in flight).
 *
 * Messages carry version ids, not manuscripts: IndexedDB stays the one copy
 * of record, and a tab in the background does no work until it is looked at.
 */
import type { Editor } from "@tiptap/core";
import {
  diffWords,
  matchBlocks,
  mergeBlocks,
  resolveMerge,
  type BlockMerge,
  type ConflictChoice,
  type WordPart,
} from "./block-merge";
import {
  FOLIO_CONTENT_SAVED,
  loadFolioContentFromIdb,
  type FolioContentSavedDetail,
} from "./idb";
import { createRevisionSnapshot } from "./revision-history";

export const FOLIO_TABS_EVENT = "twyne:folio-tabs";
const CHANNEL = "twyne:folio-tabs";
/** Follow a tab being typed in at most this often. */
const FOLLOW_MS = 800;
/** How long "Brought in changes" stays up once the tab is in view. */
const APPLIED_NOTE_MS = 20_000;
/** Versions kept automatically are kept at most this often per piece. */
const KEEP_EVERY_MS = 60_000;
const KEPT_LABEL = "Kept from another tab";
const LINEAGE_LIMIT = 256;
const HTML_LIMIT = 8;

type Message =
  | { t: "hello"; tab: string; folioId: string | null }
  | { t: "showing"; tab: string; folioId: string | null }
  | { t: "here"; tab: string; to: string; folioId: string | null }
  | { t: "bye"; tab: string }
  /** `id` was stored for `folioId`, made from the versions in `from`. */
  | { t: "saved"; tab: string; folioId: string; id: string; from: string[] };

interface Incoming {
  html: string;
  id: string;
  at: number;
  summary: Summary | null;
}

interface Shown {
  folioId: string;
  /** The stored version this tab's editor is in step with. */
  baseId: string;
  /** The editor's serialization of that version; null until known. */
  as: string | null;
  /** Versions also folded into the next save (a merge has two parents). */
  alsoFrom: string[];
  /** A version from another tab that this tab has not brought in. */
  incoming: Incoming | null;
  /** What automatic bring-ins changed since the writer last looked. */
  applied: { before: string; after: string; at: number } | null;
  /** The editor's echo of a version brought in automatically (already stored). */
  echo: string | null;
  /** Something arrived while the tab was out of view. */
  stale: boolean;
}

interface Summary {
  theirs: number;
  mine: number;
  conflicts: number;
}

export interface FolioTabsView {
  /** Other tabs showing this piece. */
  elsewhere: number;
  presenceDismissed: boolean;
  incoming: ({ at: number } & Partial<Summary>) | null;
  applied: { at: number } | null;
}

export interface FolioTabsChange {
  kind: "theirs" | "conflict";
  id: number;
  /** The close of the unchanged paragraph just before this change. */
  after?: string;
  parts: WordPart[];
  mine?: string;
  theirs?: string;
}

export interface FolioTabsPreview {
  mode: "incoming" | "applied";
  changes: FolioTabsChange[];
  /** Paragraphs changed only in this tab; they stay as they are. */
  mine: number;
}

let tabId = "";
let channel: BroadcastChannel | null = null;
let editor: Editor | null = null;
let shown: Shown | null = null;
let saver: ((folioId: string, html: string) => void) | null = null;
let presenceDismissed = false;
let followTimer: number | null = null;
let appliedTimer: number | null = null;
let reconciling: Promise<void> | null = null;
let again = false;
const others = new Map<string, { folioId: string | null; seen: number }>();
/** Version → the versions it was made from, as announced. */
const parents = new Map<string, string[]>();
/** Recent manuscripts by version, for finding what two tabs started from. */
const htmlOf = new Map<string, string>();
/** Versions this tab stored itself, per piece. */
const ownIds = new Map<string, string[]>();
const keptAt = new Map<string, number>();
const kept = new Set<string>();

let lastHashed = { html: "", id: versionOf("") };
/** A short fingerprint of a manuscript. */
export function versionOf(html: string): string {
  if (lastHashed?.html === html) return lastHashed.id;
  let hash = 0x811c9dc5;
  for (let i = 0; i < html.length; i++) {
    hash ^= html.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  const id = `${html.length.toString(36)}.${(hash >>> 0).toString(36)}`;
  lastHashed = { html, id };
  return id;
}

function bounded<K, V>(map: Map<K, V>, key: K, value: V, limit: number) {
  map.delete(key);
  map.set(key, value);
  while (map.size > limit) map.delete(map.keys().next().value as K);
}

/** Whether `id` was made, directly or not, from `ancestor`. */
export function descendsFrom(id: string, ancestor: string): boolean {
  const queue = [id];
  const seen = new Set<string>();
  while (queue.length > 0 && seen.size < LINEAGE_LIMIT) {
    const next = queue.shift()!;
    if (next === ancestor) return true;
    if (seen.has(next)) continue;
    seen.add(next);
    queue.push(...(parents.get(next) ?? []));
  }
  return false;
}

function ancestry(id: string): string[] {
  const out: string[] = [];
  const queue = [id];
  const seen = new Set<string>();
  while (queue.length > 0 && seen.size < LINEAGE_LIMIT) {
    const next = queue.shift()!;
    if (seen.has(next)) continue;
    seen.add(next);
    out.push(next);
    queue.push(...(parents.get(next) ?? []));
  }
  return out;
}

const lockName = (tab: string) => `twyne:tab:${tab}`;
const post = (message: Message) => channel?.postMessage(message);
const inView = () => document.visibilityState === "visible";
const liveEditor = () => (editor && !editor.isDestroyed ? editor : null);

function rememberHtml(html: string) {
  bounded(htmlOf, versionOf(html), html, HTML_LIMIT);
}

function markOwn(folioId: string, id: string) {
  const ids = [...(ownIds.get(folioId) ?? []).filter((own) => own !== id), id];
  ownIds.set(folioId, ids.slice(-6));
}

function view(): FolioTabsView {
  const s = shown;
  let elsewhere = 0;
  if (s) {
    for (const other of others.values()) {
      if (other.folioId === s.folioId) elsewhere++;
    }
  }
  return {
    elsewhere,
    presenceDismissed,
    incoming: s?.incoming
      ? { at: s.incoming.at, ...(s.incoming.summary ?? {}) }
      : null,
    applied: s?.applied ? { at: s.applied.at } : null,
  };
}

export function folioTabsView(): FolioTabsView {
  return view();
}

function emit() {
  window.dispatchEvent(
    new CustomEvent<FolioTabsView>(FOLIO_TABS_EVENT, { detail: view() }),
  );
}

function receive(message: Message) {
  if (!message || message.tab === tabId) return;
  const now = Date.now();
  switch (message.t) {
    case "hello":
      others.set(message.tab, { folioId: message.folioId, seen: now });
      post({
        t: "here",
        tab: tabId,
        to: message.tab,
        folioId: shown?.folioId ?? null,
      });
      break;
    case "showing":
      others.set(message.tab, { folioId: message.folioId, seen: now });
      if (message.folioId && message.folioId === shown?.folioId) {
        presenceDismissed = false;
      }
      break;
    case "here":
      if (message.to !== tabId) return;
      others.set(message.tab, { folioId: message.folioId, seen: now });
      break;
    case "bye":
      others.delete(message.tab);
      break;
    case "saved":
      bounded(parents, message.id, message.from, LINEAGE_LIMIT);
      if (!others.has(message.tab)) {
        others.set(message.tab, { folioId: message.folioId, seen: now });
      }
      if (message.folioId === shown?.folioId) follow();
      return;
  }
  emit();
}

/** Look at the stored manuscript soon, at most once per FOLLOW_MS. */
function follow() {
  const s = shown;
  if (!s) return;
  if (!inView()) {
    s.stale = true;
    return;
  }
  if (followTimer !== null) return;
  followTimer = window.setTimeout(() => {
    followTimer = null;
    void reconcile();
  }, FOLLOW_MS);
}

/** Bring this tab in line with what is stored, or say why it cannot. */
function reconcile(): Promise<void> {
  if (reconciling) {
    again = true;
    return reconciling;
  }
  reconciling = reconcileOnce().finally(() => {
    reconciling = null;
    if (again) {
      again = false;
      void reconcile();
    }
  });
  return reconciling;
}

async function reconcileOnce() {
  const s = shown;
  const ed = liveEditor();
  if (!s || !ed) return;
  if (!inView()) {
    s.stale = true;
    return;
  }
  s.stale = false;
  const stored = await loadFolioContentFromIdb(s.folioId);
  if (shown !== s || ed.isDestroyed) return;
  const id = versionOf(stored);
  if (id === s.baseId || ownIds.get(s.folioId)?.includes(id)) return;
  // Already superseded by what this tab has.
  if (descendsFrom(s.baseId, id)) return;
  const current = ed.getHTML();
  if (s.as === null && current === stored) s.as = current;
  if (current === stored) {
    moveBase(s, stored, current);
    emit();
    return;
  }
  const clean = s.as !== null && current === s.as;
  if (clean && descendsFrom(id, s.baseId)) {
    const before = current;
    if (!(await replaceDocument(ed, stored, before, false))) {
      again = true;
      return;
    }
    if (shown !== s) return;
    const after = ed.getHTML();
    moveBase(s, stored, after);
    s.echo = after;
    s.applied = {
      before: s.applied?.before ?? before,
      after: stored,
      at: Date.now(),
    };
    scheduleAppliedNote();
    emit();
    return;
  }
  if (s.incoming?.id === id) return;
  if (s.incoming && !descendsFrom(id, s.incoming.id)) {
    keep(s.folioId, s.incoming.html);
  }
  offer(s, ed, stored);
}

/** This tab's editor is now in step with stored version `html`. */
function moveBase(s: Shown, html: string, as: string | null) {
  const id = versionOf(html);
  rememberHtml(html);
  s.baseId = id;
  s.as = as;
  s.alsoFrom = [];
  if (s.incoming && (s.incoming.id === id || descendsFrom(id, s.incoming.id))) {
    s.incoming = null;
  }
}

function offer(s: Shown, ed: Editor, html: string) {
  rememberHtml(html);
  const incoming: Incoming = {
    html,
    id: versionOf(html),
    at: Date.now(),
    summary: null,
  };
  s.incoming = incoming;
  emit();
  void mergeWith(s, ed, incoming)
    .then(({ merge }) => {
      if (s.incoming !== incoming) return;
      incoming.summary = {
        theirs: merge.theirChanges,
        mine: merge.myChanges,
        conflicts: merge.conflicts,
      };
      emit();
    })
    .catch(() => undefined);
}

function scheduleAppliedNote() {
  if (appliedTimer !== null) window.clearTimeout(appliedTimer);
  appliedTimer = window.setTimeout(() => {
    appliedTimer = null;
    if (!shown?.applied) return;
    if (!inView()) return scheduleAppliedNote();
    shown.applied = null;
    emit();
  }, APPLIED_NOTE_MS);
}

/* ── Editor ─────────────────────────────────────────────────────────── */

type Tiptap = {
  createDocument: typeof import("@tiptap/core").createDocument;
  DOMSerializer: typeof import("@tiptap/pm/model").DOMSerializer;
};
let tiptapModules: Promise<Tiptap> | null = null;

function tiptap() {
  tiptapModules ??= Promise.all([
    import("@tiptap/core"),
    import("@tiptap/pm/model"),
  ]).then(([core, model]) => ({
    createDocument: core.createDocument,
    DOMSerializer: model.DOMSerializer,
  }));
  return tiptapModules;
}

/**
 * Change the editor to `html` in one step that covers only the stretch that
 * differs, so the caret and scroll stay put. False when the editor no longer
 * shows `expect`.
 */
async function replaceDocument(
  ed: Editor,
  html: string,
  expect: string,
  undoable: boolean,
): Promise<boolean> {
  const { createDocument } = await tiptap();
  if (ed.isDestroyed || ed.getHTML() !== expect) return false;
  const next = createDocument(html, ed.schema, ed.options.parseOptions);
  const { doc } = ed.state;
  const start = doc.content.findDiffStart(next.content);
  if (start === null) return true;
  const end = doc.content.findDiffEnd(next.content)!;
  let endA = end.a;
  let endB = end.b;
  const overlap = start - Math.min(endA, endB);
  if (overlap > 0) {
    endA += overlap;
    endB += overlap;
  }
  let tr = ed.state.tr;
  try {
    tr = tr.replace(start, endA, next.slice(start, endB));
  } catch {
    tr = ed.state.tr.replaceWith(0, doc.content.size, next.content);
  }
  ed.view.dispatch(
    tr.setMeta("addToHistory", undoable).setMeta("twyne:other-tab", true),
  );
  return true;
}

async function blocksOf(
  ed: Editor,
  html: string,
  text: Map<string, string>,
): Promise<string[]> {
  const { createDocument, DOMSerializer } = await tiptap();
  const doc = createDocument(html, ed.schema, ed.options.parseOptions);
  const serializer = DOMSerializer.fromSchema(ed.schema);
  const holder = document.createElement("div");
  const out: string[] = [];
  doc.forEach((node) => {
    holder.replaceChildren(serializer.serializeNode(node));
    const block = holder.innerHTML;
    out.push(block);
    if (!text.has(block)) {
      text.set(block, node.textContent.trim() || `[${node.type.name}]`);
    }
  });
  return out;
}

async function mergeOf(
  ed: Editor,
  base: string | null,
  mine: string,
  theirs: string,
): Promise<{ merge: BlockMerge; text: Map<string, string> }> {
  const text = new Map<string, string>();
  const [mineBlocks, theirBlocks] = await Promise.all([
    blocksOf(ed, mine, text),
    blocksOf(ed, theirs, text),
  ]);
  // With no version both grew from, take what they share as the original:
  // nothing either side wrote is dropped, at the cost of more "both" choices.
  const baseBlocks =
    base === null
      ? matchBlocks(mineBlocks, theirBlocks).map(([i]) => mineBlocks[i])
      : await blocksOf(ed, base, text);
  return { merge: mergeBlocks(baseBlocks, mineBlocks, theirBlocks), text };
}

/** The newest version both this tab and `incoming` grew from, if known. */
function commonAncestor(s: Shown, incoming: Incoming): string | null {
  const ours = new Set(ancestry(s.baseId));
  for (const id of ancestry(incoming.id)) {
    if (ours.has(id) && htmlOf.has(id)) return htmlOf.get(id)!;
  }
  return null;
}

function mergeWith(s: Shown, ed: Editor, incoming: Incoming) {
  return mergeOf(ed, commonAncestor(s, incoming), ed.getHTML(), incoming.html);
}

/* ── Versions ───────────────────────────────────────────────────────── */

/**
 * Keep `html` in Versions. Automatic keeps happen at most once a minute per
 * piece, so two tabs typing over each other cannot crowd out checkpoints;
 * a writer's own choice is always kept.
 */
function keep(folioId: string, html: string, chosen = false) {
  const key = `${folioId}:${versionOf(html)}`;
  if (!html || kept.has(key)) return;
  const now = Date.now();
  if (!chosen && now - (keptAt.get(folioId) ?? 0) < KEEP_EVERY_MS) return;
  kept.add(key);
  keptAt.set(folioId, now);
  void createRevisionSnapshot({
    folioId,
    html,
    label: KEPT_LABEL,
    source: "automatic",
    force: true,
  }).catch(() => kept.delete(key));
}

/* ── The route's save path ──────────────────────────────────────────── */

/**
 * Call before this tab stores `html` for `folioId`. Returns a test for
 * whether a stored version is one this tab's manuscript already includes;
 * anything else comes back from the save as displaced.
 */
export function beforeSave(
  folioId: string,
  html: string,
): (stored: string) => boolean {
  markOwn(folioId, versionOf(html));
  const s = shown?.folioId === folioId ? shown : null;
  if (s?.incoming) keep(folioId, s.incoming.html);
  return (stored) => {
    const id = versionOf(stored);
    if (ownIds.get(folioId)?.includes(id)) return true;
    if (!s || shown !== s) return true;
    return id === s.baseId || descendsFrom(s.baseId, id);
  };
}

/** Call once `html` is stored; `displaced` is what it replaced unseen. */
export function afterSave(folioId: string, html: string, displaced?: string) {
  const id = versionOf(html);
  const s = shown?.folioId === folioId ? shown : null;
  const from = s ? [s.baseId, ...s.alsoFrom] : [];
  if (s && id !== s.baseId) {
    bounded(parents, id, from, LINEAGE_LIMIT);
    moveBase(s, html, html);
    if (s.applied) s.applied = null;
  }
  post({ t: "saved", tab: tabId, folioId, id, from });
  const ed = liveEditor();
  if (displaced !== undefined && s && ed && shown === s) {
    keep(folioId, displaced);
    if (!s.incoming) offer(s, ed, displaced);
  }
  if (s) emit();
}

/** True for the editor's echo of a version brought in automatically. */
export function consumeEcho(folioId: string, html: string): boolean {
  const s = shown;
  if (!s || s.folioId !== folioId || s.echo === null) return false;
  const echo = s.echo === html;
  s.echo = null;
  return echo;
}

/** How this tab saves on demand, so other tabs hear about a choice made here. */
export function setSaver(save: ((folioId: string, html: string) => void) | null) {
  saver = save;
}

/** Something else in this tab (a restore, an import, sync) stored a version. */
function storedHere(detail: FolioContentSavedDetail) {
  const { folioId, html } = detail;
  const id = versionOf(html);
  if (ownIds.get(folioId)?.includes(id)) return;
  markOwn(folioId, id);
  const from = shown?.folioId === folioId ? [shown.baseId] : [];
  bounded(parents, id, from, LINEAGE_LIMIT);
  post({ t: "saved", tab: tabId, folioId, id, from });
}

/* ── What the tab shows ─────────────────────────────────────────────── */

/** The editor now shows `folioId` (null: none, or a shared workspace) seeded with `html`. */
export function showingFolio(folioId: string | null, html: string) {
  if (folioId && shown?.folioId === folioId) return loadedHere(folioId, html);
  if (!folioId && !shown) return;
  if (followTimer !== null) window.clearTimeout(followTimer);
  followTimer = null;
  if (folioId) rememberHtml(html);
  shown = folioId
    ? {
        folioId,
        baseId: versionOf(html),
        as: null,
        alsoFrom: [],
        incoming: null,
        applied: null,
        echo: null,
        stale: false,
      }
    : null;
  captureSoon();
  presenceDismissed = false;
  post({ t: "showing", tab: tabId, folioId });
  emit();
  // Another tab may have saved between this tab's read and now.
  if (folioId) follow();
}

/** The editor was re-seeded with `html` for the piece it already shows. */
export function loadedHere(folioId: string, html: string) {
  const s = shown;
  if (!s || s.folioId !== folioId) return;
  if (versionOf(html) !== s.baseId) moveBase(s, html, null);
  s.as = null;
  s.echo = null;
  captureSoon();
  emit();
}

/** Read the editor's serialization once the current re-seed has landed. */
function captureSoon() {
  const s = shown;
  window.setTimeout(() => {
    const ed = liveEditor();
    if (!ed || shown !== s || !s || s.as !== null) return;
    const html = ed.getHTML();
    if (htmlOf.get(s.baseId) !== undefined) {
      // Same blocks as the stored version means the editor is in step.
      s.as = html;
    }
  }, 0);
}

export function attachEditor(next: Editor | null) {
  if (editor === next) return;
  editor = next;
  const s = shown;
  // A freshly mounted editor shows the seed it was given.
  if (s && next) {
    s.as = null;
    s.echo = null;
    captureSoon();
    if (s.stale) follow();
  }
}

/* ── Writer's choices ───────────────────────────────────────────────── */

export async function previewOtherTab(): Promise<FolioTabsPreview | null> {
  const s = shown;
  const ed = liveEditor();
  if (!s || !ed) return null;
  if (s.incoming) {
    const { merge, text } = await mergeWith(s, ed, s.incoming);
    return {
      mode: "incoming",
      changes: changesOf(merge, text),
      mine: merge.myChanges,
    };
  }
  if (s.applied) {
    const { before, after } = s.applied;
    const { merge, text } = await mergeOf(ed, before, before, after);
    return { mode: "applied", changes: changesOf(merge, text), mine: 0 };
  }
  return null;
}

function changesOf(
  merge: BlockMerge,
  text: Map<string, string>,
): FolioTabsChange[] {
  const read = (blocks: string[]) =>
    blocks.map((block) => text.get(block) ?? "").join("\n\n");
  const close = (block: string | undefined) => {
    const words = block === undefined ? "" : (text.get(block) ?? "");
    return words.length > 90 ? `…${words.slice(-88).trimStart()}` : words;
  };
  const changes: FolioTabsChange[] = [];
  let previous: string | undefined;
  merge.regions.forEach((region, index) => {
    switch (region.kind) {
      case "same":
      case "both-same":
        previous = region.blocks.at(-1) ?? previous;
        return;
      case "mine":
        previous = region.mine.at(-1) ?? previous;
        return;
      case "theirs":
        changes.push({
          kind: "theirs",
          id: index,
          after: close(previous) || undefined,
          parts: diffWords(read(region.base), read(region.theirs)),
        });
        previous = region.theirs.at(-1) ?? previous;
        return;
      case "conflict":
        changes.push({
          kind: "conflict",
          id: region.id,
          after: close(previous) || undefined,
          parts: diffWords(read(region.mine), read(region.theirs)),
          mine: read(region.mine),
          theirs: read(region.theirs),
        });
        previous = region.theirs.at(-1) ?? previous;
        return;
    }
  });
  return changes;
}

/**
 * Bring the other tab's changes in. Paragraphs only one tab changed take
 * that tab's wording; ones both changed follow `choices`, keeping both by
 * default. One undoable step.
 */
export async function bringInOtherTab(
  choices: Record<number, ConflictChoice> = {},
): Promise<boolean> {
  const s = shown;
  const ed = liveEditor();
  const incoming = s?.incoming;
  if (!s || !ed || !incoming) return false;
  keep(s.folioId, incoming.html, true);
  for (let attempt = 0; attempt < 3; attempt++) {
    const current = ed.getHTML();
    const { merge } = await mergeWith(s, ed, incoming);
    const html = resolveMerge(merge, choices).join("");
    if (!(await replaceDocument(ed, html, current, true))) continue;
    if (shown !== s || s.incoming !== incoming) return false;
    integrate(s, incoming);
    // Nothing changed here, so no save follows by itself: save so the other
    // tab hears this one already has its changes.
    if (ed.getHTML() === current) saver?.(s.folioId, current);
    emit();
    return true;
  }
  return false;
}

/** The next save from this tab is made from `incoming` and from its own base. */
function integrate(s: Shown, incoming: Incoming) {
  const previous = s.baseId;
  rememberHtml(incoming.html);
  s.baseId = incoming.id;
  s.alsoFrom = [previous];
  s.as = null;
  s.incoming = null;
  s.applied = null;
}

/** Keep this tab's version; the other tab's goes to Versions. */
export function keepThisTab() {
  const s = shown;
  const ed = liveEditor();
  if (!s?.incoming || !ed) return;
  keep(s.folioId, s.incoming.html, true);
  integrate(s, s.incoming);
  saver?.(s.folioId, ed.getHTML());
  emit();
}

export function dismissOtherTab(what: "presence" | "applied") {
  if (what === "presence") presenceDismissed = true;
  else if (shown) shown.applied = null;
  emit();
}

/* ── Lifetime ───────────────────────────────────────────────────────── */

async function prune() {
  if (!navigator.locks?.query) return;
  const { held = [] } = await navigator.locks.query();
  const alive = new Set(held.map((lock) => lock.name));
  const now = Date.now();
  let changed = false;
  for (const [tab, other] of others) {
    // A tab that has only just arrived may not hold its lock yet.
    if (now - other.seen > 5_000 && !alive.has(lockName(tab))) {
      others.delete(tab);
      changed = true;
    }
  }
  if (changed) emit();
}

export function startFolioTabs(): () => void {
  if (channel || typeof BroadcastChannel === "undefined") {
    return () => undefined;
  }
  tabId = crypto.randomUUID();
  channel = new BroadcastChannel(CHANNEL);
  channel.onmessage = (event: MessageEvent<Message>) => receive(event.data);
  let release: () => void = () => undefined;
  void navigator.locks
    ?.request(
      lockName(tabId),
      () => new Promise<void>((resolve) => (release = resolve)),
    )
    .catch(() => undefined);
  const onStored = (event: Event) =>
    storedHere((event as CustomEvent<FolioContentSavedDetail>).detail);
  const onReturn = () => {
    if (!inView()) return;
    void prune();
    if (shown?.stale) void reconcile();
  };
  const onLeave = () => post({ t: "bye", tab: tabId });
  const onBack = (event: PageTransitionEvent) => {
    if (!event.persisted) return;
    others.clear();
    post({ t: "hello", tab: tabId, folioId: shown?.folioId ?? null });
    if (shown) void reconcile();
  };
  window.addEventListener(FOLIO_CONTENT_SAVED, onStored);
  window.addEventListener("focus", onReturn);
  window.addEventListener("pagehide", onLeave);
  window.addEventListener("pageshow", onBack);
  document.addEventListener("visibilitychange", onReturn);
  post({ t: "hello", tab: tabId, folioId: shown?.folioId ?? null });
  return () => {
    window.removeEventListener(FOLIO_CONTENT_SAVED, onStored);
    window.removeEventListener("focus", onReturn);
    window.removeEventListener("pagehide", onLeave);
    window.removeEventListener("pageshow", onBack);
    document.removeEventListener("visibilitychange", onReturn);
    for (const timer of [followTimer, appliedTimer]) {
      if (timer !== null) window.clearTimeout(timer);
    }
    followTimer = null;
    appliedTimer = null;
    post({ t: "bye", tab: tabId });
    channel?.close();
    channel = null;
    release();
    others.clear();
    shown = null;
    editor = null;
  };
}

