import { $, component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
import type { ConflictChoice } from "../../utils/block-merge";
import {
  FOLIO_TABS_EVENT,
  bringInOtherTab,
  dismissOtherTab,
  folioTabsView,
  keepThisTab,
  previewOtherTab,
  type FolioTabsPreview,
  type FolioTabsView,
} from "../../utils/folio-tabs";

const plural = (n: number, one: string, many = `${one}s`) =>
  `${n} ${n === 1 ? one : many}`;

/**
 * The line under the masthead for a piece also open in another tab: that it
 * is, that changes came in, or that both tabs changed it and the writer
 * chooses. The preview shows the other tab's changes word by word.
 */
export const OtherTabNotice = component$(() => {
  const state = useStore<{
    view: FolioTabsView | null;
    preview: FolioTabsPreview | null;
    choices: Record<number, ConflictChoice>;
    busy: boolean;
    failed: boolean;
  }>({ view: null, preview: null, choices: {}, busy: false, failed: false });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(
    ({ cleanup }) => {
      state.view = folioTabsView();
      const onChange = (event: Event) => {
        state.view = (event as CustomEvent<FolioTabsView>).detail;
        // What the preview showed is gone once there is nothing to look at.
        if (state.preview && !state.view.incoming && !state.view.applied) {
          state.preview = null;
        }
      };
      window.addEventListener(FOLIO_TABS_EVENT, onChange);
      cleanup(() => window.removeEventListener(FOLIO_TABS_EVENT, onChange));
    },
    { strategy: "document-ready" },
  );

  const openPreview = $(async () => {
    state.failed = false;
    state.choices = {};
    state.preview = await previewOtherTab();
  });
  const close = $(() => {
    state.preview = null;
  });
  const bringIn = $(async () => {
    state.busy = true;
    state.failed = false;
    try {
      const done = await bringInOtherTab({ ...state.choices });
      state.failed = !done;
      if (done) state.preview = null;
    } finally {
      state.busy = false;
    }
  });
  const keepMine = $(() => {
    keepThisTab();
    state.preview = null;
  });

  const view = state.view;
  if (!view) return null;
  const incoming = view.incoming;
  const preview = state.preview;

  let line = null;
  if (incoming) {
    const counts =
      incoming.theirs === undefined
        ? ""
        : ` — ${plural(incoming.theirs, "paragraph")}${
            incoming.conflicts
              ? `, ${incoming.conflicts} of them also changed here`
              : ""
          }`;
    line = (
      <div class="other-tab-notice other-tab-notice--incoming press-arrive">
        <span class="other-tab-notice__mark" aria-hidden="true">
          ⇄
        </span>
        <span class="other-tab-notice__label">
          Another tab changed this piece{counts}.
        </span>
        <button
          type="button"
          class="other-tab-notice__action focus-ring"
          onClick$={openPreview}
        >
          Preview
        </button>
        <button
          type="button"
          class="other-tab-notice__action other-tab-notice__action--primary focus-ring"
          disabled={state.busy}
          onClick$={bringIn}
        >
          Bring them in
        </button>
        <button
          type="button"
          class="other-tab-notice__action focus-ring"
          title="The other tab's version goes to Versions"
          onClick$={keepMine}
        >
          Keep this tab's
        </button>
        {state.failed && !preview && (
          <span class="other-tab-notice__label">
            Still typing here — try again in a moment.
          </span>
        )}
      </div>
    );
  } else if (view.applied) {
    line = (
      <div class="other-tab-notice press-fade">
        <span class="other-tab-notice__mark" aria-hidden="true">
          ⇄
        </span>
        <span class="other-tab-notice__label">
          Brought in changes from another tab.
        </span>
        <button
          type="button"
          class="other-tab-notice__action focus-ring"
          onClick$={openPreview}
        >
          See what changed
        </button>
        <button
          type="button"
          class="other-tab-notice__dismiss focus-ring"
          aria-label="Dismiss"
          onClick$={() => dismissOtherTab("applied")}
        >
          ×
        </button>
      </div>
    );
  } else if (view.elsewhere > 0 && !view.presenceDismissed) {
    line = (
      <div class="other-tab-notice press-fade">
        <span class="other-tab-notice__mark" aria-hidden="true">
          ⇄
        </span>
        <span class="other-tab-notice__label">
          Also open in{" "}
          {view.elsewhere === 1
            ? "another tab"
            : `${view.elsewhere} other tabs`}
          . Changes made there show up here.
        </span>
        <button
          type="button"
          class="other-tab-notice__dismiss focus-ring"
          aria-label="Dismiss"
          onClick$={() => dismissOtherTab("presence")}
        >
          ×
        </button>
      </div>
    );
  }

  return (
    <>
      <div role="status" aria-live="polite" data-other-tab-notice>
        {line}
      </div>
      {preview && (
        <div
          class="fixed inset-0 flex items-center justify-center p-4"
          style={{
            zIndex: "var(--z-modal)",
            background: "rgba(20, 16, 10, 0.58)",
          }}
          onClick$={(e) => {
            if (e.target === e.currentTarget) state.preview = null;
          }}
          onKeyDown$={(e) => {
            if (e.key === "Escape") state.preview = null;
          }}
        >
          <div
            class="folio other-tab-preview w-full max-w-2xl p-5 press-arrive"
            role="dialog"
            aria-modal="true"
            aria-labelledby="other-tab-preview-title"
          >
            <p class="dept-label mb-2">Another tab</p>
            <h2
              id="other-tab-preview-title"
              class="text-base font-semibold text-[var(--color-ink)]"
              style={{ fontFamily: "var(--font-display)" }}
            >
              {preview.mode === "incoming"
                ? "What the other tab changed"
                : "What came in from the other tab"}
            </h2>
            {preview.mode === "incoming" && (
              <p class="mt-1 text-sm leading-relaxed text-[var(--color-ink-light)]">
                Bringing them in changes only these passages
                {preview.mine > 0
                  ? `; the ${plural(preview.mine, "paragraph")} you changed here stay as they are`
                  : ""}
                . You can undo it, and the other tab's version is kept in
                Versions either way.
              </p>
            )}

            <ol class="other-tab-preview__changes">
              {preview.changes.length === 0 && (
                <li class="other-tab-preview__change">
                  <p class="other-tab-preview__where">
                    Only formatting or spacing changed.
                  </p>
                </li>
              )}
              {preview.changes.map((change) => {
                const visible = change.parts.some(
                  (part) => part.kind !== "same" && part.text.trim(),
                );
                return (
                  <li
                    key={`${change.kind}-${change.id}`}
                    class={[
                      "other-tab-preview__change",
                      {
                        "other-tab-preview__change--conflict":
                          change.kind === "conflict",
                      },
                    ]}
                  >
                    <p class="other-tab-preview__where">
                      {change.kind === "conflict"
                        ? "Changed in both tabs"
                        : change.after
                          ? `After “${change.after}”`
                          : "At the start"}
                    </p>
                    {change.kind === "theirs" ? (
                      visible ? (
                        <p class="other-tab-preview__diff">
                          {change.parts.map((part, i) =>
                            part.kind === "same" ? (
                              <span key={i}>{part.text}</span>
                            ) : part.kind === "removed" ? (
                              <del key={i}>{part.text}</del>
                            ) : (
                              <ins key={i}>{part.text}</ins>
                            ),
                          )}
                        </p>
                      ) : (
                        <p class="other-tab-preview__diff">
                          Formatting or spacing.
                        </p>
                      )
                    ) : (
                      <>
                        <div class="other-tab-preview__sides">
                          <div>
                            <p class="other-tab-preview__side">This tab</p>
                            <p class="other-tab-preview__diff">
                              {change.mine || "(removed)"}
                            </p>
                          </div>
                          <div>
                            <p class="other-tab-preview__side">Other tab</p>
                            <p class="other-tab-preview__diff">
                              {change.theirs || "(removed)"}
                            </p>
                          </div>
                        </div>
                        {preview.mode === "incoming" && (
                          <div
                            class="other-tab-preview__choice"
                            role="radiogroup"
                            aria-label="Which wording to keep"
                          >
                            {(
                              [
                                ["both", "Keep both"],
                                ["mine", "This tab's"],
                                ["theirs", "The other tab's"],
                              ] as const
                            ).map(([choice, label]) => (
                              <label key={choice}>
                                <input
                                  type="radio"
                                  name={`other-tab-choice-${change.id}`}
                                  checked={
                                    (state.choices[change.id] ?? "both") ===
                                    choice
                                  }
                                  onChange$={() => {
                                    state.choices = {
                                      ...state.choices,
                                      [change.id]: choice,
                                    };
                                  }}
                                />{" "}
                                {label}
                              </label>
                            ))}
                          </div>
                        )}
                      </>
                    )}
                  </li>
                );
              })}
            </ol>

            {state.failed && (
              <p class="mt-3 text-sm text-[var(--color-vermilion-2)]">
                This tab kept changing while bringing them in. Try again.
              </p>
            )}
            <div class="mt-5 flex flex-wrap justify-end gap-2">
              {preview.mode === "incoming" ? (
                <>
                  <button
                    type="button"
                    class="btn-paper text-xs"
                    onClick$={close}
                  >
                    Close
                  </button>
                  <button
                    type="button"
                    class="btn-paper text-xs"
                    onClick$={keepMine}
                  >
                    Keep this tab's
                  </button>
                  <button
                    type="button"
                    class="btn-press text-xs text-[var(--color-paper)]"
                    disabled={state.busy}
                    autoFocus
                    onClick$={bringIn}
                  >
                    Bring them in
                  </button>
                </>
              ) : (
                <button
                  type="button"
                  class="btn-paper text-xs"
                  autoFocus
                  onClick$={close}
                >
                  Close
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </>
  );
});

