// Two tabs on the same piece with the other-tab coordinator: presence, a
// change followed by a clean tab, then edits made in both tabs at once.
// Usage: node other-tab.mjs <url> [firefox|chromium]
import { resolve } from "node:path";
const [url, engine = "firefox"] = process.argv.slice(2);
const pw = await import(resolve(process.cwd(), "node_modules/playwright/index.mjs"));
const browser = await pw[engine].launch();
const context = await browser.newContext({ viewport: { width: 1280, height: 860 } });
await context.route(/posthog/, (r) => r.abort());
await context.route(/\/api\/auth\//, (r) => r.fulfill({ status: 200, contentType: "application/json", body: "null" }));
const seed = await context.newPage();
await seed.goto(`${url}/editor/`, { waitUntil: "load" });
await seed.waitForTimeout(1500);
await seed.evaluate(async () => {
  const db = await new Promise((res, rej) => { const r = indexedDB.open("twyne"); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
  const now = Date.now();
  const put = (store, value) => new Promise((res, rej) => { const t = db.transaction(store, "readwrite"); t.objectStore(store).put(value); t.oncomplete = res; t.onerror = () => rej(t.error); });
  await put("folios", { id: "f-two", name: "Two windows", type: "draft", createdAt: now, updatedAt: now });
  await put("folio-content", { folioId: "f-two", html: "<h1>Two windows</h1><p>First paragraph.</p><p>Second paragraph.</p><p>Third paragraph.</p>", updatedAt: now });
  await put("meta", { key: "active-folio-id", value: "f-two", updatedAt: now });
  await put("meta", { key: "signin-toast-dismissed", value: true, updatedAt: now });
  await put("meta", { key: "live-review-enabled", value: false, updatedAt: now });
  localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, compositorOpen: false }));
  db.close();
});
await seed.close();
const errors = [];
const open = async (name) => {
  const p = await context.newPage();
  p.on("pageerror", (e) => errors.push(`${name}: ${String(e).slice(0, 200)}`));
  p.on("console", (m) => { if (m.type() === "error") errors.push(`${name} console: ${m.text().slice(0, 200)}`); });
  await p.goto(`${url}/editor/`, { waitUntil: "load" });
  await p.locator("#twyne-editor-mount .ProseMirror").waitFor({ timeout: 60000 });
  await p.waitForTimeout(2500);
  return p;
};
const type = async (p, n, words) => {
  await p.bringToFront();
  const para = p.locator("#twyne-editor-mount .ProseMirror p").nth(n);
  const box = await para.boundingBox();
  await p.mouse.click(box.x + box.width - 3, box.y + box.height - 6);
  await p.keyboard.press("End");
  await p.keyboard.type(words, { delay: 20 });
};
const text = (p) => p.evaluate(() => document.querySelector("#twyne-editor-mount .ProseMirror")?.textContent ?? "");
const notice = (p) => p.evaluate(() => document.querySelector("[data-other-tab-notice]")?.textContent?.replace(/\s+/g, " ").trim() ?? "");
const stored = (p) => p.evaluate(async () => {
  const db = await new Promise((res, rej) => { const r = indexedDB.open("twyne"); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
  const get = (store, key) => new Promise((res) => { const g = db.transaction(store).objectStore(store).get(key); g.onsuccess = () => res(g.result); g.onerror = () => res(null); });
  const rec = await get("folio-content", "f-two");
  db.close();
  return rec?.html ?? "";
});
const versions = (p) => p.evaluate(async () => {
  const { loadRevisionHistory } = await import("/src/utils/revision-history.ts");
  return (await loadRevisionHistory("f-two")).map((r) => ({ label: r.label, html: r.html }));
});
const has = (s, ...words) => Object.fromEntries(words.map((w) => [w, s.includes(w)]));
const report = { engine };

const a = await open("A");
const b = await open("B");
await a.waitForTimeout(500);
report["1 presence"] = { A: await notice(a), B: await notice(b) };

// A writes; B has no edits of its own and follows.
await type(a, 0, " ALPHA");
await a.waitForTimeout(3500);
report["2 B follows A"] = { B: has(await text(b), "ALPHA"), notice: await notice(b), stored: has(await stored(a), "ALPHA") };
const caretB = await b.evaluate(() => getSelection()?.anchorNode?.textContent?.slice(0, 40) ?? null);
report["2 B follows A"].caretB = caretB;

// Both write at once, in different paragraphs.
await type(b, 1, " BRAVO");
await type(a, 2, " CHARLIE");
await a.waitForTimeout(4000);
report["3 both wrote"] = {
  A: { text: has(await text(a), "ALPHA", "BRAVO", "CHARLIE"), notice: await notice(a) },
  B: { text: has(await text(b), "ALPHA", "BRAVO", "CHARLIE"), notice: await notice(b) },
  stored: has(await stored(a), "ALPHA", "BRAVO", "CHARLIE"),
  kept: (await versions(a)).filter((v) => v.label === "Kept from another tab").map((v) => has(v.html, "BRAVO", "CHARLIE")),
};

// Whichever tab has the notice previews and brings the changes in.
const target = (await notice(a)).includes("Another tab changed") ? a : (await notice(b)).includes("Another tab changed") ? b : null;
if (target) {
  const name = target === a ? "A" : "B";
  await target.bringToFront();
  await target.getByRole("button", { name: "Preview" }).click();
  await target.waitForTimeout(600);
  const dialog = target.locator(".other-tab-preview");
  report["4 preview"] = {
    tab: name,
    title: await dialog.locator("h2").textContent(),
    changes: await dialog.locator(".other-tab-preview__change").allTextContents().then((all) => all.map((t) => t.replace(/\s+/g, " ").trim())),
    inserted: await dialog.locator("ins").allTextContents(),
  };
  await dialog.getByRole("button", { name: "Bring them in" }).click();
  await target.waitForTimeout(4500);
  report["5 after bringing in"] = {
    A: { text: has(await text(a), "ALPHA", "BRAVO", "CHARLIE"), notice: await notice(a) },
    B: { text: has(await text(b), "ALPHA", "BRAVO", "CHARLIE"), notice: await notice(b) },
    stored: has(await stored(a), "ALPHA", "BRAVO", "CHARLIE"),
  };
  // Undo in the tab that brought them in removes only what came in.
  await target.bringToFront();
  await target.locator("#twyne-editor-mount .ProseMirror").click();
  await target.keyboard.press("Control+z");
  await target.waitForTimeout(300);
  report["6 undo bring-in"] = has(await text(target), "ALPHA", "BRAVO", "CHARLIE");
} else {
  report["4 preview"] = "no tab showed the notice";
}
report.errors = errors.filter((e) => !/posthog|favicon|ERR_ABORTED|net::/i.test(e)).slice(0, 12);
console.log(JSON.stringify(report, null, 1));
await browser.close();

