/** Timing and geometry for a passage preview. No DOM or timers are owned here. */
export const HOVER_INTENT_MS = 350;
export const HOVER_DWELL_MS = 750;
export const HOVER_GRACE_MS = 450;

export type Point = { x: number; y: number };
export type CardRect = { left: number; right: number; top: number; bottom: number };
export type HoverState = {
  id: string | null;
  phase: "idle" | "intent" | "visible" | "held";
  deadline: number | null;
  closing: boolean;
};
export const idleHover = (): HoverState => ({ id: null, phase: "idle", deadline: null, closing: false });
export type HoverEvent =
  | { type: "enter"; id: string; now: number }
  | { type: "leave"; now: number }
  | { type: "return"; now: number }
  | { type: "tick"; now: number }
  | { type: "dismiss" };

export function hoverTransition(state: HoverState, event: HoverEvent): HoverState {
  switch (event.type) {
    case "dismiss": return idleHover();
    case "enter":
      if (state.id === event.id && state.phase !== "idle") return state;
      return { id: event.id, phase: "intent", deadline: event.now + HOVER_INTENT_MS, closing: false };
    case "leave":
      if (state.phase === "intent") return idleHover();
      if (state.phase === "visible") return { ...state, deadline: event.now + HOVER_GRACE_MS, closing: true };
      return state;
    case "return":
      if (state.phase === "visible" && state.closing) return { ...state, deadline: event.now + HOVER_DWELL_MS, closing: false };
      return state;
    case "tick":
      if (state.deadline === null || event.now < state.deadline) return state;
      if (state.closing) return idleHover();
      if (state.phase === "intent") return { ...state, phase: "visible", deadline: event.now + HOVER_DWELL_MS };
      if (state.phase === "visible") return { ...state, phase: "held", deadline: null };
      return state;
  }
}

/** Triangle from the point where the passage was left to the card's near edge. */
export function towardCard(origin: Point, point: Point, rect: CardRect): boolean {
  const edge = origin.x < rect.left ? rect.left : origin.x > rect.right ? rect.right : null;
  if (edge === null) return point.x >= rect.left - 12 && point.x <= rect.right + 12 && point.y >= Math.min(origin.y, rect.top) - 12 && point.y <= Math.max(origin.y, rect.bottom) + 12;
  const a = origin;
  const b = { x: edge, y: rect.top - 20 };
  const c = { x: edge, y: rect.bottom + 20 };
  const cross = (p: Point, q: Point, r: Point) => (q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x);
  const d1 = cross(a, b, point), d2 = cross(b, c, point), d3 = cross(c, a, point);
  return !(d1 < 0 || d2 < 0 || d3 < 0) || !(d1 > 0 || d2 > 0 || d3 > 0);
}

/** Timer adapter around the pure transition function. */
export function createHoverCard(onChange: (next: HoverState, previous: HoverState) => void) {
  let state = idleHover();
  let timer: ReturnType<typeof setTimeout> | undefined;
  let candidate: ReturnType<typeof setTimeout> | undefined;
  const send = (event: HoverEvent) => {
    // Keep a held card while testing intent on a different passage. A fast
    // pass across another mark must not evict the conversation being read.
    if (event.type === "enter" && state.phase === "held" && event.id !== state.id) {
      clearTimeout(candidate);
      const { id, now } = event;
      candidate = setTimeout(() => {
        candidate = undefined;
        const previous = state;
        state = hoverTransition(state, { type: "enter", id, now });
        onChange(state, previous);
        send({ type: "tick", now: Date.now() });
      }, HOVER_INTENT_MS);
      return;
    }
    if (event.type === "leave" || event.type === "dismiss" || (event.type === "enter" && event.id === state.id)) {
      clearTimeout(candidate);
      candidate = undefined;
    }
    const previous = state;

