function queueUrl(value: unknown): string {
  if (typeof value !== "string")
    throw new Error("fal returned an invalid queue URL.");
  const url = new URL(value);
  if (
    url.origin !== "https://queue.fal.run" ||
    url.username ||
    url.password ||
    url.hash
  )
    throw new Error("fal returned an invalid queue URL.");
  return url.href;
}
function mediaUrl(value: unknown): string {
  if (typeof value !== "string") throw new Error("fal returned no media.");
  const url = new URL(value);
  if (
    url.protocol !== "https:" ||
    url.username ||
    url.password ||
    url.port ||
    !/(^|\.)fal\.media$/.test(url.hostname)
  )
    throw new Error("fal returned an invalid media URL.");
  return url.href;
}
async function json(response: Response): Promise<Record<string, unknown>> {
  if (!response.ok) throw new Error(`fal request failed (${response.status}).`);
  const result: unknown = await response.json();
  if (!result || typeof result !== "object" || Array.isArray(result))
    throw new Error("fal returned an invalid response.");
  return result as Record<string, unknown>;
}
export async function submitSceneFal(
  medium: FalSceneMedium,
  prompt: string,
  key: string,
  image?: string,
  fetcher: typeof fetch = fetch,
): Promise<FalSceneJob> {
  if (!key.trim() || !prompt.trim())
    throw new Error("Add your fal key and choose a scene.");
  if (medium === "motion" && !image?.startsWith("data:image/"))
    throw new Error("Choose a look first.");
  const input =
    medium === "image"
      ? { prompt, num_images: 1, image_size: "landscape_4_3" }
      : medium === "sound"
        ? { prompt, duration: 5 }
        : { prompt, image_url: image, duration: "6" };
  const data = await json(
    await fetcher(`https://queue.fal.run/${SCENE_FAL_MODELS[medium]}`, {
      method: "POST",
      headers: {
        Authorization: `Key ${key.trim()}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(input),
      redirect: "error",
    }),
  );
  return {
    medium,
    statusUrl: queueUrl(data.status_url),
    responseUrl: queueUrl(data.response_url),
  };
}
export async function pollSceneFal(
  job: FalSceneJob,
  key: string,
  fetcher: typeof fetch = fetch,
): Promise<{ status: "waiting" } | { status: "ready"; url: string }> {
  const headers = { Authorization: `Key ${key.trim()}` };
  const state = await json(
    await fetcher(queueUrl(job.statusUrl), { headers, redirect: "error" }),
  );
  if (state.status === "IN_QUEUE" || state.status === "IN_PROGRESS")
    return { status: "waiting" };
  if (state.status !== "COMPLETED" || state.error)
    throw new Error("fal could not finish this take.");
  const data = await json(
    await fetcher(queueUrl(job.responseUrl), { headers, redirect: "error" }),
  );
  const file =
    job.medium === "image"
      ? Array.isArray(data.images)
        ? data.images[0]
        : null
      : job.medium === "sound"
        ? data.audio_file
        : data.video;
  const url =
    file && typeof file === "object"
      ? (file as { url?: unknown }).url
      : undefined;
  return { status: "ready", url: mediaUrl(url) };
}

