export const submitTake = action({
  args: {
    medium: v.union(v.literal("sound"), v.literal("motion")),
    prompt: v.string(),
    image: v.optional(v.string()),
  },
  returns: v.object({ jobId: v.string() }),
  handler: async (ctx, args) => {
    const prompt = args.prompt.trim();
    if (!prompt || prompt.length > 4000)
      throw new Error("Choose a shorter scene prompt.");
    if (
      args.medium === "motion" &&
      (!args.image ||
        !/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(
          args.image,
        ) ||
        args.image.length > 700_000)
    )
      throw new Error("Choose a smaller PNG, JPEG, or WebP look for motion.");
    const link = await account(ctx);
    await consumeRateLimit(ctx, {
      action: `scene:${args.medium}`,
      identifier: link.identity.tokenIdentifier,
      ...RATE_LIMITS.scenePicture,
    });
    const budget =
      args.medium === "motion"
        ? SCENE_MOTION_BUDGET_MICROS
        : SCENE_SOUND_BUDGET_MICROS;
    const wallet = await walletCredit(link, `scene-${args.medium}`);
    if (!wallet.eligible || wallet.availableMicros < budget)
      throw new Error("Add credit to generate this take.");
    const token = await issueNotOrganicAccessToken({
      ...link,
      feature: `scene-${args.medium}`,
      capabilities: [
        args.medium === "motion" ? "videos:generate" : "infer:image",
      ],
    });
    const result = await providerJsonRequest<{ job_id?: unknown }>(
      args.medium === "motion" ? "/v1/videos/generations" : "/v1/fal/jobs",
      token,
      {
        method: "POST",
        headers: {
          "idempotency-key": `scene_${crypto.randomUUID()}`,
          "x-notorganic-max-cost-microusd": String(budget),
        },
        body: JSON.stringify(
          args.medium === "motion"
            ? {
                model: "video-fast",
                prompt,
                image_url: args.image,
                duration_seconds: 5,
              }
            : { model: "sound-scene", input: { prompt, duration: 5 } },
        ),
      },
      { issuer: notOrganicIssuer(), feature: `scene-${args.medium}` },
    );
    if (
      typeof result.job_id !== "string" ||
      !/^(vid|fal)_[A-Za-z0-9_-]{43}$/.test(result.job_id)
    )
      throw new Error("The take could not be started.");
    return { jobId: result.job_id };
  },
});

export const pollTake = action({
  args: {
    medium: v.union(v.literal("sound"), v.literal("motion")),
    jobId: v.string(),
  },
  returns: v.object({
    status: v.union(
      v.literal("waiting"),
      v.literal("failed"),
      v.literal("ready"),
    ),
    url: v.optional(v.string()),
  }),
  handler: async (ctx, args) => {
    if (
      !(args.medium === "motion" ? /^vid_/ : /^fal_/).test(args.jobId) ||
      !/^(vid|fal)_[A-Za-z0-9_-]{43}$/.test(args.jobId)
    )
      throw new Error("Invalid take.");
    const link = await account(ctx);
    const token = await issueNotOrganicAccessToken({
      ...link,
      feature: `scene-${args.medium}`,
      capabilities: [args.medium === "motion" ? "videos:read" : "infer:image"],
    });
    const path =
      args.medium === "motion"
        ? `/v1/videos/generations/${args.jobId}`
        : `/v1/fal/jobs/${args.jobId}`;
    const result = await providerJsonRequest<{
      status?: unknown;
      video_url?: unknown;
      result?: { audio_file?: { url?: unknown } };
    }>(
      path,
      token,
      {},
      { issuer: notOrganicIssuer(), feature: `scene-${args.medium}` },
    );
    if (result.status === "failed") return { status: "failed" as const };
    if (result.status !== "succeeded") return { status: "waiting" as const };
    const url =
      args.medium === "motion"
        ? result.video_url
        : result.result?.audio_file?.url;
    if (typeof url !== "string" || !/^https:\/\/[^/]+/.test(url))
      throw new Error("The take returned no media.");
    return { status: "ready" as const, url };
  },
});

