/**
 * Line edits: the pure parts.
 *
 * The Line Editor reads sentences the writer has just written or rewritten,
 * picks the few that read oddly, and asks the configured prose model for a
 * handful of rewrites in the writer's own voice. Nothing here touches the
 * editor or calls a model. The code owns what no model can be trusted with:
 * which sentences are worth a request at all, what counts as an acceptable
 * rewrite of the exact original, which wordings the writer has asked it to
 * leave alone, and remembering an answer so the same wording is never read
 * twice.
 */
import type { GrammarIssue } from "./grammar";
import { REVISION_MAX_CHARS } from "./sentence-bench";
import { hedgeCount, wordCount } from "./struggle-signals";

export const MAX_LINE_REWRITES = 5;
/** Model requests per editor session; the loop stops asking after this. */
export const MAX_LINE_REQUESTS = 40;
/** Remembered "leave it" wordings, most recent kept. */
export const LEAVE_MEMORY_LIMIT = 500;
export const LEAVE_MEMORY_KEY = "line-editor:left:v1";

export const squashWording = (s: string) => s.replace(/\s+/g, " ").trim();

/* ── Choosing candidates ──────────────────────────────────────── */

export interface LineFinding {
  /** Harper found it, or a local reading of the sentence did. */
  source: "harper" | "local";
  /** Plain words, shown to the writer as the reason. */
  label: string;
}

/** Word counts beyond which length alone is a reason. */
const LONG_WORDS = 38;
const VERY_LONG_WORDS = 45;
/** Harper kinds the grammar desk already owns word by word. */
const DESK_KINDS = new Set(["Spelling", "Capitalization"]);

const STOP = new Set(
  "that this with from they them their there these those have been were will would could should about which while where when what your into over under than then also just only very more most some such each other after before because through between against during without within along across".split(
    " ",
  ),
);

/**
 * Cheap, local reasons a sentence may need work. Harper's findings arrive
 * from the caller (already computed for the ledger), so no second lint runs.
 * Local cues are hints for the model, not verdicts; a sentence is only a
 * candidate when the cues are strong enough to be worth one request.
 */
export function lineFindings(
  text: string,
  issues: readonly GrammarIssue[] = [],
): LineFinding[] {
  const out: LineFinding[] = [];
  const seen = new Set<string>();
  for (const issue of issues) {
    if (DESK_KINDS.has(issue.kind)) continue;
    const label = squashWording(issue.message).replace(/\.$/, "");
    if (!label || seen.has(label)) continue;
    seen.add(label);
    out.push({ source: "harper", label });
    if (out.length >= 3) break;
  }
  const words = wordCount(text);
  if (words >= LONG_WORDS)
    out.push({ source: "local", label: `runs long: ${words} words` });

  const commas = (text.match(/[,;:]/g) ?? []).length;
  const joins = (text.match(/\b(and|but|so|or|yet)\b/gi) ?? []).length;
  if (joins >= 3 && commas >= 2)
    out.push({ source: "local", label: "chains clauses" });

  const repeat = nearRepeat(text);
  if (repeat) out.push({ source: "local", label: `repeats “${repeat}”` });

  if (
    /^(?:\p{L}+ing|\p{L}+ed)\b[^,]{0,70},\s+(?:it|there|this|that|the|a|an|his|her|their|my|our|its)\b/iu.test(
      text,
    )
  )
    out.push({ source: "local", label: "the opener may hang" });

  if (hedgeCount(text) >= 2)
    out.push({ source: "local", label: "stacks hedges" });

  if (/^there\s+(?:is|are|was|were)\b.{8,}\b(?:that|which|who)\b/i.test(text))
    out.push({ source: "local", label: "starts with there is" });

  const prepositions = (
    text.match(/\b(?:of|in|on|for|with|to|by|from|at|into|onto)\b/gi) ?? []
  ).length;
  if (prepositions >= 6 && words > 0 && prepositions / words >= 0.22)
    out.push({ source: "local", label: "piles up prepositions" });

  if (
    /\b(?:not|never|no|nobody|nothing)\b[^.;]{0,30}\b(?:not|never|no|nobody|nothing|un\p{L}{3,}|hardly|scarcely)\b/iu.test(
      text,
    )
  )
    out.push({ source: "local", label: "doubles a negative" });
  return out;
}

/** The same content word twice within a few words of itself. */
function nearRepeat(text: string): string | null {
  const tokens = text.toLocaleLowerCase().match(/[\p{L}]+/gu) ?? [];
  const last = new Map<string, number>();
  for (let i = 0; i < tokens.length; i++) {
    const w = tokens[i];
    if (w.length < 4 || STOP.has(w)) continue;
    const prev = last.get(w);
    if (prev !== undefined && i - prev <= 8) return w;
    last.set(w, i);
  }
  return null;
}

/** Worth one model request: Harper objected, or the local cues agree. */
export function isLineCandidate(
  findings: readonly LineFinding[],
  text: string,
): boolean {
  if (!text.trim() || wordCount(text) < 4) return false;
  if (findings.some((f) => f.source === "harper")) return true;
  const local = findings.filter((f) => f.source === "local");
  if (local.length >= 2) return true;
  return wordCount(text) >= VERY_LONG_WORDS;
}

/** The card's one-line reason, from the findings. */
export function lineReason(findings: readonly LineFinding[]): string {
  const harper = findings.filter((f) => f.source === "harper");
  const local = findings.filter((f) => f.source === "local");
  const parts = [
    harper.length ? `Harper: ${harper.map((f) => f.label).join("; ")}` : "",
    local.map((f) => f.label).join(", "),
  ].filter(Boolean);

  ].filter(Boolean);
  const text = parts.join(" · ");
  return text ? text[0].toUpperCase() + text.slice(1) + "." : "Reads oddly.";
}

/* ── Asking for rewrites ──────────────────────────────────────── */

/** The exact texts one request was about. */
export interface LineBinding {
  original: string;
  /** The surrounding paragraph text, without the sentence. */
  before: string;
  after: string;
}
export interface LineRewrite {
