const NUMBER = /\d[\d.,:%/-]*/g;

/**
 * Code-owned limits on a rewrite of `original`. The writer's numbers are not
 * a model's to drop; a rewrite that loses one is refused. Grammar is never a
 * gate here.
 */
export function acceptLineRewrite(
  original: string,
  candidate: unknown,
): string | null {
  if (typeof candidate !== "string") return null;
  const text = squashWording(candidate);
  const source = squashWording(original);
  if (!text || text === source) return null;
  if (text.length > REVISION_MAX_CHARS) return null;
  if (text.length > source.length * 2.5 + 20) return null;
  if (!/[\p{L}\p{N}]/u.test(text)) return null;
  const numbers: string[] = source.match(NUMBER) ?? [];
  const kept: string[] = text.match(NUMBER) ?? [];
  for (const n of numbers) {
    const i = kept.indexOf(n);
    if (i < 0) return null;
    kept.splice(i, 1);
  }
  return text;
}

const cleanLabel = (value: unknown): string => {
  const label =
    typeof value === "string"
      ? squashWording(value)
          .replace(/[.:]+$/, "")
          .slice(0, 40)
