 * rewrites has said the sentence is fine; that is a normal answer.
 */
export function parseLineRewrites(
  raw: string,
  original: string,
): LineRewriteResult {
  const start = raw.indexOf("{"),
    end = raw.lastIndexOf("}");
  let data: unknown;
  try {
    data =
      start >= 0 && end > start ? JSON.parse(raw.slice(start, end + 1)) : null;
  } catch {
    data = null;
  }
  const list = (data as { rewrites?: unknown } | null)?.rewrites;
  if (!Array.isArray(list)) return { ok: false, reason: "malformed" };
  const noteRaw = (data as { note?: unknown }).note;
  const note =
    typeof noteRaw === "string" ? squashWording(noteRaw).slice(0, 300) : "";
  const rewrites: LineRewrite[] = [];
  const seen = new Set<string>();
  let dropped = 0;
  for (const item of list) {
    const o = (item ?? {}) as Record<string, unknown>;
    const text = acceptLineRewrite(original, o.text);
    const key = text?.toLocaleLowerCase();
    if (!text || !key || seen.has(key)) {
      dropped++;
      continue;
    }
    seen.add(key);
    if (rewrites.length < MAX_LINE_REWRITES)
      rewrites.push({ label: cleanLabel(o.label), text });
  }
  return { ok: true, note, rewrites, dropped };
}

/* ── Remembering ──────────────────────────────────────────────── */

/** FNV-1a over the squashed wording: small, stable, and not the text itself. */
export function wordingKey(text: string): string {
  const s = squashWording(text);
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, "0") + s.length.toString(36);
}

export interface LeftWording {
  key: string;
  at: number;
}

/** Whatever storage held, as a list; anything malformed is forgotten. */
export function readLeftWordings(raw: unknown): LeftWording[] {
  if (!Array.isArray(raw)) return [];
  return raw.filter(
    (e): e is LeftWording =>
      !!e &&
      typeof e === "object" &&
      typeof (e as LeftWording).key === "string" &&
      typeof (e as LeftWording).at === "number",
  );
}

export function wasLeft(left: readonly LeftWording[], text: string): boolean {
  const key = wordingKey(text);
  return left.some((e) => e.key === key);
}

/** "Leave it" for this exact wording, kept most-recent-first within the limit. */
export function rememberLeft(
  left: readonly LeftWording[],
  text: string,
  now: number,
): LeftWording[] {
  const key = wordingKey(text);
  return [{ key, at: now }, ...left.filter((e) => e.key !== key)].slice(
    0,
    LEAVE_MEMORY_LIMIT,
