export type LineEntry =
  | { status: "clean"; findings: LineFinding[]; at: number }
  | { status: "candidate"; findings: LineFinding[]; at: number }
  | {
      status: "ready";
      findings: LineFinding[];
      note: string;
      rewrites: LineRewrite[];
      at: number;
    }
  | { status: "no-provider"; findings: LineFinding[]; at: number }
  | { status: "failed"; findings: LineFinding[]; at: number }
  /** The writer used a rewrite; its text is theirs now and is not reread. */
  | { status: "applied"; findings: LineFinding[]; at: number };

/** Results by exact wording, most recent kept. A wording is read once. */
export class LineCache {
  private readonly map = new Map<string, LineEntry>();
  constructor(private readonly limit = 200) {}
  get(text: string): LineEntry | undefined {
    const key = squashWording(text);
    const entry = this.map.get(key);
    if (entry) {
      this.map.delete(key);
      this.map.set(key, entry);
    }
    return entry;
  }
  set(text: string, entry: LineEntry): void {
    const key = squashWording(text);
    this.map.delete(key);
    this.map.set(key, entry);
    while (this.map.size > this.limit)
      this.map.delete(this.map.keys().next().value!);
  }
  get size(): number {
    return this.map.size;
  }
}

