async function installTransport(page: Page) {
  const lineRequests: WireRequest[] = [];
  await page.route(/\/api\/auth\//, (route) =>
    route.fulfill({ contentType: "application/json", body: "null" }),
  );
  await page.route("**/api/provider/", async (route) => {
    expect(route.request().headers()["x-twyne-provider-url"]).toBe(
      `${REPLY_ENDPOINT}/chat/completions`,
    );
    const request = route.request().postDataJSON() as WireRequest;
    const system =
      request.messages.find((m) => m.role === "system")?.content ?? "";
    const prompt =
      request.messages.find((m) => m.role === "user")?.content ?? "";
    if (request.model === "fixture-line-not-live") {
      expect(system).toContain("You are a line editor inside a writing app");
      expect(prompt).toContain(`SENTENCE:\n${ODD}`);
      lineRequests.push(request);
      await route.fulfill(
        completion(
          request.model,
          JSON.stringify({
            note: "Browser fixture note: the opener hangs.",
            rewrites: REWRITES,
          }),
          request.stream,
        ),
      );
      return;
    }
    // Anything else the editor asks of the provider while live review is on
    // gets an empty, well-formed answer; nothing leaves the fixture.
    await route.fulfill(completion(request.model, "{}", request.stream));
  });
  return lineRequests;
}

async function seed(page: Page) {
  await page.route("**/__line-editor-seed", (route) =>
    route.fulfill({
      contentType: "text/html",
      body: "<!doctype html><title>Fictional line editor fixture</title>",
    }),
  );
  await page.goto("/__line-editor-seed");
  await page.evaluate(
    async ({ html, folioId, replyEndpoint }) => {
      const dbPath = "/src/utils/idb.ts";
      const db = await import(/* @vite-ignore */ dbPath);
      const now = Date.now();
      await db.saveFoliosToIdb([
        {
          id: folioId,
          name: "The map and the ledger",
          type: "draft",
          createdAt: now,
          updatedAt: now,
        },
      ]);
      await db.saveFolioContentToIdb(folioId, html);
      await db.saveActiveFolioIdToIdb(folioId);
      await db.saveAiSettingsToIdb({
        advancedMode: true,
        defaultProviderId: "fixture-prose",
        providers: [
          {
            id: "fixture-prose",
            name: "Browser transport fixture — not live",
            type: "openai-compatible",
            apiKey: "fictional-fixture-key-not-a-secret",
            baseUrl: replyEndpoint,
            defaultModel: "fixture-prose-not-live",
            apiMode: "chat",
          },
        ],
        perFeature: { "in-flow-tool": { model: "fixture-line-not-live" } },
        showProviderTags: true,
      });
      // The loop runs under the live-review switch, so it stays on here.
      await db.saveMetaToIdb("live-review-enabled", true);
      await db.saveMetaToIdb("signin-toast-dismissed", true);
      localStorage.setItem("living-desk-open", "false");
      localStorage.setItem(
        "twyne:editor:view:v1",
        JSON.stringify({ zenMode: false, compositorOpen: false }),
      );
    },
    {
      html: INSTRUMENT_MANUSCRIPT,
      folioId: FOLIO_ID,
      replyEndpoint: REPLY_ENDPOINT,
    },
  );
  await page.goto("/editor/");
  await expect(manuscript(page)).toContainText(INSTRUMENT_SENTENCE, {
    timeout: 60_000,
  });
  await page.evaluate(() => document.fonts.ready);
}

/** Type a sentence at the end of the first paragraph and move the caret off it. */
async function typeOdd(page: Page) {
  const paragraph = manuscript(page).locator("p").first();
  await paragraph.click();
  await page.keyboard.press("End");
  await page.keyboard.type(` ${ODD}`);
  await expect(paragraph).toContainText(ODD);
  await page.keyboard.press("ArrowUp");
}

async function capture(page: Page, info: TestInfo, name: string) {
  const path = info.outputPath(`${name}.png`);
  await page.screenshot({ path, animations: "disabled" });
  await info.attach(name, { path, contentType: "image/png" });
}

