test("Line edits reads a typed sentence, offers rewrites, applies one in one undo step, and remembers Leave it across a reload", async ({
  page,
}, info) => {
  const lineRequests = await installTransport(page);
  await seed(page);

  await typeOdd(page);
  // The loop read the settled sentence once and underlined it.
  await expect(underlined(page)).toHaveText(ODD, { timeout: 30_000 });
  expect(lineRequests).toHaveLength(1);
  expect(card(page)).toHaveCount(0);
  await capture(page, info, "line-edits-underline");

  // Resting the caret in it opens the card by itself.
  await underlined(page).click();
  await expect(card(page)).toBeVisible({ timeout: 10_000 });
  await expect(card(page).locator(".line-editor-original")).toHaveText(ODD);
  await expect(card(page).locator(".line-editor-note")).toHaveText(
    "Browser fixture note: the opener hangs.",
  );
  const rewrites = card(page).locator(".line-editor-rewrite");
  await expect(rewrites).toHaveCount(3);
  await expect(rewrites.locator(".line-editor-rewrite__label")).toHaveText(
    REWRITES.map((r) => r.label),
  );
  await expect(rewrites.first().locator("ins").first()).toBeVisible();
  const reason = page.locator(".in-flow-card__reason");
  await expect(reason).toContainText("repeats “quiet”");
  await capture(page, info, "line-edits-card");
  expect(lineRequests).toHaveLength(1);

  // Use applies the rewrite; one undo brings the sentence back.
  const paragraph = manuscript(page).locator("p").first();
  const before = await paragraph.textContent();
  await rewrites
    .nth(1)
    .getByRole("button", { name: /^Use this rewrite/ })
    .click();
  await expect(paragraph).toContainText(REWRITES[1].text);
  await expect(paragraph).not.toContainText(ODD);
  await expect(card(page)).toHaveCount(0);
  await manuscript(page).focus();
  await page.keyboard.press("ControlOrMeta+z");
  await expect(paragraph).toHaveText(before!);
  await expect(paragraph).not.toContainText(REWRITES[1].text);

  // Back on the same wording, the cache answers; no second request.
  await page.keyboard.press("ArrowUp");
  await expect(underlined(page)).toHaveText(ODD, { timeout: 10_000 });
  await underlined(page).click();
  await expect(card(page)).toBeVisible({ timeout: 10_000 });
  expect(lineRequests).toHaveLength(1);

  // Leave it: the card closes, the underline goes, and the memory is kept.
  await card(page)
    .getByRole("button", { name: "Leave it", exact: true })
    .click();
  await expect(card(page)).toHaveCount(0);
  await expect(underlined(page)).toHaveCount(0);
  await expect(paragraph).toHaveText(before!);

  // After a reload the same wording, typed again, is never raised or asked about.
  await page.waitForTimeout(1500);
  await page.reload();
  await expect(manuscript(page)).toContainText(INSTRUMENT_SENTENCE, {
    timeout: 60_000,
  });
  const requestsBeforeRetype = lineRequests.length;
  const last = manuscript(page).locator("p").last();
  await last.click();
  await page.keyboard.press("End");
  await page.keyboard.press("Enter");
  await page.keyboard.type(ODD);
  await page.keyboard.press("ArrowUp");
  await page.waitForTimeout(4000);
  expect(lineRequests).toHaveLength(requestsBeforeRetype);
  await expect(underlined(page)).toHaveCount(0);
  await expect(card(page)).toHaveCount(0);
});
